{"command": "cd /workspace && python3 - <<'EOF'
import subprocess
def run(q):
    out = subprocess.run(["./executable","-c",q],capture_output=True).stdout.decode('utf-8')
    return out.split('\n')
for q in ["SELECT '日' AS x", "SELECT '日本' AS xy", "SELECT '日' AS x, 'a' AS y", "SELECT 'a' AS x", "SELECT '日本' AS x"]:
    print("Q:", q)
    for i,l in enumerate(run(q)):
        print("   ", i, repr(l), "len=",len(l))
EOF"}

