import subprocess
def w(cp):
    q = "SELECT '%s' AS x" % chr(cp)
    out = subprocess.run(["./executable","-c",q],capture_output=True).stdout.decode('utf-8').split('\n')
    inner = out[4][2:-2]
    pad = len(inner) - len(inner.rstrip(' '))
    return 7 - pad
for cp in [0x1F3FA,0x1F3FB,0x1F3FF,0x1F400,0x1F5FF,0x1F600,0x1FFFC,0x1FFFD,0x1FFFE,0x2FFFC,0x2FFFD,0x30000,0x2FFFF,0xE0200,0xF0000,0xF0FFD,0xFFFFD,0x10FFFD,0x10FFFE]:
    try:
        print("U+%05X -> %d" % (cp, w(cp)))
    except Exception as e:
        print("U+%05X -> ERR" % cp)
EOF"}

