namespace ddb {

size_t utf8_char_len(unsigned char c) {
	if (c < 0x80) return 1;
	if ((c & 0xE0) == 0xC0) return 2;
	if ((c & 0xF0) == 0xE0) return 3;
	if ((c & 0xF8) == 0xF0) return 4;
	return 1;
}

uint32_t utf8_next(const std::string &s, size_t &pos, bool *valid) {
	if (valid) *valid = true;
	if (pos >= s.size()) return 0;
	unsigned char c = (unsigned char)s[pos];
	size_t l = utf8_char_len(c);
	if (l > s.size() - pos) l = s.size() - pos;
	uint32_t cp = 0;
	bool ok = true;
	if (l == 1) {
		cp = c;
	} else if (l == 2) {
		cp = c & 0x1F; ok = ((c & 0xC0) == 0xC0);
	} else if (l == 3) {
		cp = c & 0x0F; ok = ((c & 0xE0) == 0xE0);
	} else {
		cp = c & 0x07; ok = ((c & 0xF8) == 0xF0);
	}
	for (size_t i = 1; i < l; i++) {
		unsigned char cc = (unsigned char)s[pos + i];
		if ((cc & 0xC0) != 0x80) ok = false;
		cp = (cp << 6) | (cc & 0x3F);
	}
	if (!ok) cp = c;
	pos += l;
	if (valid) *valid = ok;
	return cp;
}

size_t utf8_codepoints(const std::string &s) {
	size_t pos = 0, n = 0;
	while (pos < s.size()) { utf8_next(s, pos); n++; }
	return n;
}

