static bool in_ranges(uint32_t cp, const Range *ranges, size_t n) {
	if (n == 0 || cp < ranges[0].lo) return false;
	size_t lo = 0, hi = n - 1;
	while (lo <= hi) {
		size_t mid = (lo + hi) / 2;
		if (cp < ranges[mid].lo) {
			if (mid == 0) return false;
			hi = mid - 1;
		} else if (cp > ranges[mid].hi) {
			lo = mid + 1;
		} else return true;
	}
	return false;
}

int utf8_codepoint_width(uint32_t cp) {
	if (cp < 0x300) return 1;
	if (cp < 0x1100) {
		if (in_ranges(cp, kZeroWidth, sizeof(kZeroWidth) / sizeof(Range))) return 0;
		return 1;
	}
	if (in_ranges(cp, kZeroWidth, sizeof(kZeroWidth) / sizeof(Range))) return 0;
	if (in_ranges(cp, kWide, sizeof(kWide) / sizeof(Range))) return 2;
	return 1;
}

int utf8_display_width(const std::string &s) {
	size_t pos = 0;
	int w = 0;
	while (pos < s.size()) {
		uint32_t cp = utf8_next(s, pos);
		w += utf8_codepoint_width(cp);
	}
	return w;
}

size_t utf8_truncate_cp(const std::string &s, size_t max_cp) {
	size_t pos = 0, n = 0;
	while (pos < s.size()) {
		size_t before = pos;
		utf8_next(s, pos);
		if (n >= max_cp) return before;
		n++;
	}
	return s.size();
}

std::string utf8_truncate(const std::string &s, size_t max_cp) {
	size_t e = utf8_truncate_cp(s, max_cp);
	return s.substr(0, e);
}

std::string escape_string(const std::string &s) {
	std::string out;
	out.reserve(s.size());
	for (size_t i = 0; i < s.size(); i++) {
		unsigned char c = (unsigned char)s[i];
		switch (c) {
		case '\a': out += "\\a"; break;
		case '\b': out += "\\b"; break;
		case '\t': out += "\\t"; break;
		case '\n': out += "\\n"; break;
		case '\v': out += "\\v"; break;
		case '\f': out += "\\f"; break;
		case '\r': out += "\\r"; break;
		case 0x1b: out += "\\e"; break;
		default:
			if (c < 0x20) {
				char buf[16];
				snprintf(buf, sizeof(buf), "\\%d", (int)c);
				out += buf;
			} else out += (char)c;
		}
	}
	return out;
}

std::string to_lower(const std::string &s) {
	std::string o = s;
	for (auto &c : o) if (c >= 'A' && c <= 'Z') c += 32;
	return o;
}
std::string to_upper(const std::string &s) {
	std::string o = s;
	for (auto &c : o) if (c >= 'a' && c <= 'z') c -= 32;
	return o;
}
bool iequals(const std::string &a, const std::string &b) {
	if (a.size() != b.size()) return false;
	for (size_t i = 0; i < a.size(); i++) {
		char x = a[i], y = b[i];
		if (x >= 'A' && x <= 'Z') x += 32;
		if (y >= 'A' && y <= 'Z') y += 32;
		if (x != y) return false;
	}
	return true;
}

std::vector<std::string> split_string(const std::string &s, char sep) {
	std::vector<std::string> out;
	size_t pos = 0;
	while (true) {
		size_t e = s.find(sep, pos);
		if (e == std::string::npos) { out.push_back(s.substr(pos)); break; }
		out.push_back(s.substr(pos, e - pos));
		pos = e + 1;
	}
	return out;
}
std::string join_string(const std::vector<std::string> &v, const std::string &sep) {
	std::string o;
	for (size_t i = 0; i < v.size(); i++) {
		if (i) o += sep;
		o += v[i];
	}
	return o;
}
std::string trim_ws(const std::string &s) {
	size_t a = 0, b = s.size();
	while (a < b && isspace((unsigned char)s[a])) a++;
	while (b > a && isspace((unsigned char)s[b - 1])) b--;
	return s.substr(a, b - a);
}
std::string string_replace(const std::string &s, const std::string &from, const std::string &to) {
	if (from.empty()) return s;
	std::string o;
	size_t pos = 0;
	while (true) {
		size_t e = s.find(from, pos);
		if (e == std::string::npos) { o += s.substr(pos); break; }
		o += s.substr(pos, e - pos) + to;
		pos = e + from.size();
	}
	return o;
}

int levenshtein_distance(const std::string &a0, const std::string &b0) {
	std::string a = to_lower(a0), b = to_lower(b0);
	size_t n = a.size(), m = b.size();
	if (n == 0) return (int)m;
	if (m == 0) return (int)n;
	std::vector<int> prev(m + 1), cur(m + 1);
	for (size_t j = 0; j <= m; j++) prev[j] = (int)j;
	for (size_t i = 1; i <= n; i++) {
		cur[0] = (int)i;
		for (size_t j = 1; j <= m; j++) {
			int cost = (a[i - 1] == b[j - 1]) ? 0 : 1;
			cur[j] = std::min({cur[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost});
		}
		std::swap(prev, cur);
	}
	return prev[m];
}

// ------------------------------------------------------------- double fmt
// shortest representation that round-trips, DuckDB style
std::string format_double_full(double v) {
	if (v != v) return "nan";
	if (v == HUGE_VAL) return "inf";
	if (v == -HUGE_VAL) return "-inf";
	char buf[64];
	for (int prec = 1; prec <= 17; prec++) {
		snprintf(buf, sizeof(buf), "%.*g", prec, v);
		if (strtod(buf, nullptr) == v) break;
	}
	std::string s = buf;
	return s;
}

std::string format_double(double v) {
	std::string s = format_double_full(v);
	// DuckDB prints whole numbers with a ".0" suffix
	if (s.find('.') == std::string::npos && s.find('e') == std::string::npos && s.find('n') == std::string::npos && s.find('i') == std::string::npos) {
		s += ".0";
	}
	return s;
}

// ----------------------------------------------------------------- errors
const char *DuckDBException::type_name(Type t) {
	switch (t) {
	case Type::PARSER: return "Parser Error";
	case Type::CATALOG: return "Catalog Error";
	case Type::BINDER: return "Binder Error";
	case Type::CONVERSION: return "Conversion Error";
	case Type::IO: return "IO Error";
	case Type::VALIDATION: return "Validation Error";
	case Type::NOT_IMPLEMENTED: return "Not implemented Error";
	case Type::OUT_OF_RANGE: return "Out of Range Error";
	case Type::EXECUTION: return "Error";
	case Type::INTERNAL: return "Internal Error";
	case Type::CONSTRAINT: return "Constraint Error";
	case Type::FEATURE: return "Feature not supported";
	case Type::UNKNOWN_COMMAND: return "Unknown Command Error";
	case Type::UNKNOWN_OPTION: return "Unknown Option Error";
	case Type::INVALID_INPUT: return "Invalid Input Error";
	case Type::MISMATCHED_TYPE: return "Mismatched Type Error";
	default: return "Error";
	}
}

DuckDBException &DuckDBException::with_location(size_t begin, size_t caret) {
	has_location = true;
	stmt_begin = begin;
	this->caret = caret;
	return *this;
}

std::string DuckDBException::render(size_t stmt_begin, const std::string &stmt) const {
	std::string out = std::string(type_name(type)) + ": " + message;
	if (!has_location) return out;
	// compute line number and offset
	size_t line_no = 1, i = stmt_begin;
	while (i < caret && i < stmt.size()) {
		if (stmt[i] == '\n') line_no++;
		i++;
	}
	size_t line_start = stmt_begin;
	{
		size_t j = stmt_begin;
		while (j < caret && j < stmt.size()) {
			if (stmt[j] == '\n') line_start = j + 1;
			j++;
		}
	}
	size_t line_end = caret;
	{
		size_t j = caret;
		while (j < stmt.size() && stmt[j] != '\n') j++;
		line_end = j;
	}
	std::string text = stmt.substr(line_start, line_end - line_start);
	size_t caret_offset = caret - line_start;
	const size_t max_width = 120;
	if (text.size() > max_width) {
		size_t keep = max_width - 3;
		// cut in the middle
		size_t a = caret_offset > keep / 2 ? caret_offset - keep / 2 : 0;
		std::string head = "...";
		if (a > 0) text = "..." + text.substr(a);
		if (caret_offset >= a) caret_offset = caret_offset - a + 3;
		if (text.size() > max_width) {
			text = text.substr(0, max_width - 3) + "...";
			if (caret_offset > max_width - 3) caret_offset = max_width - 3;
		}
	}
	out += "\n\nLINE " + std::to_string(line_no) + ": " + text;
	out += "\n" + std::string(caret_offset, ' ') + "^";
	return out;
}

[[noreturn]] void throw_parser(const std::string &msg) { throw DuckDBException(DuckDBException::Type::PARSER, msg); }
[[noreturn]] void throw_parser_at(const std::string &msg, size_t caret) { throw DuckDBException(DuckDBException::Type::PARSER, msg).with_location(0, caret); }
[[noreturn]] void throw_catalog(const std::string &msg) { throw DuckDBException(DuckDBException::Type::CATALOG, msg); }
[[noreturn]] void throw_binder(const std::string &msg) { throw DuckDBException(DuckDBException::Type::BINDER, msg); }
[[noreturn]] void throw_conversion(const std::string &msg) { throw DuckDBException(DuckDBException::Type::CONVERSION, msg); }
[[noreturn]] void throw_not_implemented(const std::string &msg) { throw DuckDBException(DuckDBException::Type::NOT_IMPLEMENTED, msg); }
[[noreturn]] void throw_execution(const std::string &msg) { throw DuckDBException(DuckDBException::Type::EXECUTION, msg); }
[[noreturn]] void throw_validation(const std::string &msg) { throw DuckDBException(DuckDBException::Type::VALIDATION, msg); }
[[noreturn]] void throw_constraint(const std::string &msg) { throw DuckDBException(DuckDBException::Type::CONSTRAINT, msg); }
[[noreturn]] void throw_io(const std::string &msg) { throw DuckDBException(DuckDBException::Type::IO, msg); }

std::string suggestion_for(const std::string &what, const std::vector<std::string> &candidates) {
	int best = -1;
	std::string bestname;
	for (auto &c : candidates) {
		if (iequals(c, what)) continue;
		int d = levenshtein_distance(what, c);
		if (best < 0 || d < best) { best = d; bestname = c; }
	}
	if (best < 0 || best > 2) return "";
	return "Did you mean \"" + bestname + "\"?";
}

