	FLOAT, DOUBLE, DECIMAL, VARCHAR, BLOB, DATE, TIME, TIMESTAMP, TIMESTAMP_TZ,
	INTERVAL, LIST, STRUCT, MAP, ARRAY, UNION, ENUM, UNKNOWN
};

struct LogicalType {
	TId id = TId::UNKNOWN;
	int width = 0;    // decimal
	int scale = 0;    // decimal
	int length = 0;   // array length
	std::vector<LogicalType> children;
	std::vector<std::string> child_names;

	LogicalType() {}
	LogicalType(TId t) : id(t) {}
	bool operator==(const LogicalType &o) const {
		if (id != o.id) return false;
		if (id == TId::DECIMAL) return width == o.width && scale == o.scale;
		if (id == TId::ARRAY) return length == o.length && children == o.children;
		if (children.size() != o.children.size()) return false;
		for (size_t i = 0; i < children.size(); i++) if (!(children[i] == o.children[i])) return false;
		return true;
	}
	bool operator!=(const LogicalType &o) const { return !(*this == o); }
	bool is_numeric() const { return id >= TId::BOOLEAN && id <= TId::UBIGINT && id != TId::BOOLEAN; }
	bool is_integral() const { return (id >= TId::TINYINT && id <= TId::UBIGINT); }
	bool is_decimal() const { return id == TId::DECIMAL; }
	bool is_temporal() const { return id == TId::DATE || id == TId::TIME || id == TId::TIMESTAMP || id == TId::TIMESTAMP_TZ; }
