std::string LogicalType::short_name() const {
	switch (id) {
	case TId::DECIMAL: {
		char buf[64]; snprintf(buf, sizeof(buf), "decimal(%d,%d)", width, scale);
		return buf;
	}
	case TId::LIST: return children.empty() ? std::string("list") : children[0].short_name() + "[]";
	case TId::ARRAY: {
		std::string base = children.empty() ? std::string("unknown") : children[0].short_name();
		char buf[64]; snprintf(buf, sizeof(buf), "[%d]", length);
		return base + buf;
	}
	case TId::STRUCT: {
		std::string o = "struct(";
		for (size_t i = 0; i < children.size(); i++) {
			if (i) o += ", ";
			o += child_names[i] + " " + children[i].sql_name();
		}
		return o + ")";
	}
	case TId::MAP: {
		std::string a = children.size() > 0 ? children[0].sql_name() : std::string("unknown");
		std::string b = children.size() > 1 ? children[1].sql_name() : std::string("unknown");
		return "map(" + a + ", " + b + ")";
	}
	case TId::UNION: {
		std::string o = "union(";
		for (size_t i = 0; i < children.size(); i++) {
			if (i) o += ", ";
			o += child_names[i] + " " + children[i].sql_name();
		}
		return o + ")";
	}
	default: return tid_short_name(id);
	}
}

std::string LogicalType::sql_name() const {
	switch (id) {
	case TId::DECIMAL: {
		char buf[64]; snprintf(buf, sizeof(buf), "DECIMAL(%d,%d)", width, scale);
		return buf;
	}
	case TId::LIST: return (children.empty() ? std::string("UNKNOWN") : children[0].sql_name()) + "[]";
	case TId::ARRAY: {
		std::string base = children.empty() ? std::string("UNKNOWN") : children[0].sql_name();
		char buf[64]; snprintf(buf, sizeof(buf), "[%d]", length);
		return base + buf;
	}
	case TId::STRUCT: {
		std::string o = "STRUCT(";
		for (size_t i = 0; i < children.size(); i++) {
			if (i) o += ", ";
			o += "\"" + child_names[i] + "\" " + children[i].sql_name();
		}
		return o + ")";
	}
	case TId::MAP: {
		std::string a = children.size() > 0 ? children[0].sql_name() : std::string("UNKNOWN");
		std::string b = children.size() > 1 ? children[1].sql_name() : std::string("UNKNOWN");
		return "MAP(" + a + ", " + b + ")";
	}
	default: return tid_sql_name(id);
	}
}

LogicalType LogicalType::integer_by_width(int bytes, bool u) {
	switch (bytes) {
	case 1: return LogicalType(u ? TId::UTINYINT : TId::TINYINT);
	case 2: return LogicalType(u ? TId::USMALLINT : TId::SMALLINT);
	case 4: return LogicalType(u ? TId::UINTEGER : TId::INTEGER);
	case 8: return LogicalType(u ? TId::UBIGINT : TId::BIGINT);
	case 16: return LogicalType(TId::HUGEINT);
	default: return LogicalType(TId::DOUBLE);
	}
}
LogicalType LogicalType::decimal(int w, int s) { LogicalType t(TId::DECIMAL); t.width = w; t.scale = s; return t; }
LogicalType LogicalType::list_type(const LogicalType &t) { LogicalType o(TId::LIST); o.children.push_back(t); return o; }
LogicalType LogicalType::struct_type(std::vector<std::string> names, std::vector<LogicalType> types) {
	LogicalType o(TId::STRUCT); o.child_names = names; o.children = types; return o;
