// ------------------------------------------------------------------ dates
// Howard Hinnant's algorithm
int64_t days_from_civil(int y, int m, int d) {
	y -= m <= 2;
	const int64_t era = (y >= 0 ? y : y - 399) / 400;
	const unsigned yoe = (unsigned)(y - era * 400);
	const unsigned doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + (unsigned)d - 1;
	const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
	return era * 146097 + (int64_t)doe - 719468;
}
void civil_from_days(int64_t z, int &y, int &m, int &d) {
	z += 719468;
	const int64_t era = (z >= 0 ? z : z - 146096) / 146097;
	const unsigned doe = (unsigned)(z - era * 146097);
	const unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
	const int64_t yy = (int64_t)yoe + era * 400;
	const unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
	const unsigned mp = (5 * doy + 2) / 153;
	d = (int)(doy - (153 * mp + 2) / 5 + 1);
	m = (int)(mp < 10 ? mp + 3 : mp - 9);
	y = (int)(yy + (m <= 2));
}

int64_t date_to_epoch_micros(int64_t days) { return days * 86400000000LL; }
int64_t epoch_micros_to_date(int64_t micros) {
	int64_t days = micros / 86400000000LL;
	if (micros < 0 && micros % 86400000000LL != 0) days--;
	return days;
}

bool is_leap(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }
static int days_in_month(int y, int m) {
	static const int d[12] = {31,28,31,30,31,30,31,31,30,31,30,31};
	if (m == 2 && is_leap(y)) return 29;
	if (m < 1 || m > 12) return 0;
	return d[m - 1];
}

bool parse_date_string(const std::string &s0, int64_t &days) {
	std::string s = trim_ws(s0);
	if (s.size() < 8) return false;
	int y = 0, m = 0, d = 0;
	char extra = 0;
	int n = 0;
	if (s.size() >= 11 && (s[4] == '-' || s[4] == '/')) {
		if (sscanf(s.c_str(), "%d-%d-%d%c", &y, &m, &d, &extra) >= 3) n = 3;
	} else if (s.size() >= 8) {
		// YYYYMMDD
		for (int i = 0; i < 8; i++) if (!isdigit((unsigned char)s[i])) return false;
		y = (s[0] - '0') * 1000 + (s[1] - '0') * 100 + (s[2] - '0') * 10 + (s[3] - '0');
		m = (s[4] - '0') * 10 + (s[5] - '0');
		d = (s[6] - '0') * 10 + (s[7] - '0');
		if (s.size() != 8) return false;
		return m >= 1 && m <= 12 && d >= 1 && d <= days_in_month(y, m) && (days = days_from_civil(y, m, d), true);
	} else return false;
	if (n != 3) return false;
	if (m < 1 || m > 12 || d < 1 || d > days_in_month(y, m)) return false;
	days = days_from_civil(y, m, d);
	return true;
}

bool parse_time_string(const std::string &s0, int64_t &micros) {
	std::string s = trim_ws(s0);
	int h = 0, mi = 0, sec = 0;
	double frac = 0;
	char tail[32] = {0};
	int n = 0;
	if (s.size() >= 8) n = sscanf(s.c_str(), "%d:%d:%d%lf%s", &h, &mi, &sec, &frac, tail) ;
	else if (s.size() >= 5) n = sscanf(s.c_str(), "%d:%d%lf%s", &h, &mi, &frac, tail) ;
	else return false;
	if (n >= 3) {
		if (h < 0 || h > 23 || mi < 0 || mi > 59 || sec < 0 || sec > 60) return false;
		double us = frac * 1000000;
		if (us >= 1000000) us = 999999;
		micros = ((int64_t)h * 3600 + mi * 60 + sec) * 1000000 + (int64_t)us;
	} else if (n == 2) {
		if (h < 0 || h > 23 || mi < 0 || mi > 59) return false;
		micros = ((int64_t)h * 3600 + mi * 60) * 1000000;
	} else return false;
	return true;
}

bool parse_timestamp_string(const std::string &s0, int64_t &micros) {
	std::string s = trim_ws(s0);
	// split into date and time
	size_t sep = std::string::npos;
	for (size_t i = 0; i < s.size(); i++) {
		if (s[i] == ' ' || s[i] == 'T' || s[i] == 't') { sep = i; break; }
	}
	int64_t days = 0;
	if (sep == std::string::npos) {
		if (!parse_date_string(s, days)) return false;
		micros = date_to_epoch_micros(days);
		return true;
	}
	if (!parse_date_string(s.substr(0, sep), days)) return false;
	std::string t = trim_ws(s.substr(sep + 1));
	bool tz = false;
	if (t.size() > 1 && (t[t.size() - 1] == 'Z' || t[t.size() - 1] == 'z')) { t = t.substr(0, t.size() - 1); tz = true; }
	else {
		// look for +/-HH:MM at the end
		for (size_t i = t.size(); i > 2; i--) {
			char c = t[i - 1];
			if ((c == '+' || c == '-') && t.size() - i >= 4 && i > 1) {
				std::string tzpart = t.substr(i - 1);
				bool ok = true;
				for (size_t k = 1; k < tzpart.size(); k++) {
					char cc = tzpart[k];
					if (cc == ':' || isdigit((unsigned char)cc)) continue;
					ok = false; break;
				}
				if (ok && tzpart.size() <= 6) { t = t.substr(0, i - 1); tz = true; break; }
			}
		}
	}
	int64_t tm = 0;
	if (!parse_time_string(t, tm)) return false;
	micros = date_to_epoch_micros(days) + tm;
	return true;
}

static std::string pad(int v, int width) {
	char buf[32];
	snprintf(buf, sizeof(buf), "%0*d", width, v);
	return buf;
}

std::string format_date(int64_t days) {
	int y, m, d;
	civil_from_days(days, y, m, d);
	return pad(y, 4) + "-" + pad(m, 2) + "-" + pad(d, 2);
}

static std::string format_micros_part(int64_t micros) {
	int64_t h = micros / 3600000000LL; micros -= h * 3600000000LL;
	int64_t m = micros / 60000000LL; micros -= m * 60000000LL;
	int64_t s = micros / 1000000LL; micros -= s * 1000000LL;
	std::string o = pad((int)h, 2) + ":" + pad((int)m, 2) + ":" + pad((int)s, 2);
	if (micros != 0) {
		std::string frac = pad((int)micros, 6);
		while (frac.size() > 1 && frac.back() == '0') frac.pop_back();
		o += "." + frac;
	}
	return o;
}

std::string format_time(int64_t micros) { return format_micros_part(micros); }

std::string format_timestamp(int64_t micros) {
	int64_t days = micros / 86400000000LL;
	if (micros < 0 && micros % 86400000000LL != 0) days--;
	int64_t rest = micros - days * 86400000000LL;
	return format_date(days) + " " + format_micros_part(rest);
}

int64_t now_micros() {
	struct timeval tv;
	gettimeofday(&tv, nullptr);
	return (int64_t)tv.tv_sec * 1000000 + tv.tv_usec;
}

std::string current_date_str() { return format_date(epoch_micros_to_date(now_micros())); }

// ----------------------------------------------------------------- interval
Value parse_interval(const std::string &text) {
	// parses strings like '1 day', '1 year 2 months', '01:02:03', '1.5 years'
	int64_t months = 0, days = 0, micros = 0;
	std::string s = to_lower(trim_ws(text));
	if (s.empty()) { return Value(); }
	size_t pos = 0;
	bool any = false;
	bool neg = false;
	while (pos < s.size()) {
		while (pos < s.size() && (s[pos] == ' ' || s[pos] == ',')) pos++;
		if (pos >= s.size()) break;
		// HH:MM:SS
		if (isdigit((unsigned char)s[pos]) && s[pos + 1] == ':' && pos + 1 < s.size()) {
			int64_t tm = 0;
			std::string t = s.substr(pos);
			if (!parse_time_string(t, tm)) throw_conversion("Could not convert string '" + text + "' to INTERVAL");
			micros += tm;
			pos = s.size();
			any = true;
			break;
		}
		if (s[pos] == '-') { neg = true; pos++; continue; }
		if (s[pos] == '+') { pos++; continue; }
		if (!isdigit((unsigned char)s[pos])) {
			if (!any) { throw_conversion("Could not convert string '" + text + "' to INTERVAL"); }
			break;
		}
		// number (possibly decimal)
		std::string num;
		while (pos < s.size() && (isdigit((unsigned char)s[pos]) || s[pos] == '.')) num += s[pos++];
		double val = atof(num.c_str());
		bool frac = num.find('.') != std::string::npos;
		while (pos < s.size() && s[pos] == ' ') pos++;
		std::string unit;
		while (pos < s.size() && isalpha((unsigned char)s[pos])) unit += s[pos++];
		if (unit.empty()) {
			// implicit: seconds
			micros += (int64_t)(val * 1000000);
			any = true;
			continue;
		}
		if (unit == "century" || unit == "centuries") months += (int64_t)(val * 1200);
		else if (unit == "decade" || unit == "decades") months += (int64_t)(val * 120);
		else if (unit == "year" || unit == "years") months += (int64_t)val * 12;
		else if (unit == "quarter") months += (int64_t)val * 3;
		else if (unit == "month" || unit == "months") months += (int64_t)val;
		else if (unit == "week" || unit == "weeks") days += (int64_t)val * 7;
		else if (unit == "day" || unit == "days") days += (int64_t)val;
		else if (frac) {
			// fractional parts of time units
			if (unit == "hour" || unit == "hours") micros += (int64_t)(val * 3600000000.0);
			else if (unit == "minute" || unit == "minutes" || unit == "min" || unit == "mins") micros += (int64_t)(val * 60000000.0);
			else if (unit == "second" || unit == "seconds" || unit == "sec" || unit == "secs") micros += (int64_t)(val * 1000000.0);
			else if (unit == "millisecond" || unit == "milliseconds" || unit == "ms") micros += (int64_t)(val * 1000.0);
			else if (unit == "microsecond" || unit == "microseconds" || unit == "us") micros += (int64_t)val;
			else throw_conversion("Could not convert string '" + text + "' to INTERVAL");
		} else if (unit == "hour" || unit == "hours") micros += (int64_t)val * 3600000000LL;
		else if (unit == "minute" || unit == "minutes" || unit == "min" || unit == "mins") micros += (int64_t)val * 60000000LL;
		else if (unit == "second" || unit == "seconds" || unit == "sec" || unit == "secs") micros += (int64_t)val * 1000000LL;
		else if (unit == "millisecond" || unit == "milliseconds" || unit == "ms") micros += (int64_t)val * 1000LL;
		else if (unit == "microsecond" || unit == "microseconds" || unit == "us") micros += (int64_t)val;
		else throw_conversion("Could not convert string '" + text + "' to INTERVAL");
		any = true;
	}
	Value v;
	v.type = LogicalType(TId::INTERVAL);
	v.null = false;
	// stored in kv: months, days, micros
	v.kv = {{"months", Value::integer(months, TId::BIGINT)}, {"days", Value::integer(days, TId::BIGINT)}, {"micros", Value::integer(micros, TId::BIGINT)}};
	return v;
}

std::string format_interval(const Value &v) {
	int64_t months = 0, days = 0, micros = 0;
	if (!v.null) {
		for (auto &p : v.kv) {
			if (p.first == "months") months = p.second.i;
			else if (p.first == "days") days = p.second.i;
			else if (p.first == "micros") micros = p.second.i;
		}
	}
	std::string out;
	if (months != 0) {
		int64_t years = months / 12, rem = months % 12;
		if (years != 0) out += std::to_string(years) + (years == 1 ? " year" : " years") + " ";
		if (rem != 0) out += std::to_string(rem) + (rem == 1 ? " month" : " months") + " ";
	}
	if (days != 0) out += std::to_string(days) + (days == 1 ? " day" : " days") + " ";
	if (micros != 0) out += format_micros_part(micros) + " ";
	out = trim_ws(out);
	if (out.empty()) out = format_micros_part(micros);
	return out;
}

// -------------------------------------------------------------- conversion
Value parse_string_literal(const std::string &raw) {
	// raw includes the quotes
	if (raw.size() < 2) return Value::str("");
	std::string body = raw.substr(1, raw.size() - 2);
	// handle escapes
	std::string out;
	bool has_escape = false;
	for (size_t i = 0; i < body.size(); i++) {
		if (body[i] == '\\' && i + 1 < body.size()) {
			has_escape = true;
			char c = body[i + 1];
			if (c == 'x' || c == 'X') {
				// \xXX hex escape (only valid in blob context)
				out += body[i];
				out += body[i + 1];
				if (i + 2 < body.size()) out += body[i + 2];
				if (i + 3 < body.size()) out += body[i + 3];
				i += 3;
				continue;
			}
			if (c == '\\' || c == '\'' || c == '"' || c == '%' || c == ' ' || c == 0) {
				out += c;
				i++;
				continue;
			}
		}
		out += body[i];
	}
	// collapse '' -> '
	std::string o2;
	for (size_t i = 0; i < out.size(); i++) {
		if (out[i] == '\'' && i + 1 < out.size() && out[i + 1] == '\'') { o2 += '\''; i++; continue; }
		o2 += out[i];
	}
	return Value::str(o2);
}

Value parse_integer_literal(const std::string &digits, bool negative, size_t caret) {
	std::string d = digits;
	// remove underscores
	std::string clean;
	for (char c : d) if (c != '_') clean += c;
	if (clean.size() > 18) {
		// large integer: use __int128
		__int128 v = 0;
		for (char c : clean) v = v * 10 + (c - '0');
		if (negative) v = -v;
		return Value::hugeint(v);
	}
	errno = 0;
	unsigned long long u = strtoull(clean.c_str(), nullptr, 10);
	if (negative) {
		if (u > 9223372036854775807ULL + 1ULL) return Value::hugeint((int64_t)(-u));
		return Value::integer((int64_t)u * -1, u >= 2147483648ULL ? TId::BIGINT : TId::INTEGER);
	}
	if (u > 2147483647ULL) {
		if (u > 9223372036854775807ULL) {
			__int128 v = 0;
			for (char c : clean) v = v * 10 + (c - '0');
			return Value::hugeint(v);
		}
		return Value::integer((int64_t)u, TId::BIGINT);
	}
	return Value::integer((int64_t)u, TId::INTEGER);
}

Value parse_decimal_literal(const std::string &digits0, int int_digits, int frac_digits, bool negative, bool has_dot) {
	std::string digits;
	for (char c : digits0) if (c != '_') digits += c;
	int total = int_digits + frac_digits;
	bool has_frac = frac_digits > 0;
	if (!has_dot && int_digits <= 18) {
		// integer literal
		return parse_integer_literal(digits, negative, 0);
	}
	if (total > 38) {
		// convert to double
		double v = atof(digits.c_str());
		if (negative) v = -v;
		return Value::dbl(v);
	}
	__int128 v = 0;
	for (char c : digits) v = v * 10 + (c - '0');
	if (negative) v = -v;
	return Value::decimalv(v, has_frac ? frac_digits : 0, LogicalType::decimal(total, has_frac ? frac_digits : 0));
}

Value parse_float_literal(const std::string &text) {
	return Value::dbl(atof(text.c_str()));
}

