static std::string hugeint_to_string(__int128 v) {
	if (v == 0) return "0";
	bool neg = v < 0;
	unsigned __int128 u = neg ? (unsigned __int128)(-(v + 1)) + 1 : (unsigned __int128)v;
	std::string digits;
	while (u > 0) {
		digits += (char)('0' + (int)(u % 10));
		u /= 10;
	}
	if (neg) digits += '-';
	std::reverse(digits.begin(), digits.end());
	return digits;
}

std::string huge_to_string(__int128 v) { return hugeint_to_string(v); }

std::string Value::to_string() const {
	if (null) return "NULL";
	switch (type.id) {
	case TId::BOOLEAN: return b ? "true" : "false";
	case TId::TINYINT: case TId::SMALLINT: case TId::INTEGER: case TId::BIGINT:
		return std::to_string(i);
	case TId::UTINYINT: case TId::USMALLINT: case TId::UINTEGER: case TId::UBIGINT: {
		unsigned long long u = (unsigned long long)i;
		return std::to_string(u);
	}
	case TId::HUGEINT: return hugeint_to_string(big);
	case TId::FLOAT: case TId::DOUBLE: return format_double(d);
	case TId::DECIMAL: {
		__int128 unscaled = big;
		int sc = type.scale;
		bool neg = unscaled < 0;
		unsigned __int128 mag = neg ? (unsigned __int128)(-(unscaled + 1)) + 1 : (unsigned __int128)unscaled;
		__int128 scale_v = 1;
		for (int i2 = 0; i2 < sc; i2++) scale_v *= 10;
		unsigned __int128 ip = mag / (unsigned __int128)scale_v;
		unsigned __int128 fp = mag % (unsigned __int128)scale_v;
		std::string out;
		if (ip == 0 && !neg) {
			// DuckDB omits the leading zero for positive fractional decimals
		} else {
			out += hugeint_to_string((__int128)ip);
		}
		if (sc > 0) {
			std::string frac = hugeint_to_string((__int128)fp);
			while (frac.size() < (size_t)sc) frac = "0" + frac;
			out += "." + frac;
		}
		if (out.empty()) out = "0";
		if (neg) out = "-" + out;
		return out;
	}
	case TId::VARCHAR: return s;
	case TId::BLOB: {
		std::string o;
		for (unsigned char c : s) {
			if (c >= 0x20 && c <= 0x7e) o += (char)c;
			else {
				char buf[8]; snprintf(buf, sizeof(buf), "\\x%02X", (int)c);
				o += buf;
			}
		}
		return o;
	}
	case TId::DATE: return format_date(i);
	case TId::TIME: return format_micros_part(i);
	case TId::TIMESTAMP: return format_timestamp(i);
	case TId::TIMESTAMP_TZ: return format_timestamp(i) + "+00";
	case TId::INTERVAL: return format_interval(*this);
	case TId::LIST: case TId::ARRAY: {
		std::string o = "[";
		for (size_t j = 0; j < children.size(); j++) {
			if (j) o += ", ";
			o += children[j].to_string();
		}
		return o + "]";
	}
	case TId::STRUCT: {
		std::string o = "{";
		for (size_t j = 0; j < type.child_names.size(); j++) {
			if (j) o += ", ";
			o += type.child_names[j] + ": " + (j < children.size() ? children[j].to_string() : std::string("NULL"));
		}
		return o + "}";
	}
	case TId::MAP: {
		std::string o = "{";
		for (size_t j = 0; j < kv.size(); j++) {
			if (j) o += ", ";
			o += kv[j].first.to_string() + "=" + kv[j].second.to_string();
		}
		return o + "}";
	}
	default: return "";
	}
}

