	case TId::UTINYINT: case TId::USMALLINT: case TId::UINTEGER: case TId::UBIGINT: return (double)(unsigned long long)i;
	case TId::HUGEINT: return (double)big;
	case TId::FLOAT: case TId::DOUBLE: return d;
	case TId::DECIMAL: {
