int Value::compare(const Value &o) const {
	if (null || o.null) return 2; // incomparable
	TId a = type.id, b = o.type.id;
	bool an = a == TId::BOOLEAN || (a >= TId::TINYINT && a <= TId::UBIGINT) || a == TId::HUGEINT;
	bool bn = b == TId::BOOLEAN || (b >= TId::TINYINT && b <= TId::UBIGINT) || b == TId::HUGEINT;
	if (type.id == TId::DECIMAL || o.type.id == TId::DECIMAL) {
		// compare as decimals
		int sc = std::max(type.id == TId::DECIMAL ? type.scale : 0, o.type.id == TId::DECIMAL ? o.type.scale : 0);
		__int128 v1 = type.id == TId::DECIMAL ? big : (an ? as_big() : (__int128)as_double());
		__int128 v2 = o.type.id == TId::DECIMAL ? o.big : (bn ? o.as_big() : (__int128)o.as_double());
		int s1 = type.id == TId::DECIMAL ? type.scale : 0;
		int s2 = o.type.id == TId::DECIMAL ? o.type.scale : 0;
		for (int i2 = s1; i2 < sc; i2++) v1 *= 10;
		for (int i2 = s2; i2 < sc; i2++) v2 *= 10;
		if (v1 < v2) return -1;
		if (v1 > v2) return 1;
		return 0;
	}
	if ((an || bn) && !((type.id == TId::VARCHAR) || (o.type.id == TId::VARCHAR))) {
		if (type.id == TId::DOUBLE || o.type.id == TId::DOUBLE || type.id == TId::FLOAT || o.type.id == TId::FLOAT) {
			double x = as_double(), y = o.as_double();
			if (x < y) return -1;
			if (x > y) return 1;
			return 0;
		}
		__int128 x = as_big(), y = o.as_big();
		if (x < y) return -1;
		if (x > y) return 1;
		return 0;
	}
	switch (type.id) {
	case TId::VARCHAR: case TId::BLOB: {
		if (o.type.id != TId::VARCHAR && o.type.id != TId::BLOB) {
			return -1; // mixed comparison handled elsewhere
		}
		return s < o.s ? -1 : (s > o.s ? 1 : 0);
	}
	case TId::DATE: case TId::TIME: case TId::TIMESTAMP: case TId::TIMESTAMP_TZ: {
		if (o.type.id == TId::VARCHAR || o.type.id == TId::BLOB) return -1;
		int64_t x = i, y = o.i;
		if (x < y) return -1;
		if (x > y) return 1;
		return 0;
	}
	case TId::INTERVAL: {
		int64_t x = i, y = o.i;
		if (x < y) return -1;
		if (x > y) return 1;
		return 0;
	}
	case TId::LIST: case TId::ARRAY: {
		size_t n = children.size(), m = o.children.size();
		size_t k = std::min(n, m);
		for (size_t j = 0; j < k; j++) {
			int c = children[j].compare(o.children[j]);
			if (c != 0) return c;
		}
		if (n < m) return -1;
		if (n > m) return 1;
		return 0;
	}
	case TId::STRUCT: {
		size_t n = children.size(), m = o.children.size();
		for (size_t j = 0; j < std::min(n, m); j++) {
			int c = children[j].compare(o.children[j]);
			if (c != 0) return c;
		}
		return 0;
	}
	default: {
		double x = as_double(), y = o.as_double();
		if (x < y) return -1;
		if (x > y) return 1;
		return 0;
	}
	}
}

bool Value::equals(const Value &o) const {
	if (null != o.null) return false;
	if (null) return true;
	int c = compare(o);
	if (c == 2) {
		// NULL involvement
