#include "ops.hpp"
#include "value.hpp"

namespace ddb {

// Table of integral promotion results, derived empirically.
// index: 0..4 signed (TINYINT,SMALLINT,INTEGER,BIGINT,HUGEINT), 5..8 unsigned
static const int kSignedIdx[4] = {0,1,2,3};
static const int kUnsignedIdx[4] = {5,6,7,8};
// result for [signed_idx][unsigned_idx]: 0=int8 1=int16 2=int32 3=int64 4=int128 8=uint8 9=uint16 10=uint32 11=uint64
static const int kMix[4][4] = {
	// signed width 1 (TINYINT)
	{3,3,3,4},   // + UTINYINT(1),USMALLINT(2),UINTEGER(4),UBIGINT(8)
	// signed width 2 (SMALLINT)
	{1,3,3,4},
	// signed width 4 (INTEGER)
	{2,2,3,4},
	// signed width 8 (BIGINT)
	{3,3,3,4},
};
static TId id_from_index(int i) {
	switch (i) {
	case 0: return TId::TINYINT;
	case 1: return TId::SMALLINT;
	case 2: return TId::INTEGER;
	case 3: return TId::BIGINT;
	case 4: return TId::HUGEINT;
	case 5: return TId::UTINYINT;
	case 6: return TId::USMALLINT;
	case 7: return TId::UINTEGER;
	case 8: return TId::UBIGINT;
	default: return TId::HUGEINT;
	}
}
static int index_from_id(TId t) {
	switch (t) {
	case TId::TINYINT: return 0;
	case TId::SMALLINT: return 1;
	case TId::INTEGER: return 2;
	case TId::BIGINT: return 3;
	case TId::HUGEINT: return 4;
	case TId::UTINYINT: return 5;
	case TId::USMALLINT: return 6;
	case TId::UINTEGER: return 7;
	case TId::UBIGINT: return 8;
	default: return 4;
	}
}

TId promote_integral(TId a, TId b) {
	int ia = index_from_id(a), ib = index_from_id(b);
	bool ua = tid_is_unsigned(a), ub = tid_is_unsigned(b);
	if (!ua && !ub) {
		return id_from_index(std::max(ia, ib));
	}
	if (ua && ub) {
		// unsigned + unsigned -> wider unsigned, but if either is hugeint -> int128
		if (a == TId::UBIGINT && b == TId::UBIGINT) return TId::UBIGINT;
		return id_from_index(std::max(ia, ib));
	}
	// mixed
	int si = ua ? index_from_id(b) : index_from_id(a);
	int ui = ua ? index_from_id(a) - 5 : index_from_id(b) - 5;
	int sw = tid_width(ua ? b : a);
	int uw = tid_width(ua ? a : b);
	if (sw == 16 || uw == 8) return TId::HUGEINT; // hugeint involved
	if (sw == uw) {
		// equal widths -> 64-bit signed (or 128 for 8 byte unsigned)
		return TId::BIGINT;
	}
	return id_from_index(kMix[sw == 1 ? 0 : sw == 2 ? 1 : sw == 4 ? 2 : 3][uw == 1 ? 0 : uw == 2 ? 1 : uw == 4 ? 2 : 3]);
}

int integral_decimal_width(TId t) {
	switch (t) {
	case TId::TINYINT: case TId::UTINYINT: return 3;
	case TId::SMALLINT: case TId::USMALLINT: return 5;
	case TId::INTEGER: case TId::UINTEGER: return 10;
	case TId::BIGINT: return 19;
	case TId::UBIGINT: return 20;
	case TId::HUGEINT: return 38;
	default: return 18;
	}
}

static bool is_floatish(TId t) { return t == TId::FLOAT || t == TId::DOUBLE; }

LogicalType numeric_op_result(int op, const LogicalType &l, const LogicalType &r) {
	if (l.id == TId::BOOLEAN && r.id == TId::BOOLEAN) return LogicalType(TId::BOOLEAN);
	if (is_floatish(l.id) || is_floatish(r.id)) {
		if (l.id == TId::DOUBLE || r.id == TId::DOUBLE) return LogicalType(TId::DOUBLE);
		return LogicalType(TId::FLOAT);
	}
	if (l.id == TId::DECIMAL || r.id == TId::DECIMAL) {
		if (op == OP_DIV) return LogicalType(TId::DOUBLE);
		// convert the non-decimal side to a decimal type
		int lw = l.id == TId::DECIMAL ? l.width : integral_decimal_width(l.id);
		int ls = l.id == TId::DECIMAL ? l.scale : 0;
		int rw = r.id == TId::DECIMAL ? r.width : integral_decimal_width(r.id);
		int rs = r.id == TId::DECIMAL ? r.scale : 0;
		int maxw = std::max(lw, rw);
		int cap = maxw <= 18 ? 18 : 38;
		int width, scale;
		if (op == OP_MUL) {
			scale = ls + rs;
			width = lw + rw;
		} else {
			scale = std::max(ls, rs);
			width = std::max(lw - ls, rw - rs) + scale + 1;
		}
		if (width > cap) width = cap;
		if (width < scale) width = scale;
		if (width > 38) width = 38;
		if (width < 1) width = 1;
		return LogicalType::decimal(width, scale);
	}
	if (l.is_integral() && r.is_integral()) {
		if (op == OP_DIV) return LogicalType(TId::DOUBLE);
		if (op == OP_POW) return LogicalType(TId::DOUBLE);
		return LogicalType(promote_integral(l.id, r.id));
	}
	if (l.id == TId::VARCHAR || r.id == TId::VARCHAR) return LogicalType(TId::VARCHAR);
	return LogicalType(TId::DOUBLE);
}

LogicalType comparison_type(const LogicalType &l, const LogicalType &r) {
	(void)l; (void)r;
	return LogicalType(TId::BOOLEAN);
}

// -------------------------------------------------------------------- arithmetic
static __int128 decimal_scale(int s) {
	__int128 v = 1;
	for (int i = 0; i < s; i++) v *= 10;
	return v;
}

static bool is_numericish(const Value &v) {
	TId t = v.type.id;
	return t == TId::BOOLEAN || t == TId::TINYINT || t == TId::SMALLINT || t == TId::INTEGER ||
	       t == TId::BIGINT || t == TId::HUGEINT || t == TId::UTINYINT || t == TId::USMALLINT ||
	       t == TId::UINTEGER || t == TId::UBIGINT || t == TId::FLOAT || t == TId::DOUBLE ||
	       t == TId::DECIMAL;
}

// interval helpers
Value add_interval(const Value &interval, const Value &base, bool subtract) {
	if (base.type.id == TId::INTERVAL) {
		// interval + interval
		Value out;
		out.type = LogicalType(TId::INTERVAL);
		out.null = base.null || interval.null;
		int64_t m = 0, d = 0, us = 0;
		auto get = [](const Value &v, const char *key) -> int64_t {
			for (auto &p : v.kv) if (p.first == key) return p.second.i;
			return 0;
		};
		if (!out.null) {
			m = get(base, "months") + (subtract ? -1 : 1) * get(interval, "months");
			d = get(base, "days") + (subtract ? -1 : 1) * get(interval, "days");
			us = get(base, "micros") + (subtract ? -1 : 1) * get(interval, "micros");
		}
		out.kv = {{"months", Value::integer(m, TId::BIGINT)}, {"days", Value::integer(d, TId::BIGINT)}, {"micros", Value::integer(us, TId::BIGINT)}};
		return out;
	}
	if (interval.null || base.null) return Value::nullval(base.type);
	// extract interval parts
	int64_t months = 0, days = 0, micros = 0;
	if (interval.type.id == TId::INTERVAL) {
		for (auto &p : interval.kv) {
			if (p.first == "months") months = p.second.i;
			else if (p.first == "days") days = p.second.i;
			else if (p.first == "micros") micros = p.second.i;
		}
	} else {
		throw_validation("Unexpected type in interval addition");
	}
	int sign = subtract ? -1 : 1;
	TId bt = base.type.id;
	if (bt == TId::DATE) {
		int64_t days = base.i;
		int y, m, d;
		civil_from_days(days, y, m, d);
		// add months
		int64_t total_months = m - 1 + sign * months;
		int64_t ny = y + total_months / 12;
		int nm = (int)(total_months % 12);
		if (nm < 0) { nm += 12; ny--; }
		nm += 1;
		if (nm < 1) { nm += 12; ny--; }
		if (nm > 12) { nm -= 12; ny++; }
		int nd = std::min(d, days_in_month((int)ny, nm));
		int64_t newdays = days_from_civil((int)ny, nm, nd) + sign * days;
		return Value::date(newdays);
	}
	if (bt == TId::TIMESTAMP || bt == TId::TIMESTAMP_TZ) {
		int64_t micros_v = base.i;
		// months: handle via date
		if (months != 0) {
			int64_t day0 = epoch_micros_to_date(micros_v);
			int y, m, d;
			civil_from_days(day0, y, m, d);
			int64_t total_months = m - 1 + sign * months;
			int64_t ny = y + total_months / 12;
			int nm = (int)(total_months % 12);
			if (nm < 0) { nm += 12; ny--; }
			nm += 1;
			if (nm < 1) { nm += 12; ny--; }
			if (nm > 12) { nm -= 12; ny++; }
			int nd = std::min(d, days_in_month((int)ny, nm));
			int64_t newday = days_from_civil((int)ny, nm, nd);
			micros_v = date_to_epoch_micros(newday) + (micros_v - date_to_epoch_micros(day0));
		}
		micros_v += sign * days * 86400000000LL + sign * micros;
		return Value::timestamp(micros_v);
	}
	if (bt == TId::TIME) {
		return Value::time(base.i + sign * micros);
	}
	throw_execution("Unsupported type for interval addition");
	return Value();
}

static int64_t interval_key(const Value &v, const char *key) {
	for (auto &p : v.kv) if (p.first == key) return p.second.i;
	return 0;
}

Value apply_binary_op(int op, const Value &l, const Value &r) {
	if (l.null || r.null) {
		LogicalType t = numeric_op_result(op, l.type, r.type);
		return Value::nullval(t);
	}
	// interval arithmetic
	if (l.type.id == TId::INTERVAL && (op == OP_ADD || op == OP_SUB)) return add_interval(l, r, op == OP_SUB);
	if (r.type.id == TId::INTERVAL && (op == OP_ADD || op == OP_SUB)) return add_interval(r, l, false);
	// date +/- integer (days)
	if ((l.type.id == TId::DATE || l.type.id == TId::TIMESTAMP) && r.is_integral() && (op == OP_ADD || op == OP_SUB)) {
		int64_t v = r.as_int();
		if (l.type.id == TId::DATE) return Value::date(l.i + (op == OP_SUB ? -v : v));
		return Value::timestamp(l.i + (op == OP_SUB ? -v : v) * 86400000000LL);
	}
	if (l.type.id == TId::DATE && r.type.id == TId::DATE && (op == OP_SUB || op == OP_ADD)) {
		// date - date -> interval in days
		Value out;
		out.type = LogicalType(TId::INTERVAL);
		out.null = false;
		out.kv = {{"months", Value::integer(0, TId::BIGINT)}, {"days", Value::integer(l.i - r.i, TId::BIGINT)}, {"micros", Value::integer(0, TId::BIGINT)}};
		return out;
	}
	if (op == OP_ADD && (l.type.id == TId::VARCHAR || r.type.id == TId::VARCHAR)) {
		return Value::str(l.to_string() + r.to_string());
	}
	if (l.type.id == TId::BOOLEAN && r.type.id == TId::BOOLEAN) {
		switch (op) {
		case OP_AND_BIT: return Value::boolean(l.b && r.b);
		case OP_OR_BIT: return Value::boolean(l.b || r.b);
		default: break;
		}
	}
	if (!is_numericish(l) || !is_numericish(r)) {
		throw_execution("Cannot apply operator to these types");
	}
	LogicalType rt = numeric_op_result(op, l.type, r.type);
	// compute
	if (l.type.id == TId::DECIMAL || r.type.id == TId::DECIMAL) {
		int ls = l.type.id == TId::DECIMAL ? l.type.scale : 0;
		int rs = r.type.id == TId::DECIMAL ? r.type.scale : 0;
		__int128 lv = l.type.id == TId::DECIMAL ? l.big : (l.type.id == TId::FLOAT || l.type.id == TId::DOUBLE ? 0 : l.as_big());
		__int128 rv = r.type.id == TId::DECIMAL ? r.big : (r.type.id == TId::FLOAT || r.type.id == TId::DOUBLE ? 0 : r.as_big());
		if (l.type.id != TId::DECIMAL && (l.type.id == TId::FLOAT || l.type.id == TId::DOUBLE)) {
			return Value::dbl(l.d + r.as_double() * (op == OP_SUB ? -1 : 1));
		}
		if (r.type.id != TId::DECIMAL && (r.type.id == TId::FLOAT || r.type.id == TId::DOUBLE)) {
			return Value::dbl(l.as_double() + (op == OP_SUB ? -1 : 1) * r.d);
		}
		int outscale = rt.scale;
		// rescale operands to the output scale
		__int128 a = lv, b = rv;
		if (op == OP_MUL) {
			// result scale = ls + rs
			__int128 v = lv * rv;
			if (ls < outscale) { /* nothing */ }
			return Value::decimalv(v, outscale, rt);
		}
		// align to outscale
		for (int i = ls; i < outscale; i++) a *= 10;
		for (int i = rs; i < outscale; i++) b *= 10;
		for (int i = outscale; i < ls; i++) a /= 10;
		for (int i = outscale; i < rs; i++) b /= 10;
		__int128 v;
		switch (op) {
		case OP_ADD: v = a + b; break;
		case OP_SUB: v = a - b; break;
		default: v = a; break;
		}
		return Value::decimalv(v, outscale, rt);
	}
	if (l.type.id == TId::FLOAT || l.type.id == TId::DOUBLE || r.type.id == TId::FLOAT || r.type.id == TId::DOUBLE) {
		double x = l.as_double(), y = r.as_double();
		switch (op) {
		case OP_ADD: return Value::dbl(x + y);
		case OP_SUB: return Value::dbl(x - y);
		case OP_MUL: return Value::dbl(x * y);
		case OP_DIV: return Value::dbl(x / y);
		case OP_INTDIV: {
			if (rt.id == TId::FLOAT) { Value o(rt); o.null = false; o.d = (float)std::trunc(x / y); return o; }
			return Value::dbl(std::trunc(x / y));
		}
		case OP_MOD: return Value::dbl(std::fmod(x, y));
		case OP_POW: return Value::dbl(std::pow(x, y));
		default: return Value::dbl(0);
		}
	}
	// integral
	__int128 x = l.as_big(), y = r.as_big();
	switch (op) {
	case OP_ADD: {
		if (rt.id == TId::HUGEINT) return Value::hugeint(x + y);
		int64_t a = (int64_t)x, b = (int64_t)y;
		bool unsigned_op = tid_is_unsigned(rt.id);
		if (!unsigned_op) {
			if (__builtin_add_overflow(a, b, &a)) {
				throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Overflow in addition of " + std::string(tid_sql_name(rt.id)) + " (" + l.to_string() + " + " + r.to_string() + ")!");
			}
			return Value::intv(a, rt);
		} else {
			return Value::intv(a + b, rt);
		}
	}
	case OP_SUB: {
		if (rt.id == TId::HUGEINT) return Value::hugeint(x - y);
		int64_t a = (int64_t)x, b = (int64_t)y;
		bool unsigned_op = tid_is_unsigned(rt.id);
		if (!unsigned_op) {
			if (__builtin_sub_overflow(a, b, &a)) {
				throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Overflow in subtraction of " + std::string(tid_sql_name(rt.id)) + " (" + l.to_string() + " - " + r.to_string() + ")!");
			}
			return Value::intv(a, rt);
		} else {
			if (a - b < 0) {
				throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Overflow in subtraction of " + std::string(tid_sql_name(rt.id)) + " (" + l.to_string() + " - " + r.to_string() + ")!");
			}
			return Value::intv(a - b, rt);
		}
	}
	case OP_MUL: {
		if (rt.id == TId::HUGEINT) return Value::hugeint(x * y);
		int64_t a = (int64_t)x, b = (int64_t)y, c;
		if (__builtin_mul_overflow(a, b, &c)) {
			throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Overflow in multiplication of " + std::string(tid_sql_name(rt.id)) + " (" + l.to_string() + " * " + r.to_string() + ")!");
		}
		return Value::intv(c, rt);
	}
	case OP_DIV: return Value::dbl((double)x / (double)y);
	case OP_INTDIV: {
		if (y == 0) throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Division by zero!");
		__int128 v = x / y;
		if (rt.id == TId::HUGEINT) return Value::hugeint(v);
		return Value::intv((int64_t)v, rt);
	}
	case OP_MOD: {
		if (y == 0) throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Division by zero!");
		__int128 v = x % y;
		if (rt.id == TId::HUGEINT) return Value::hugeint(v);
		return Value::intv((int64_t)v, rt);
	}
	case OP_POW: return Value::dbl(std::pow((double)x, (double)y));
	case OP_AND_BIT: case OP_OR_BIT: case OP_SHL: case OP_SHR: {
		__int128 v = 0;
		switch (op) {
		case OP_AND_BIT: v = x & y; break;
		case OP_OR_BIT: v = x | y; break;
		case OP_SHL: v = x << (uint64_t)y; break;
		case OP_SHR: v = x >> (uint64_t)y; break;
		}
		if (rt.id == TId::HUGEINT) return Value::hugeint(v);
		return Value::intv((int64_t)v, rt);
	}
	default: return Value();
	}
}

Value apply_unary_op(int op, const Value &v) {
	if (v.null) return Value::nullval(v.type);
	switch (op) {
	case OP_SUB: // negation
		switch (v.type.id) {
		case TId::DECIMAL: return Value::decimalv(-v.big, v.type.scale, v.type);
		case TId::FLOAT: case TId::DOUBLE: return Value::dbl(-v.d);
		case TId::HUGEINT: return Value::hugeint(-v.big);
		default:
			if (v.type.is_integral() && tid_is_unsigned(v.type.id)) {
				throw DuckDBException(DuckDBException::Type::OUT_OF_RANGE, "Overflow in negation of " + std::string(tid_sql_name(v.type.id)) + " (" + v.to_string() + ")!");
			}
			return Value::intv(-v.i, v.type);
		}
	case OP_ADD: return v;
	default: return v;
	}
}

Value apply_comparison(int op, const Value &l, const Value &r) {
	LogicalType bt(TId::BOOLEAN);
	if (l.null || r.null) return Value::nullval(bt);
	int c = l.compare(r);
	// cross-type: fall back to string comparison
	if (c == 2) {
		std::string a = l.to_string(), b = r.to_string();
		c = a < b ? -1 : (a > b ? 1 : 0);
	}
	switch (op) {
	case 0: return Value::boolean(c == 0);
	case 1: return Value::boolean(c != 0);
	case 2: return Value::boolean(c < 0);
	case 3: return Value::boolean(c <= 0);
	case 4: return Value::boolean(c > 0);
	case 5: return Value::boolean(c >= 0);
	}
	return Value::nullval(bt);
}

Value apply_logical(int op, const Value &l, const Value &r) {
	LogicalType bt(TId::BOOLEAN);
	if (op == 0) { // AND
		if ((!l.null && !l.b) || (!r.null && !r.b)) return Value::boolean(false);
		if (l.null || r.null) return Value::nullval(bt);
		return Value::boolean(true);
	}
	if (op == 1) { // OR
		if ((!l.null && l.b) || (!r.null && r.b)) return Value::boolean(true);
		if (l.null || r.null) return Value::nullval(bt);
		return Value::boolean(false);
	}
	return Value::nullval(bt);
}

