// ------------------------------------------------------------------- casting
static const char *phys_name(TId t) {
	switch (t) {
	case TId::BOOLEAN: return "BOOL";
	case TId::TINYINT: return "INT8";
	case TId::SMALLINT: return "INT16";
	case TId::INTEGER: return "INT32";
	case TId::BIGINT: return "INT64";
	case TId::HUGEINT: return "INT128";
	case TId::UTINYINT: return "UINT8";
	case TId::USMALLINT: return "UINT16";
	case TId::UINTEGER: return "UINT32";
	case TId::UBIGINT: return "UINT64";
	case TId::FLOAT: return "FLOAT";
	case TId::DOUBLE: return "DOUBLE";
	case TId::DECIMAL: return "DECIMAL";
	case TId::VARCHAR: return "VARCHAR";
	case TId::BLOB: return "BLOB";
	case TId::DATE: return "DATE";
	case TId::TIME: return "TIME";
	case TId::TIMESTAMP: return "TIMESTAMP";
	case TId::TIMESTAMP_TZ: return "TIMESTAMP WITH TIME ZONE";
	case TId::INTERVAL: return "INTERVAL";
	case TId::LIST: return "LIST";
	case TId::STRUCT: return "STRUCT";
	case TId::MAP: return "MAP";
	default: return "UNKNOWN";
	}
}
const char *physical_type_name(TId t) { return phys_name(t); }

static double round_half_away(double d) { return d < 0 ? -std::floor(-d + 0.5) : std::floor(d + 0.5); }

static __int128 parse_bigint_str(const std::string &s, bool &ok) {
	std::string t = trim_ws(s);
	ok = true;
	if (t.empty()) { ok = false; return 0; }
	size_t i = 0;
	bool neg = false;
	if (t[0] == '-') { neg = true; i++; }
	else if (t[0] == '+') i++;
	if (i >= t.size()) { ok = false; return 0; }
	__int128 v = 0;
	for (; i < t.size(); i++) {
		char c = t[i];
		if (c == '_') continue;
		if (c < '0' || c > '9') { ok = false; return 0; }
		v = v * 10 + (c - '0');
	}
	return neg ? -v : v;
}

static double parse_double_str(const std::string &s, bool &ok) {
	std::string t = trim_ws(s);
	ok = true;
	if (t.empty()) { ok = false; return 0; }
	if (t == "inf" || t == "Inf" || t == "INF" || t == "Infinity" || t == "infinity") return HUGE_VAL;
	if (t == "-inf" || t == "-Inf" || t == "-INF" || t == "-Infinity" || t == "-infinity") return -HUGE_VAL;
	if (t == "nan" || t == "NaN" || t == "NAN") return 0.0 / 0.0;
	const char *c = t.c_str();
	char *end = nullptr;
	double v = strtod(c, &end);
	if (end == c) { ok = false; return 0; }
	while (*end == ' ' || *end == '\t') end++;
	if (*end != 0) { ok = false; return 0; }
	return v;
}

// blob escape decoding: \xXX
static std::string blob_decode(const std::string &s, bool &ok) {
	std::string out;
	ok = true;
	for (size_t i = 0; i < s.size(); i++) {
		if (s[i] == '\\' && i + 1 < s.size() && (s[i + 1] == 'x' || s[i + 1] == 'X')) {
			if (i + 3 >= s.size()) { ok = false; return ""; }
			int hi = -1, lo = -1;
			auto hexval = [](char c) -> int {
				if (c >= '0' && c <= '9') return c - '0';
				if (c >= 'a' && c <= 'f') return c - 'a' + 10;
				if (c >= 'A' && c <= 'F') return c - 'A' + 10;
				return -1;
			};
			hi = hexval(s[i + 2]);
			lo = hexval(s[i + 3]);
			if (hi < 0 || lo < 0) { ok = false; return ""; }
			out += (char)(hi * 16 + lo);
			i += 3;
			continue;
		}
		unsigned char c = (unsigned char)s[i];
		if (c >= 0x80) {
			ok = false;
			return "";
		}
		out += (char)c;
	}
	return out;
}

// parse a DuckDB list/struct literal from a string
Value parse_nested_literal(const std::string &s, const LogicalType &target);

Value do_cast(const Value &v, const LogicalType &target) {
	if (target.id == v.type.id) {
		if (target.id == TId::DECIMAL && target.scale != v.type.scale) {
			// rescale
			if (v.null) return Value::nullval(target);
			int ds = target.scale - v.type.scale;
			__int128 big = v.big;
			if (ds > 0) {
				for (int i = 0; i < ds; i++) big *= 10;
			} else {
				for (int i = 0; i < -ds; i++) big /= 10;
			}
			Value o(target);
			o.null = false;
			o.big = big;
			return o;
		}
		return v;
	}
	if (v.null) return Value::nullval(target);
	TId src = v.type.id, dst = target.id;
	switch (dst) {
	case TId::BOOLEAN: {
		if (src == TId::BOOLEAN) return Value::boolean(v.b);
		if (src == TId::VARCHAR) {
			std::string t = to_lower(trim_ws(v.s));
			if (t == "true" || t == "t" || t == "1" || t == "yes") return Value::boolean(true);
			if (t == "false" || t == "f" || t == "0" || t == "no") return Value::boolean(false);
			throw_conversion("Could not convert string '" + v.s + "' to BOOL");
		}
		if (is_numericish(v)) return Value::boolean(v.as_double() != 0);
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> BOOL)");
	}
	case TId::TINYINT: case TId::SMALLINT: case TId::INTEGER: case TId::BIGINT: case TId::HUGEINT:
	case TId::UTINYINT: case TId::USMALLINT: case TId::UINTEGER: case TId::UBIGINT: {
		__int128 out = 0;
		if (src == TId::VARCHAR) {
			bool ok = false;
			out = parse_bigint_str(v.s, ok);
			if (!ok) throw_conversion("Could not convert string '" + v.s + "' to " + phys_name(dst));
		} else if (src == TId::FLOAT || src == TId::DOUBLE) {
			double d = round_half_away(v.d);
			out = (__int128)d;
			if (src == TId::DOUBLE) {
				if (!(d >= -9.0e18 && d <= 9.0e18) && dst != TId::HUGEINT) {
					if (d != d) throw_conversion("Could not cast value nan to " + std::string(phys_name(dst)));
					throw_conversion("Type DOUBLE with value " + format_double(v.d) + " can't be cast because the value is out of range for the destination type " + phys_name(dst));
				}
			}
		} else if (src == TId::DECIMAL) {
			// round to nearest integer
			__int128 sc = decimal_scale(v.type.scale);
			__int128 ip = v.big / sc;
			__int128 fp = v.big % sc;
			__int128 half = sc / 2;
			if (v.big < 0) ip = -((-v.big + sc - 1) / sc);
			else if (fp * 2 >= sc) ip++;
			out = ip;
		} else if (src == TId::DATE || src == TId::TIME || src == TId::TIMESTAMP || src == TId::TIMESTAMP_TZ) {
			out = v.i;
		} else if (src == TId::BOOLEAN) {
			out = v.b ? 1 : 0;
		} else if (src == TId::INTERVAL) {
			out = interval_key(v, "micros");
		} else {
			out = v.as_big();
		}
		// range check
		__int128 lo = 0, hi = 0;
		bool check = true;
		switch (dst) {
		case TId::TINYINT: lo = -128; hi = 127; break;
		case TId::SMALLINT: lo = -32768; hi = 32767; break;
		case TId::INTEGER: lo = -2147483648LL; hi = 2147483647LL; break;
		case TId::BIGINT: lo = (__int128)INT64_MIN; hi = (__int128)INT64_MAX; break;
		case TId::HUGEINT: lo = ((__int128)0 - ((__int128)1 << 127)); hi = (((__int128)1 << 127) - 1); break;
		case TId::UTINYINT: lo = 0; hi = 255; break;
		case TId::USMALLINT: lo = 0; hi = 65535; break;
		case TId::UINTEGER: lo = 0; hi = 4294967295LL; break;
		case TId::UBIGINT: lo = 0; hi = (__int128)18446744073709551615ULL; break;
		default: check = false; break;
		}
		if (check && (out < lo || out > hi)) {
			throw_conversion("Type " + std::string(phys_name(src)) + " with value " + v.to_string() + " can't be cast because the value is out of range for the destination type " + phys_name(dst));
		}
		Value o(target);
		o.null = false;
		o.i = (int64_t)out;
		o.big = out;
		return o;
	}
	case TId::FLOAT: case TId::DOUBLE: {
		double d = v.as_double();
		Value o(target);
		o.null = false;
		o.d = d;
		return o;
	}
	case TId::DECIMAL: {
		__int128 out = 0;
		if (src == TId::VARCHAR) {
			std::string t = trim_ws(v.s);
			// parse decimal
			size_t dot = t.find('.');
			bool ok = true;
			std::string ipart = t, fpart;
			if (dot != std::string::npos) { ipart = t.substr(0, dot); fpart = t.substr(dot + 1); }
			if (ipart.empty() || ipart == "-") ipart += "0";
			bool neg = false;
			if (ipart[0] == '-') { neg = true; ipart = ipart.substr(1); }
			else if (ipart[0] == '+') { ipart = ipart.substr(1); }
			if (ipart.empty() || fpart.empty() && false) ok = false;
			for (char c : ipart) if (c < '0' || c > '9') ok = false;
			for (char c : fpart) if (c < '0' || c > '9') ok = false;
			if (!ok) throw_conversion("Could not convert string \"" + v.s + "\" to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")");
			__int128 scale_v = decimal_scale(target.scale);
			__int128 ip = 0;
			for (char c : ipart) ip = ip * 10 + (c - '0');
			__int128 fp = 0;
			for (size_t i = 0; i < (size_t)target.scale && i < fpart.size(); i++) fp = fp * 10 + (fpart[i] - '0');
			// rounding of the remaining digits
			if (fpart.size() > (size_t)target.scale) {
				if (fpart[target.scale] >= '5') fp++;
				if (fp >= scale_v) { fp -= scale_v; ip++; }
			}
			out = ip * scale_v + fp;
			if (neg) out = -out;
			if (out > decimal_scale(38) / 10) {
				throw_conversion("Could not cast value " + v.to_string() + " to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")");
			}
		} else if (src == TId::FLOAT || src == TId::DOUBLE) {
			__int128 scale_v = decimal_scale(target.scale);
			double d = v.d * (double)scale_v;
			if (std::fabs(d) > 1e38) {
				char buf[128];
				snprintf(buf, sizeof(buf), "%s to DECIMAL(%d,%d)", format_double_full(v.d).c_str(), target.width, target.scale);
				std::string vs = v.to_string();
				// DuckDB prints the double with 6 decimals in this message
				char buf2[64];
				snprintf(buf2, sizeof(buf2), "%.6f", v.d);
				throw_conversion("Could not cast value " + std::string(buf2) + " to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")");
			}
			out = (__int128)round_half_away(d);
		} else if (src == TId::DECIMAL) {
			__int128 sc = decimal_scale(v.type.scale);
			__int128 scale_v = decimal_scale(target.scale);
			__int128 mag = v.big;
			if (target.scale > v.type.scale) {
				for (int i = 0; i < target.scale - v.type.scale; i++) mag *= 10;
			} else {
				__int128 div = 1;
				for (int i = 0; i < v.type.scale - target.scale; i++) div *= 10;
				__int128 rem = mag % div;
				mag /= div;
				__int128 half = div / 2;
				if (mag >= 0) { if (rem * 2 >= half) mag++; }
				else { if ((-rem) * 2 >= half) mag--; }
			}
			out = mag;
		} else if (is_numericish(src)) {
			__int128 scale_v = decimal_scale(target.scale);
			out = v.as_big() * scale_v;
		} else {
			throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> DECIMAL)");
		}
		// range check
		__int128 maxv = decimal_scale(target.width) - 1;
		if (out > maxv || out < -maxv) {
			char buf2[64];
			snprintf(buf2, sizeof(buf2), "%.6f", v.d);
			throw_conversion("Could not cast value " + std::string(src == TId::DOUBLE || src == TId::FLOAT ? buf2 : v.to_string()) + " to DECIMAL(" + std::to_string(target.width) + "," + std::to_string(target.scale) + ")");
		}
		Value o(target);
		o.null = false;
		o.big = out;
		return o;
	}
	case TId::VARCHAR: {
		Value o(target);
		o.null = false;
		o.s = v.to_string();
		return o;
	}
	case TId::BLOB: {
		if (src == TId::BLOB) return v;
		if (src == TId::VARCHAR) {
			bool ok = false;
			std::string dec = blob_decode(v.s, ok);
			if (!ok) {
				throw_conversion("Invalid byte encountered in STRING -> BLOB conversion of string \"" + v.s + "\". All non-ascii characters must be escaped with hex codes (e.g. \\xAA)");
			}
			Value o(target);
			o.null = false;
			o.s = dec;
			return o;
		}
		if (src == TId::DOUBLE || src == TId::FLOAT) {
			// DuckDB casts double to blob as raw bytes
			Value o(target);
			o.null = false;
			o.s = std::string((const char *)&v.d, src == TId::DOUBLE ? 8 : 4);
			return o;
		}
		if (is_numericish(src)) {
			Value o(target);
			o.null = false;
			int64_t iv = v.as_int();
			o.s = std::string((const char *)&iv, 8);
			return o;
		}
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> BLOB)");
	}
	case TId::DATE: {
		int64_t days = 0;
		if (src == TId::DATE) return v;
		if (src == TId::TIMESTAMP || src == TId::TIMESTAMP_TZ) return Value::date(epoch_micros_to_date(v.i));
		if (src == TId::VARCHAR) {
			if (!parse_date_string(v.s, days)) {
				throw_conversion("invalid date field format: \"" + v.s + "\", expected format is (YYYY-MM-DD)");
			}
			return Value::date(days);
		}
		if (is_numericish(src)) {
			return Value::date(v.as_int());
		}
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> DATE)");
	}
	case TId::TIME: {
		int64_t micros = 0;
		if (src == TId::TIME) return v;
		if (src == TId::VARCHAR) {
			if (!parse_time_string(v.s, micros)) {
				throw_conversion("time field value out of range: \"" + v.s + "\", expected format is ([YYYY-MM-DD ]HH:MM:SS[.MS])");
			}
			return Value::time(micros);
		}
		if (is_numericish(src)) return Value::time(v.as_int());
		if (src == TId::TIMESTAMP || src == TId::TIMESTAMP_TZ) {
			return Value::time(v.i % 86400000000LL);
		}
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> TIME)");
	}
	case TId::TIMESTAMP: case TId::TIMESTAMP_TZ: {
		int64_t micros = 0;
		if (src == TId::TIMESTAMP || src == TId::TIMESTAMP_TZ) {
			Value o(target); o.null = false; o.i = v.i; return o;
		}
		if (src == TId::DATE) return Value::timestamp(v.i * 86400000000LL);
		if (src == TId::VARCHAR) {
			if (!parse_timestamp_string(v.s, micros)) {
				throw_conversion("invalid timestamp field format: \"" + v.s + "\", expected format is (YYYY-MM-DD HH:MM:SS[.US][±HH[:MM[:SS]]| ZONE])");
			}
			Value o(target); o.null = false; o.i = micros; return o;
		}
		if (is_numericish(src)) {
			Value o(target); o.null = false; o.i = v.as_int() * 1000000;
			return o;
		}
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> TIMESTAMP)");
	}
	case TId::INTERVAL: {
		if (src == TId::INTERVAL) return v;
		if (src == TId::VARCHAR) {
			Value iv = parse_interval(v.s);
			return iv;
		}
		if (is_numericish(src)) {
			Value o(target); o.null = false;
			o.kv = {{"months", Value::integer(0, TId::BIGINT)}, {"days", Value::integer(0, TId::BIGINT)}, {"micros", Value::integer(v.as_int(), TId::BIGINT)}};
			return o;
		}
		throw_conversion("Could not convert string '" + v.to_string() + "' to INTERVAL");
	}
	case TId::LIST: case TId::STRUCT: case TId::MAP: {
		if (src == dst && target == v.type) return v;
		if (src == TId::VARCHAR) {
			return parse_nested_literal(v.s, target);
		}
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> " + target.sql_name() + ")");
	}
	default:
		if (src == dst) return v;
		throw_conversion("Unimplemented type for cast (" + std::string(phys_name(src)) + " -> " + target.sql_name() + ")");
	}
}

// nested literal parsing (list/struct/map from strings)
static void skip_ws(const std::string &s, size_t &p) { while (p < s.size() && isspace((unsigned char)s[p])) p++; }

Value parse_nested_literal(const std::string &s, const LogicalType &target) {
	size_t p = 0;
	skip_ws(s, p);
	if (target.id == TId::LIST) {
		if (p >= s.size() || s[p] != '[') throw_conversion("Could not convert string '" + s + "' to LIST");
		p++;
		std::vector<Value> items;
		while (true) {
			skip_ws(s, p);
			if (p < s.size() && s[p] == ']') { p++; break; }
			// parse until ',' or ']'
			size_t start = p;
			int depth = 0;
			bool in_str = false;
			while (p < s.size()) {
				char c = s[p];
				if (in_str) { if (c == '\'') { if (p + 1 < s.size() && s[p + 1] == '\'') { p += 2; continue; } in_str = false; } p++; continue; }
				if (c == '\'') { in_str = true; p++; continue; }
				if (c == '[' || c == '{') depth++;
				if (c == ']' || c == '}') { if (depth == 0) break; depth--; }
				if (c == ',' && depth == 0) break;
				p++;
			}
			std::string item = trim_ws(s.substr(start, p - start));
			Value iv;
			if (iequals(item, "NULL")) iv = Value::nullval(target.children[0]);
			else if (!item.empty() && item[0] == '\'') iv = do_cast(parse_string_literal(item), target.children[0]);
			else iv = do_cast(Value::str(item), target.children[0]);
			items.push_back(iv);
			skip_ws(s, p);
			if (p < s.size() && s[p] == ',') { p++; continue; }
			if (p < s.size() && s[p] == ']') { p++; break; }
			throw_conversion("Could not convert string '" + s + "' to LIST");
		}
		return Value::listval(items, target);
	}
	if (target.id == TId::STRUCT) {
		if (p >= s.size() || s[p] != '{') throw_conversion("Could not convert string '" + s + "' to STRUCT");
		p++;
		std::vector<Value> fields(target.children.size());
		for (size_t i = 0; i < fields.size(); i++) fields[i] = Value::nullval(target.children[i]);
		while (true) {
			skip_ws(s, p);
			if (p < s.size() && s[p] == '}') { p++; break; }
			size_t start = p;
			while (p < s.size() && s[p] != ':' && s[p] != '}') p++;
			std::string key = trim_ws(s.substr(start, p - start));
			if (p < s.size() && s[p] == ':') p++;
			size_t vstart = p;
			int depth = 0;
			bool in_str = false;
			while (p < s.size()) {
				char c = s[p];
				if (in_str) { if (c == '\'') { if (p + 1 < s.size() && s[p + 1] == '\'') { p += 2; continue; } in_str = false; } p++; continue; }
				if (c == '\'') { in_str = true; p++; continue; }
				if (c == '[' || c == '{') depth++;
				if (c == ']' || c == '}') { if (depth == 0) break; depth--; }
				if (c == ',' && depth == 0) break;
				p++;
			}
			std::string val = trim_ws(s.substr(vstart, p - vstart));
			if (!key.empty() && key[0] == '\'') key = key.substr(1, key.size() - 2);
			size_t idx = target.children.size();
			for (size_t i = 0; i < target.child_names.size(); i++) if (iequals(target.child_names[i], key)) idx = i;
			Value iv;
			if (iequals(val, "NULL")) iv = Value::nullval(idx < target.children.size() ? target.children[idx] : LogicalType());
			else if (!val.empty() && val[0] == '\'') iv = do_cast(parse_string_literal(val), idx < target.children.size() ? target.children[idx] : LogicalType());
			else iv = do_cast(Value::str(val), idx < target.children.size() ? target.children[idx] : LogicalType());
			if (idx < fields.size()) fields[idx] = iv;
			skip_ws(s, p);
			if (p < s.size() && s[p] == ',') { p++; continue; }
			if (p < s.size() && s[p] == '}') { p++; break; }
			throw_conversion("Could not convert string '" + s + "' to STRUCT");
		}
		return Value::structval(fields, target);
	}
	throw_conversion("Unimplemented type for cast (VARCHAR -> " + target.sql_name() + ")");
}

