// SQL AST definitions
#pragma once
#include "value.hpp"

namespace ddb {

enum class EK {
	ColumnRef, Star, Constant, Cast, Binary, Unary, Func, Case, In, Between, Like,
	IsNull, Subquery, Exists, ListCtor, StructCtor, MapCtor, Window, Param, IntervalLit,
	TableStar, Collate, Default, CurrentRow
};

struct Expr {
	EK kind = EK::Constant;
	int op = 0;                  // operator / comparison id
	Value value;                 // constant value
	std::string text;            // raw text (function name, column name, etc)
	std::string table, column;   // column reference
	std::string alias;
	std::vector<std::unique_ptr<Expr>> args;
	std::vector<std::unique_ptr<Expr>> extra;   // for case: when/then/else; in: list
	std::vector<bool> flags;
	bool distinct = false;
	bool negated = false;
	bool star = false;
	bool case_insensitive = false;   // for LIKE ILIKE
	// window
	std::vector<std::unique_ptr<Expr>> partition_by;
	std::vector<std::unique_ptr<Expr>> order_by_exprs;
	std::vector<int> order_by_desc;
	std::string frame;
	// binding output
	LogicalType type;
	std::string name;            // the expression name (for output headers)
	std::string schema_name;
	size_t pos = 0;              // position in the original statement
	// subquery
	struct Query *query = nullptr;

	Expr() {}
	Expr(EK k) : kind(k) {}
};

struct SelectItem {
	std::unique_ptr<Expr> expr;
	std::string alias;
	bool star = false;
	bool has_alias = false;
	std::string star_table;
	size_t pos = 0;
};

enum class TRK { Base, Subquery, TableFunc, Join, Values, CTE };

struct OrderItem {
