			while (pos < n && sql[pos] != '\n') pos++;
			continue;
		}
		if (c == '/' && pos + 1 < n && sql[pos + 1] == '*') {
			pos += 2;
			int depth = 1;
			while (pos < n && depth > 0) {
				if (sql[pos] == '*' && pos + 1 < n && sql[pos + 1] == '/') { depth--; pos += 2; continue; }
