				pos++;
			}
			continue;
		}
		Token t;
		t.pos = pos;
		if (c == '\'') {
			// string literal
			std::string raw = "'";
			pos++;
			while (pos < n) {
				if (sql[pos] == '\'') {
					if (pos + 1 < n && sql[pos + 1] == '\'') { raw += "''"; pos += 2; continue; }
					raw += '\'';
					pos++;
					break;
				}
				raw += sql[pos];
				pos++;
			}
			t.type = Token::STRING;
			t.text = raw;
			t.value = parse_string_literal(raw).s;
			out.push_back(t);
			continue;
		}
		if (c == '"') {
			std::string raw = "\"";
			pos++;
			while (pos < n) {
				if (sql[pos] == '"') {
					if (pos + 1 < n && sql[pos + 1] == '"') { raw += "\"\""; pos += 2; continue; }
					raw += '"';
					pos++;
					break;
				}
				raw += sql[pos];
				pos++;
			}
			t.type = Token::QUOTED;
			t.text = raw;
			t.value = raw.substr(1, raw.size() - 2);
			{
				std::string o;
				for (size_t i = 0; i < t.value.size(); i++) {
					if (t.value[i] == '"' && i + 1 < t.value.size() && t.value[i + 1] == '"') { o += '"'; i++; continue; }
					o += t.value[i];
				}
				t.value = o;
			}
			out.push_back(t);
			continue;
		}
		if (c == '$' && pos + 1 < n && sql[pos + 1] == '$') {
			// dollar quoted string
			std::string raw = "$$";
			pos += 2;
			while (pos + 1 < n) {
				if (sql[pos] == '$' && sql[pos + 1] == '$') { raw += "$$"; pos += 2; break; }
				raw += sql[pos];
				pos++;
			}
			t.type = Token::STRING;
			t.text = raw;
			t.value = raw.substr(2, raw.size() > 4 ? raw.size() - 4 : 0);
			out.push_back(t);
			continue;
		}
		if (is_ident_start(c)) {
			std::string id;
			while (pos < n && is_ident_char(sql[pos])) { id += sql[pos]; pos++; }
			t.type = Token::IDENT;
			t.text = id;
			t.value = id;
			out.push_back(t);
			continue;
		}
		if (isdigit((unsigned char)c) || (c == '.' && pos + 1 < n && isdigit((unsigned char)sql[pos + 1]))) {
			std::string num;
			bool is_float = false;
			if (c == '.') { num += '.'; pos++; is_float = true; }
			while (pos < n && (isdigit((unsigned char)sql[pos]) || sql[pos] == '_')) { num += sql[pos]; pos++; }
			if (pos < n && sql[pos] == '.') {
				num += '.';
				pos++;
				is_float = true;
				while (pos < n && (isdigit((unsigned char)sql[pos]) || sql[pos] == '_')) { num += sql[pos]; pos++; }
			}
			if (pos < n && (sql[pos] == 'e' || sql[pos] == 'E')) {
				std::string save = num;
				num += 'e';
				pos++;
				if (pos < n && (sql[pos] == '+' || sql[pos] == '-')) { num += sql[pos]; pos++; }
				bool digits = false;
				while (pos < n && isdigit((unsigned char)sql[pos])) { num += sql[pos]; pos++; digits = true; }
				if (!digits) { num = save; pos -= (num.size() - save.size()); }
				else is_float = true;
			}
			t.type = Token::NUMBER;
			t.text = num;
			t.value = num;
			out.push_back(t);
			continue;
		}
		// operators
		if (pos + 1 < n) {
			std::string two = sql.substr(pos, 2);
			static const char *ops2[] = {"::", "<=", ">=", "<>", "!=", "||", "->", "=>", "<<" , ">>", "!~", NULL};
			bool matched = false;
			for (int i = 0; ops2[i]; i++) if (two == ops2[i]) { matched = true; break; }
			if (matched) {
				t.type = Token::OP;
				t.text = two;
				t.value = two;
				pos += 2;
				out.push_back(t);
				continue;
			}
		}
		t.type = Token::OP;
		t.text = std::string(1, c);
		t.value = t.text;
		pos++;
		out.push_back(t);
	}
	Token end;
	end.type = Token::END;
	end.pos = n;
	out.push_back(end);
	return out;
}

