// --------------------------------------------------------------- the parser
class Parser {
public:
	const std::string &sql;
	std::vector<Token> toks;
	size_t p = 0;
	size_t stmt_begin = 0;

	Parser(const std::string &s) : sql(s) { toks = tokenize(s); }

	Token &cur() { return toks[p]; }
	Token &peek(size_t k = 1) { return toks[std::min(p + k, toks.size() - 1)]; }
	bool at_end() { return cur().type == Token::END; }
	bool at_op(const char *o) { return cur().type == Token::OP && cur().value == o; }
	bool at_kw(const char *k) { return cur().type == Token::IDENT && iequals(cur().value, k); }
	bool at_kw2(const char *k) { return (cur().type == Token::IDENT || cur().type == Token::QUOTED) && iequals(cur().value, k); }

	[[noreturn]] void syntax_error_here() {
		if (at_end()) throw_parser("syntax error at end of input");
		throw DuckDBException(DuckDBException::Type::PARSER, "syntax error at or near \"" + cur().value + "\"").with_location(stmt_begin, cur().pos);
	}
	[[noreturn]] void syntax_error(const std::string &msg, size_t pos) {
		throw DuckDBException(DuckDBException::Type::PARSER, msg).with_location(stmt_begin, pos);
	}
	void expect_op(const char *o) {
		if (!at_op(o)) syntax_error_here();
		p++;
	}
	void expect_kw(const char *k) {
		if (!at_kw(k)) syntax_error_here();
		p++;
	}
	bool accept_op(const char *o) {
		if (at_op(o)) { p++; return true; }
		return false;
	}
	bool accept_kw(const char *k) {
		if (at_kw(k)) { p++; return true; }
		return false;
