std::string expr_kind_name(EK k) {
	switch (k) {
	case EK::ColumnRef: return "ColumnRef";
	case EK::Star: return "Star";
	case EK::Constant: return "Constant";
	case EK::Cast: return "Cast";
	case EK::Binary: return "Binary";
	case EK::Unary: return "Unary";
	case EK::Func: return "Func";
	default: return "Expr";
	}
}

// operator precedence table
static int binop_prec(const std::string &op) {
	if (op == "::") return 90;
	if (op == "||") return 20;
	if (op == "*" || op == "/" || op == "%" || op == "//") return 30;
	if (op == "+" || op == "-") return 25;
	if (op == "<<" || op == ">>") return 18;
	if (op == "&") return 17;
	if (op == "|") return 16;
	if (op == "^") return 15;
	if (op == "=" || op == "<>" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=") return 12;
	if (op == "&&") return 11;
	if (op == "||") return 11;
	return -1;
}

static int binop_kind(const std::string &op) {
	if (op == "+") return OP_ADD;
	if (op == "-") return OP_SUB;
	if (op == "*") return OP_MUL;
	if (op == "/") return OP_DIV;
	if (op == "//") return OP_INTDIV;
	if (op == "%") return OP_MOD;
	if (op == "^") return OP_POW;
	if (op == "&") return OP_AND_BIT;
	if (op == "|") return OP_OR_BIT;
	if (op == "<<") return OP_SHL;
	if (op == ">>") return OP_SHR;
	return 0;
}

static int cmp_kind(const std::string &op) {
	if (op == "=") return 0;
	if (op == "<>" || op == "!=") return 1;
	if (op == "<") return 2;
	if (op == "<=") return 3;
	if (op == ">") return 4;
	if (op == ">=") return 5;
	return -1;
}

std::unique_ptr<Expr> Parser::parse_expr(int min_prec) {
	auto left = parse_primary();
	while (true) {
		if (cur().type == Token::OP) {
			std::string op = cur().value;
			if (op == "::") {
				p++;
				LogicalType t = parse_type();
				auto e = std::make_unique<Expr>(EK::Cast);
				e->args.push_back(std::move(left));
				e->type = t;
				e->pos = left->pos;
				left = std::move(e);
				continue;
			}
			int prec = binop_prec(op);
			if (prec >= 0 && prec >= min_prec) {
				// check for IS DISTINCT FROM style
				p++;
				auto right = parse_expr(prec + 1);
				auto e = std::make_unique<Expr>(EK::Binary);
				e->op = binop_kind(op);
				e->text = op;
				if (op == "=" || op == "<>" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=") {
					e->op = cmp_kind(op);
					e->kind = EK::Binary; // comparisons share Binary
					e->flags.push_back(true); // flag: comparison
				}
				e->args.push_back(std::move(left));
				e->args.push_back(std::move(right));
				e->pos = left->pos;
				left = std::move(e);
				continue;
			}
			if (op == "." ) break;
			break;
		}
		// word operators
		if (cur().type == Token::IDENT) {
			std::string w = cur().value;
			if (iequals(w, "AND")) {
				if (min_prec > 4) break;
				p++;
				auto right = parse_expr(5);
				auto e = std::make_unique<Expr>(EK::Binary);
				e->op = 100; // AND
				e->text = "AND";
				e->args.push_back(std::move(left));
				e->args.push_back(std::move(right));
				e->pos = left->pos;
				left = std::move(e);
				continue;
			}
			if (iequals(w, "OR")) {
				if (min_prec > 3) break;
				p++;
				auto right = parse_expr(4);
				auto e = std::make_unique<Expr>(EK::Binary);
				e->op = 101; // OR
				e->text = "OR";
				e->args.push_back(std::move(left));
				e->args.push_back(std::move(right));
				e->pos = left->pos;
				left = std::move(e);
				continue;
			}
			if (iequals(w, "IS")) {
				// IS NULL / IS NOT NULL / IS TRUE / IS [NOT] DISTINCT FROM
				p++;
				bool not_ = accept_kw("NOT");
				if (at_kw("NULL")) {
					p++;
					auto e = std::make_unique<Expr>(EK::IsNull);
					e->negated = not_;
					e->args.push_back(std::move(left));
					e->pos = left->pos;
					left = std::move(e);
					continue;
				}
				if (at_kw("DISTINCT")) {
					p++;
					expect_kw("FROM");
					auto right = parse_expr(6);
					auto e = std::make_unique<Expr>(EK::In);
					e->op = 30; // is distinct from
					e->negated = not_;
					e->args.push_back(std::move(left));
					e->args.push_back(std::move(right));
					e->pos = left->pos;
					left = std::move(e);
					continue;
				}
				if (at_kw("TRUE") || at_kw("FALSE")) {
					bool tv = iequals(cur().value, "TRUE");
					p++;
					auto e = std::make_unique<Expr>(EK::In);
					e->op = 31; // is true/false
					e->negated = not_;
					e->flags.push_back(tv);
					e->args.push_back(std::move(left));
					e->pos = left->pos;
					left = std::move(e);
					continue;
				}
				syntax_error_here();
			}
			if (iequals(w, "ISNULL") || iequals(w, "NOTNULL")) {
				bool not_ = iequals(w, "NOTNULL");
				p++;
				auto e = std::make_unique<Expr>(EK::IsNull);
				e->negated = not_;
				e->args.push_back(std::move(left));
				e->pos = left->pos;
				left = std::move(e);
				continue;
			}
			if (iequals(w, "NOT")) {
				// NOT IN / NOT LIKE / NOT BETWEEN / NOT ILIKE
				if (at_op("(") && peek().type == Token::STRING) {
					// could be a NOT function? no. fall through
				}
				std::string next = peek().type == Token::IDENT ? peek().value : "";
				if (iequals(next, "IN") || iequals(next, "LIKE") || iequals(next, "ILIKE") || iequals(next, "BETWEEN") ||
				    iequals(next, "SIMILAR") || iequals(next, "GLOB") || iequals(next, "REGEXP")) {
					p++;
					w = cur().value;
					// handled below with negated flag
				} else if (min_prec <= 9) {
					p++;
					auto right = parse_expr(9);
					auto e = std::make_unique<Expr>(EK::Unary);
					e->op = 2; // NOT
					e->args.push_back(std::move(right));
					e->pos = left->pos;
					left = std::move(e);
					continue;
				}
			}
			if (iequals(w, "IN") || iequals(w, "LIKE") || iequals(w, "ILIKE") || iequals(w, "BETWEEN") ||
			    iequals(w, "SIMILAR") || iequals(w, "GLOB") || iequals(w, "REGEXP")) {
				// precedence: same as comparison
				if (min_prec > 12) break;
				bool negated = false;
				if (iequals(w, "NOT")) { p++; w = cur().value; negated = true; }
				if (iequals(w, "IN")) {
