	Token &peek(size_t k = 1) { return toks[std::min(p + k, toks.size() - 1)]; }
	bool at_end() { return cur().type == Token::END; }
	bool at_op(const char *o) { return cur().type == Token::OP && cur().value == o; }
	bool at_kw(const char *k) { return cur().type == Token::IDENT && iequals(cur().value, k); }
	bool at_kw2(const char *k) { return (cur().type == Token::IDENT || cur().type == Token::QUOTED) && iequals(cur().value, k); }

	[[noreturn]] void syntax_error_here() {
		if (at_end()) throw_parser("syntax error at end of input");
		throw DuckDBException(DuckDBException::Type::PARSER, "syntax error at or near \"" + cur().value + "\"").with_location(stmt_begin, cur().pos);
