// operator precedence table
static int binop_prec(const std::string &op) {
	if (op == "::") return 90;
	if (op == "||") return 20;
	if (op == "*" || op == "/" || op == "%" || op == "//") return 30;
	if (op == "+" || op == "-") return 25;
	if (op == "<<" || op == ">>") return 18;
	if (op == "&") return 17;
	if (op == "|") return 16;
	if (op == "^") return 15;
	if (op == "=" || op == "<>" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=") return 12;
	if (op == "&&") return 11;
	if (op == "||") return 11;
	return -1;
}

static int binop_kind(const std::string &op) {
	if (op == "+") return OP_ADD;
	if (op == "-") return OP_SUB;
	if (op == "*") return OP_MUL;
	if (op == "/") return OP_DIV;
	if (op == "//") return OP_INTDIV;
	if (op == "%") return OP_MOD;
	if (op == "^") return OP_POW;
	if (op == "&") return OP_AND_BIT;
	if (op == "|") return OP_OR_BIT;
	if (op == "<<") return OP_SHL;
	if (op == ">>") return OP_SHR;
	return 0;
}

static int cmp_kind(const std::string &op) {
	if (op == "=") return 0;
	if (op == "<>" || op == "!=") return 1;
	if (op == "<") return 2;
	if (op == "<=") return 3;
	if (op == ">") return 4;
	if (op == ">=") return 5;
	return -1;
