std::vector<std::unique_ptr<Expr>> Parser::parse_arg_list(const char *open, const char *close) {
	std::vector<std::unique_ptr<Expr>> out;
	if (open && at_op(open)) p++;
	if (close && at_op(close)) { p++; return out; }
	while (true) {
		if (at_op("*") && out.empty()) {
			auto e = std::make_unique<Expr>(EK::Star);
			e->star = true;
