		auto e = std::make_unique<Expr>(EK::Constant);
		std::string num = t.text;
		bool has_dot = num.find('.') != std::string::npos;
		bool has_exp = num.find('e') != std::string::npos || num.find('E') != std::string::npos;
		if (has_exp) {
			e->value = Value::dbl(atof(num.c_str()));
			e->type = LogicalType(TId::DOUBLE);
		} else if (has_dot) {
			// decimal literal
			size_t dot = num.find('.');
			std::string ip = num.substr(0, dot);
			std::string fp = num.substr(dot + 1);
			int idg = 0;
			for (char c : ip) if (isdigit((unsigned char)c)) idg++;
			int fdg = 0;
			for (char c : fp) if (isdigit((unsigned char)c)) fdg++;
			e->value = parse_decimal_literal(num, idg, fdg, false, true);
			e->type = e->value.type;
		} else {
			e->value = parse_integer_literal(num, false, t.pos);
			e->type = e->value.type;
		}
		e->text = num;
		e->pos = t.pos;
		return e;
	}
	if (t.type == Token::QUOTED) {
		p++;
		std::string name = t.value;
		// possibly qualified: a.b / a.b.c
		auto e = std::make_unique<Expr>(EK::ColumnRef);
		e->column = name;
		e->pos = t.pos;
		if (at_op(".")) {
			p++;
			Token t2 = cur();
			if (t2.type == Token::QUOTED || t2.type == Token::IDENT) {
				p++;
				e->table = e->column;
				e->column = t2.value;
				if (at_op(".")) {
					p++;
					Token t3 = cur();
					if (t3.type == Token::QUOTED || t3.type == Token::IDENT) {
						p++;
						e->schema_name = e->table;
						e->table = e->column;
						e->column = t3.value;
					}
				}
			} else if (at_op("*")) {
				p++;
				auto s = std::make_unique<Expr>(EK::TableStar);
				s->table = name;
				s->star = true;
				s->pos = t.pos;
				return s;
			} else syntax_error_here();
		}
		if (at_op(".")) { p++; expect_op("*"); }
		return e;
	}
	if (t.type == Token::IDENT) {
		std::string w = t.value;
		// keywords that form literals
		if (iequals(w, "NULL")) {
			p++;
			auto e = std::make_unique<Expr>(EK::Constant);
			e->value = Value::nullval(LogicalType(TId::INTEGER));
			e->text = "NULL";
			e->pos = t.pos;
			return e;
		}
		if (iequals(w, "TRUE") || iequals(w, "FALSE")) {
			p++;
			auto e = std::make_unique<Expr>(EK::Constant);
			e->value = Value::boolean(iequals(w, "TRUE"));
			e->text = iequals(w, "TRUE") ? "true" : "false";
			e->type = LogicalType(TId::BOOLEAN);
			e->pos = t.pos;
			return e;
		}
		if (iequals(w, "INTERVAL")) {
			p++;
			std::string text;
			if (cur().type == Token::STRING) {
				text = cur().value;
				p++;
			} else {
				// INTERVAL n UNIT [n UNIT ...]
				text = "";
				while (true) {
					if (cur().type == Token::NUMBER) {
						text += cur().text + " ";
						p++;
						if (cur().type == Token::IDENT) { text += cur().value; p++; }
						else if (cur().type == Token::NUMBER) { text += cur().text; p++; }
						text += " ";
					} else break;
					if (!accept_op(",")) break;
				}
			}
			auto e = std::make_unique<Expr>(EK::Constant);
			try {
				e->value = parse_interval(text);
			} catch (DuckDBException &) {
				throw DuckDBException(DuckDBException::Type::PARSER, "Could not convert string '" + text + "' to INTERVAL").with_location(stmt_begin, t.pos);
			}
			e->type = LogicalType(TId::INTERVAL);
			e->text = text;
			e->pos = t.pos;
			return e;
		}
		if (iequals(w, "DATE") || iequals(w, "TIME") || iequals(w, "TIMESTAMP") || iequals(w, "TIMESTAMPTZ") || iequals(w, "TIMESTAMP") ||
		    iequals(w, "DECIMAL") || iequals(w, "NUMERIC") || iequals(w, "STRUCT") || iequals(w, "MAP") || iequals(w, "LIST") || iequals(w, "UNION") ||
		    iequals(w, "CAST") || iequals(w, "TRY_CAST")) {
			if (cur().type == Token::STRING || (iequals(w, "CAST") || iequals(w, "TRY_CAST"))) {
				// typed literal
				if (cur().type == Token::STRING) {
					std::string sv = cur().value;
					std::string raw = cur().text;
					p++;
					LogicalType ty;
					if (iequals(w, "DATE")) ty = LogicalType(TId::DATE);
					else if (iequals(w, "TIME")) ty = LogicalType(TId::TIME);
					else if (iequals(w, "TIMESTAMPTZ")) ty = LogicalType(TId::TIMESTAMP_TZ);
					else if (iequals(w, "TIMESTAMP")) ty = LogicalType(TId::TIMESTAMP);
					auto e = std::make_unique<Expr>(EK::Cast);
					auto inner = std::make_unique<Expr>(EK::Constant);
					inner->value = Value::str(sv);
					inner->type = LogicalType(TId::VARCHAR);
					inner->text = raw;
					inner->pos = cur().pos;
					e->args.push_back(std::move(inner));
					e->type = ty;
					e->text = w;
					e->pos = t.pos;
					return e;
				}
			}
			if (iequals(w, "CAST") || iequals(w, "TRY_CAST")) {
				p++;
				auto inner = parse_expr(0);
				expect_kw("AS");
				LogicalType ty = parse_type();
				expect_op(")");
				auto e = std::make_unique<Expr>(EK::Cast);
				e->args.push_back(std::move(inner));
				e->type = ty;
				e->pos = t.pos;
				return e;
			}
			if (iequals(w, "STRUCT") && at_op("(")) {
				// struct literal
				p++;
				auto e = std::make_unique<Expr>(EK::StructCtor);
				while (true) {
					if (at_op(")")) { p++; break; }
					std::string key;
					std::unique_ptr<Expr> val;
					if (cur().type == Token::QUOTED || cur().type == Token::IDENT) {
						Token k = cur();
						p++;
						if (at_op(":") && peek().text == "=") {
							// :=
							p++;
							p++;
							key = k.value;
							val = parse_expr(0);
						} else if (at_op("=")) {
							p++;
							key = k.value;
							val = parse_expr(0);
						} else {
							// type only (struct(a integer))
							key = k.value;
							// parse a type expression: name TYPE
							LogicalType ty = parse_type();
							auto c = std::make_unique<Expr>(EK::Constant);
							c->value = Value::nullval(ty);
							c->type = ty;
							c->text = key;
							c->flags.push_back(true); // type-only marker
							e->extra.push_back(std::move(c));
