							if (at_op(")")) { p++; break; }
							syntax_error_here();
						}
					} else syntax_error_here();
					val->text = key;
					e->args.push_back(std::move(val));
					if (accept_op(",")) continue;
					if (at_op(")")) { p++; break; }
					syntax_error_here();
				}
				e->pos = t.pos;
				return e;
			}
			if (iequals(w, "MAP") && at_op("{")) {
				p++;
				auto e = std::make_unique<Expr>(EK::MapCtor);
				while (true) {
					if (at_op("}")) { p++; break; }
					auto k = parse_expr(0);
					expect_op(":");
					auto v = parse_expr(0);
					e->args.push_back(std::move(k));
					e->extra.push_back(std::move(v));
					if (accept_op(",")) continue;
					if (at_op("}")) { p++; break; }
					syntax_error_here();
				}
				e->pos = t.pos;
				return e;
			}
			if (iequals(w, "DECIMAL") || iequals(w, "NUMERIC")) {
				// DECIMAL '123.45'
				if (cur().type == Token::STRING) {
