			return e;
		}
		if (at_op("(")) {
			// parenthesized expression / subquery / row
			p++;
			if (at_kw("SELECT") || at_kw("WITH") || at_kw("VALUES")) {
				auto q = parse_query(false);
				expect_op(")");
				auto e = std::make_unique<Expr>(EK::Subquery);
				e->query = q.release();
				e->pos = t.pos;
				return e;
			}
			auto first = parse_expr(0);
			if (at_op(",")) {
				auto e = std::make_unique<Expr>(EK::ListCtor);
				e->op = 10; // row constructor
				e->args.push_back(std::move(first));
				while (accept_op(",")) e->args.push_back(parse_expr(0));
				expect_op(")");
				e->pos = t.pos;
				return e;
			}
			expect_op(")");
			first->pos = t.pos;
			return first;
		}
		if (at_op("[")) {
			p++;
			auto e = std::make_unique<Expr>(EK::ListCtor);
			while (true) {
				if (at_op("]")) { p++; break; }
				e->args.push_back(parse_expr(0));
				if (accept_op(",")) continue;
				if (at_op("]")) { p++; break; }
				syntax_error_here();
			}
			e->pos = t.pos;
			return e;
		}
		if (at_op("{")) {
			p++;
			auto e = std::make_unique<Expr>(EK::StructCtor);
			while (true) {
				if (at_op("}")) { p++; break; }
				std::string key;
				if (cur().type == Token::STRING) { key = cur().value; p++; }
				else if (cur().type == Token::IDENT || cur().type == Token::QUOTED) { key = cur().value; p++; }
				else if (cur().type == Token::NUMBER) { key = cur().text; p++; }
				else syntax_error_here();
				expect_op(":");
				auto v = parse_expr(0);
				v->text = key;
				e->args.push_back(std::move(v));
				if (accept_op(",")) continue;
				if (at_op("}")) { p++; break; }
				syntax_error_here();
			}
			e->pos = t.pos;
			return e;
		}
		// unary operators
		if (t.text == "-" || t.text == "+") {
			// only if the next token is not the start of an expression operand? handle here
			p++;
			auto inner = parse_expr(95);
			auto e = std::make_unique<Expr>(EK::Unary);
			e->op = t.text == "-" ? OP_SUB : OP_ADD;
			e->negated = t.text == "-";
			e->args.push_back(std::move(inner));
			e->pos = t.pos;
			return e;
		}
		if (t.text == "~") {
			p++;
			auto inner = parse_expr(95);
			auto e = std::make_unique<Expr>(EK::Unary);
			e->op = 3; // bitwise not
			e->args.push_back(std::move(inner));
			e->pos = t.pos;
			return e;
		}
		if (t.text == "*") {
			p++;
			auto e = std::make_unique<Expr>(EK::Star);
			e->star = true;
			e->pos = t.pos;
			return e;
		}
		// identifier or function
		p++;
		std::string name = t.value;
		std::string schema, catalog;
		if (at_op(".")) {
			p++;
			Token t2 = cur();
			if (t2.type == Token::IDENT || t2.type == Token::QUOTED) {
				p++;
				schema = name;
				name = t2.value;
				if (at_op(".")) {
					p++;
					Token t3 = cur();
					if (t3.type == Token::IDENT || t3.type == Token::QUOTED) {
						p++;
						catalog = schema;
						schema = name;
						name = t3.value;
					} else if (at_op("*")) {
						p++;
						auto e = std::make_unique<Expr>(EK::TableStar);
						e->table = name;
						e->schema_name = schema;
						e->star = true;
						e->pos = t.pos;
						return e;
					}
				} else if (at_op("*")) {
					p++;
					auto e = std::make_unique<Expr>(EK::TableStar);
					e->table = name;
					e->star = true;
					e->pos = t.pos;
					return e;
				}
			} else if (at_op("*")) {
				p++;
				auto e = std::make_unique<Expr>(EK::TableStar);
				e->table = name;
				e->star = true;
				e->pos = t.pos;
				return e;
			}
		}
		auto e = std::make_unique<Expr>(EK::ColumnRef);
		e->table = schema;
		e->column = name;
		e->schema_name = catalog;
		e->pos = t.pos;
		if (at_op("(")) {
			return parse_func_call(std::move(e));
		}
		// struct/map constructor syntax: struct_pack? handled via func
		return e;
	}
	syntax_error_here();
	return nullptr;
}

std::unique_ptr<Expr> Parser::parse_case() {
	Token t = cur();
	p++;
	auto e = std::make_unique<Expr>(EK::Case);
	if (!at_kw("WHEN")) {
		e->extra.push_back(parse_expr(0)); // the base expression
	}
	while (at_kw("WHEN")) {
		p++;
		e->args.push_back(parse_expr(0));
		expect_kw("THEN");
		e->args.push_back(parse_expr(0));
	}
	if (at_kw("ELSE")) {
		p++;
		e->args.push_back(parse_expr(0));
	}
	expect_kw("END");
	e->pos = t.pos;
	return e;
}

std::unique_ptr<Expr> Parser::parse_func_call(std::unique_ptr<Expr> name_expr) {
	// name_expr is a ColumnRef with the function name
	Token t = cur();
	expect_op("(");
	auto e = std::make_unique<Expr>(EK::Func);
	e->text = name_expr->column;
	e->schema_name = name_expr->table;
	e->pos = name_expr->pos;
	if (at_op("*")) {
		auto star = std::make_unique<Expr>(EK::Star);
		star->star = true;
		star->pos = cur().pos;
		p++;
		e->args.push_back(std::move(star));
	} else if (!at_op(")")) {
		while (true) {
			e->args.push_back(parse_expr(0));
			if (accept_op(",")) continue;
			break;
		}
	}
	if (at_kw("DISTINCT")) {
		p++;
		e->distinct = true;
		// the actual argument comes after DISTINCT
		while (true) {
			if (e->args.size() > 1) break;
			e->args.clear();
			e->args.push_back(parse_expr(0));
			if (accept_op(",")) continue;
			break;
		}
	}
	// named parameters
	if (at_op("=>")) {
		// reparse
	}
	expect_op(")");
	// named arguments after: name := value
	if (at_op(":") ) { /* handled above */ }
	return e;
}

