		if (iequals(w, "CHARACTER")) { p++; if (at_kw("VARYING")) { name = "VARCHAR"; p++; } else name = "VARCHAR"; continue; }
		if (iequals(w, "DOUBLE") && (peek().type == Token::IDENT && iequals(peek().value, "PRECISION"))) { p += 2; return LogicalType(TId::DOUBLE); }
		if (iequals(w, "TIMESTAMP") && peek().type == Token::IDENT && iequals(peek().value, "WITH")) {
			p += 2; // TIMESTAMP WITH
			expect_kw("TIME");
			expect_kw("ZONE");
			return LogicalType(TId::TIMESTAMP_TZ);
		}
		if (iequals(w, "TIME") && peek().type == Token::IDENT && iequals(peek().value, "WITH")) {
			p += 2;
			expect_kw("TIME");
			expect_kw("ZONE");
			return LogicalType(TId::TIME);
		}
		if (iequals(w, "WITHOUT")) { p++; expect_kw("TIME"); expect_kw("ZONE"); continue; }
		if (iequals(w, "NOT")) { p++; expect_kw("NULL"); continue; }
		name = w;
		p++;
		break;
	}
	if (name.empty()) syntax_error_here();
	LogicalType t(TId::UNKNOWN);
	if (iequals(name, "BOOLEAN") || iequals(name, "BOOL") || iequals(name, "LOGICAL")) t = LogicalType(TId::BOOLEAN);
	else if (iequals(name, "TINYINT") || iequals(name, "INT1") || iequals(name, "INT8") || iequals(name, "BYTE") || iequals(name, "SIGNED1")) t = LogicalType(TId::TINYINT);
	else if (iequals(name, "SMALLINT") || iequals(name, "INT2") || iequals(name, "SHORT")) t = LogicalType(TId::SMALLINT);
	else if (iequals(name, "INTEGER") || iequals(name, "INT") || iequals(name, "INT4") || iequals(name, "SIGNED") || iequals(name, "INT32")) t = LogicalType(TId::INTEGER);
	else if (iequals(name, "BIGINT") || iequals(name, "INT64") || iequals(name, "LONG")) t = LogicalType(TId::BIGINT);
	else if (iequals(name, "HUGEINT") || iequals(name, "INT128")) t = LogicalType(TId::HUGEINT);
	else if (iequals(name, "UTINYINT") || iequals(name, "UINT8") || iequals(name, "UBYTE")) t = LogicalType(TId::UTINYINT);
	else if (iequals(name, "USMALLINT") || iequals(name, "UINT16")) t = LogicalType(TId::USMALLINT);
	else if (iequals(name, "UINTEGER") || iequals(name, "UINT32")) t = LogicalType(TId::UINTEGER);
	else if (iequals(name, "UBIGINT") || iequals(name, "UINT64")) t = LogicalType(TId::UBIGINT);
	else if (iequals(name, "FLOAT") || iequals(name, "FLOAT4") || iequals(name, "REAL")) t = LogicalType(TId::FLOAT);
	else if (iequals(name, "DOUBLE") || iequals(name, "FLOAT8")) t = LogicalType(TId::DOUBLE);
	else if (iequals(name, "DECIMAL") || iequals(name, "NUMERIC") || iequals(name, "DEC")) {
		int w = 18, s = 3;
		if (at_op("(")) {
			p++;
			auto args = parse_arg_list(nullptr, ")");
			if (args.size() >= 1) w = (int)args[0]->value.as_int();
			if (args.size() >= 2) s = (int)args[1]->value.as_int();
		}
		t = LogicalType::decimal(w, s);
	} else if (iequals(name, "VARCHAR") || iequals(name, "TEXT") || iequals(name, "STRING") || iequals(name, "CHAR") ||
	           iequals(name, "BPCHAR") || iequals(name, "NCHAR") || iequals(name, "NVARCHAR")) {
		t = LogicalType(TId::VARCHAR);
		if (at_op("(")) { p++; parse_arg_list(nullptr, ")"); }
	} else if (iequals(name, "BLOB") || iequals(name, "BYTEA") || iequals(name, "VARBINARY") || iequals(name, "BINARY")) {
		t = LogicalType(TId::BLOB);
	} else if (iequals(name, "DATE")) t = LogicalType(TId::DATE);
	else if (iequals(name, "TIME")) t = LogicalType(TId::TIME);
	else if (iequals(name, "TIMESTAMP") || iequals(name, "DATETIME")) t = LogicalType(TId::TIMESTAMP);
	else if (iequals(name, "TIMESTAMPTZ")) t = LogicalType(TId::TIMESTAMP_TZ);
	else if (iequals(name, "INTERVAL")) t = LogicalType(TId::INTERVAL);
	else if (iequals(name, "JSON")) t = LogicalType(TId::VARCHAR);
	else if (iequals(name, "UUID")) t = LogicalType(TId::HUGEINT);
	else if (iequals(name, "STRUCT") || iequals(name, "ROW")) {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		if (at_op("(")) {
			p++;
			while (true) {
				if (at_op(")")) { p++; break; }
				std::string cname = parse_identifier();
				LogicalType cty = parse_type();
				names.push_back(cname);
				types.push_back(cty);
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
		}
		t = LogicalType::struct_type(names, types);
	} else if (iequals(name, "MAP")) {
		expect_op("(");
		LogicalType k = parse_type();
		expect_op(",");
		LogicalType v = parse_type();
		expect_op(")");
		t = LogicalType::map_type(k, v);
	} else if (iequals(name, "UNION")) {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		if (at_op("(")) {
			p++;
			while (true) {
				if (at_op(")")) { p++; break; }
				std::string cname = parse_identifier();
				LogicalType cty = parse_type();
				names.push_back(cname);
				types.push_back(cty);
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
		}
		t = LogicalType(TId::UNION);
		t.child_names = names;
		t.children = types;
	} else if (iequals(name, "LIST") || iequals(name, "ARRAY")) {
		expect_op("(");
		LogicalType inner = parse_type();
		expect_op(")");
		t = LogicalType::list_type(inner);
	} else if (iequals(name, "NULLTYPE")) t = LogicalType(TId::UNKNOWN);
	else {
		// unknown type
		p--;
		throw DuckDBException(DuckDBException::Type::PARSER, "syntax error at or near \"" + cur().value + "\"").with_location(stmt_begin, cur().pos);
	}
	// array suffixes: INT[] or INT[3]
	while (true) {
		if (at_op("[")) {
			p++;
			if (at_op("]")) {
				p++;
				t = LogicalType::list_type(t);
			} else {
				auto args = parse_arg_list(nullptr, "]");
				int n = args.empty() ? 0 : (int)args[0]->value.as_int();
				t = LogicalType::array_type(t, n);
			}
			continue;
		}
		break;
	}
	return t;
}

std::string Parser::parse_identifier() {
	if (cur().type != Token::IDENT && cur().type != Token::QUOTED && cur().type != Token::STRING) syntax_error_here();
	std::string s = cur().value;
	p++;
	return s;
}

std::vector<std::string> Parser::parse_name_list(bool allow_quoted) {
	std::vector<std::string> out;
	while (true) {
		out.push_back(parse_identifier());
		if (accept_op(",")) continue;
		break;
	}
	return out;
}

// ----------------------------------------------------------------- queries
std::unique_ptr<Query> Parser::parse_query(bool allow_with) {
	auto q = std::make_unique<Query>();
	q->pos = cur().pos;
	if (allow_with && at_kw("WITH")) {
		p++;
		bool recursive = false;
		if (at_kw("RECURSIVE")) { p++; recursive = true; }
		while (true) {
			std::string name = parse_identifier();
			std::vector<std::string> cols;
			if (at_op("(")) {
				p++;
				while (true) {
					if (at_op(")")) { p++; break; }
					cols.push_back(parse_identifier());
					if (accept_op(",")) continue;
					if (at_op(")")) { p++; break; }
					syntax_error_here();
				}
			}
			expect_kw("AS");
			if (at_op("(")) {
				p++;
				auto body = parse_query(true);
				expect_op(")");
				q->cte_names.push_back(name);
				q->cte_bodies.push_back(std::move(body));
				q->cte_columns.push_back({});
				for (auto &c : cols) q->cte_column_names.push_back(c);
			} else syntax_error_here();
			if (accept_op(",")) continue;
			break;
		}
		(void)recursive;
	}
	// select core
	if (at_op("(")) {
		p++;
		auto inner = parse_query(true);
		expect_op(")");
		q->distinct = inner->distinct;
		q->select_list = std::move(inner->select_list);
		q->from = std::move(inner->from);
		q->where = std::move(inner->where);
		q->having = std::move(inner->having);
		q->group_by = std::move(inner->group_by);
		q->set_ops = std::move(inner->set_ops);
		q->is_values = inner->is_values;
		q->values_rows = std::move(inner->values_rows);
		q->cte_names = std::move(inner->cte_names);
		q->cte_bodies = std::move(inner->cte_bodies);
		q->cte_column_names = std::move(inner->cte_column_names);
	} else if (at_kw("SELECT") || at_kw("TABLE")) {
		if (at_kw("TABLE")) {
			p++;
			std::string tname = parse_identifier();
			auto sel = std::make_unique<Expr>(EK::ColumnRef);
			sel->star = true;
			SelectItem it;
			it.star = true;
			it.star_table = tname;
			it.pos = q->pos;
			q->select_list.push_back(std::move(it));
		} else {
			p++;
			if (at_kw("DISTINCT")) { p++; q->distinct = true; }
			else if (at_kw("ALL")) { p++; }
			// select list
			while (true) {
				SelectItem item;
				item.pos = cur().pos;
				if (at_op("*")) {
					p++;
					item.star = true;
					auto e = std::make_unique<Expr>(EK::Star);
					e->star = true;
					e->pos = item.pos;
					item.expr = std::move(e);
				} else if ((cur().type == Token::IDENT || cur().type == Token::QUOTED) && (peek().type == Token::OP && peek().value == ".")) {
					// could be table.* or qualified column
					std::string a = cur().value;
					size_t save = p;
					p += 2;
					if (at_op("*")) {
						p++;
						item.star = true;
						item.star_table = a;
						auto e = std::make_unique<Expr>(EK::TableStar);
						e->table = a;
						e->star = true;
						e->pos = item.pos;
						item.expr = std::move(e);
					} else {
						p = save;
						item.expr = parse_expr(0);
					}
				} else {
					item.expr = parse_expr(0);
				}
				if (at_kw("AS")) {
					p++;
					item.alias = parse_identifier();
					item.has_alias = true;
				} else if ((cur().type == Token::IDENT && !is_keyword(cur().value)) || cur().type == Token::QUOTED || cur().type == Token::STRING) {
					item.alias = cur().value;
					item.has_alias = true;
					p++;
				}
				q->select_list.push_back(std::move(item));
				if (accept_op(",")) continue;
				break;
			}
		}
	} else if (at_kw("VALUES")) {
		p++;
		q->is_values = true;
		while (true) {
			expect_op("(");
			std::vector<std::unique_ptr<Expr>> row;
			while (true) {
				if (at_op(")")) { p++; break; }
				row.push_back(parse_expr(0));
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
			q->values_rows.push_back(std::move(row));
			if (accept_op(",")) continue;
			break;
		}
	} else syntax_error_here();

	// FROM
	if (at_kw("FROM")) {
		p++;
		q->from = parse_from_clause();
	}
	// WHERE
	if (at_kw("WHERE")) {
		p++;
		q->where = parse_expr(0);
	}
	// GROUP BY
	if (at_kw("GROUP")) {
		p++;
		expect_kw("BY");
		if (at_kw("ALL")) { p++; }
		else if (at_kw("GROUPING") || at_kw("SETS")) { p++; if (at_kw("SETS")) p++; }
		while (true) {
			q->group_by.push_back(parse_expr(0));
			if (accept_op(",")) continue;
			break;
		}
	}
	// HAVING
	if (at_kw("HAVING")) {
		p++;
		q->having = parse_expr(0);
	}
	// QUALIFY
	if (at_kw("QUALIFY")) {
		p++;
		q->having = parse_expr(0);
	}
	// set operations
	while (at_kw("UNION") || at_kw("INTERSECT") || at_kw("EXCEPT")) {
		SetOpItem so;
		std::string w = cur().value;
		p++;
		bool all = false;
		if (at_kw("ALL")) { p++; all = true; }
		else if (at_kw("DISTINCT")) { p++; }
		if (iequals(w, "UNION")) so.type = all ? 1 : 0;
		else if (iequals(w, "INTERSECT")) so.type = all ? 5 : 2;
		else so.type = all ? 4 : 3;
		if (at_op("(")) {
			p++;
			auto inner = parse_query(true);
			expect_op(")");
			so.query = std::move(inner);
		} else {
			auto inner = std::make_unique<Query>();
			inner->pos = cur().pos;
			if (at_kw("WITH")) {
				auto body = parse_query(true);
				so.query = std::move(body);
			} else {
				// parse the next select
				p--;
				Token save = cur();
				auto sq = std::make_unique<Query>();
				sq->pos = cur().pos;
				// use a sub-parser by reusing: we recursively call parse_select_core equivalent
				// simplest: call parse_query with allow_with=false but that would consume set ops
				auto sub = parse_query_setop_body();
				so.query = std::move(sub);
			}
		}
		q->set_ops.push_back(std::move(so));
	}
	// ORDER BY
	if (at_kw("ORDER")) {
		p++;
		expect_kw("BY");
		while (true) {
			OrderItem it;
			it.expr = parse_expr(0);
			if (at_kw("ASC")) { p++; }
			else if (at_kw("DESC")) { p++; it.desc = true; }
			if (at_kw("NULLS")) {
				p++;
				it.has_nulls_spec = true;
				if (at_kw("FIRST")) { p++; it.nulls_first = true; }
				else if (at_kw("LAST")) { p++; it.nulls_first = false; }
			}
			q->order_by.push_back(std::move(it));
			if (accept_op(",")) continue;
			break;
		}
	}
	// LIMIT
	if (at_kw("LIMIT")) {
		p++;
		q->limit = parse_expr(0);
	}
	if (at_kw("OFFSET")) {
		p++;
		q->offset = parse_expr(0);
	}
	if (at_kw("LIMIT")) {
		p++;
		q->limit = parse_expr(0);
	}
	return q;
}

std::unique_ptr<Query> Parser::parse_query_setop_body() {
	// parse a SELECT ... (without set ops / order by) for the right side of a set op
	auto q = std::make_unique<Query>();
	q->pos = cur().pos;
	if (at_op("(")) {
		p++;
		auto inner = parse_query(true);
		expect_op(")");
		q->distinct = inner->distinct;
		q->select_list = std::move(inner->select_list);
		q->from = std::move(inner->from);
		q->where = std::move(inner->where);
		q->having = std::move(inner->having);
		q->group_by = std::move(inner->group_by);
		q->is_values = inner->is_values;
		q->values_rows = std::move(inner->values_rows);
		q->cte_names = std::move(inner->cte_names);
		q->cte_bodies = std::move(inner->cte_bodies);
		q->cte_column_names = std::move(inner->cte_column_names);
		return q;
	}
	if (at_kw("VALUES")) {
		p++;
		q->is_values = true;
		while (true) {
			expect_op("(");
			std::vector<std::unique_ptr<Expr>> row;
			while (true) {
				if (at_op(")")) { p++; break; }
				row.push_back(parse_expr(0));
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
			q->values_rows.push_back(std::move(row));
			if (accept_op(",")) continue;
			break;
		}
		return q;
	}
	expect_kw("SELECT");
	if (at_kw("DISTINCT")) { p++; q->distinct = true; }
	else if (at_kw("ALL")) p++;
	while (true) {
		SelectItem item;
		item.pos = cur().pos;
		if (at_op("*")) {
			p++;
			item.star = true;
			auto e = std::make_unique<Expr>(EK::Star);
			e->star = true;
			e->pos = item.pos;
			item.expr = std::move(e);
		} else {
			item.expr = parse_expr(0);
		}
		if (at_kw("AS")) { p++; item.alias = parse_identifier(); item.has_alias = true; }
		else if ((cur().type == Token::IDENT && !is_keyword(cur().value)) || cur().type == Token::QUOTED) { item.alias = cur().value; item.has_alias = true; p++; }
		q->select_list.push_back(std::move(item));
		if (accept_op(",")) continue;
		break;
	}
	if (at_kw("FROM")) { p++; q->from = parse_from_clause(); }
	if (at_kw("WHERE")) { p++; q->where = parse_expr(0); }
	if (at_kw("GROUP")) {
		p++;
		expect_kw("BY");
		while (true) {
			q->group_by.push_back(parse_expr(0));
			if (accept_op(",")) continue;
			break;
		}
	}
	if (at_kw("HAVING")) { p++; q->having = parse_expr(0); }
	return q;
}

