std::unique_ptr<TableRef> Parser::parse_table_ref() {
	auto tr = std::make_unique<TableRef>();
	tr->pos = cur().pos;
	if (at_op("(")) {
		p++;
		if (at_kw("SELECT") || at_kw("WITH") || at_kw("VALUES")) {
			auto q = parse_query(true);
			expect_op(")");
			tr->kind = TRK::Subquery;
			auto e = std::make_unique<Expr>(EK::Subquery);
			e->query = q.release();
			tr->query = std::move(e);
		} else {
			tr = parse_table_ref();
			expect_op(")");
		}
	} else if (at_kw("LATERAL") && peek().type == Token::OP && peek().value == "(") {
		p++;
		p++;
		auto q = parse_query(true);
		expect_op(")");
		tr->kind = TRK::Subquery;
		tr->lateral = true;
		auto e = std::make_unique<Expr>(EK::Subquery);
		e->query = q.release();
		tr->query = std::move(e);
	} else if (at_kw("VALUES")) {
		p++;
		tr->kind = TRK::Values;
		while (true) {
			expect_op("(");
			std::vector<std::unique_ptr<Expr>> row;
			while (true) {
				if (at_op(")")) { p++; break; }
				row.push_back(parse_expr(0));
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
			tr->values_rows.push_back(std::move(row));
			if (accept_op(",")) continue;
			break;
		}
	} else {
		// table name or table function
		std::string catalog, schema, name;
		name = parse_identifier();
		while (at_op(".")) {
			p++;
			std::string n2 = parse_identifier();
			catalog = schema;
			schema = name;
			name = n2;
			// may be followed by * for pg_catalog tables
			if (at_op("*")) { p++; }
		}
		if (at_op("(")) {
			// table function
			tr->kind = TRK::TableFunc;
			tr->name = name;
			tr->name_parts.push_back(schema);
			tr->name_parts.push_back(catalog);
			p++;
			auto args = parse_arg_list(nullptr, ")");
			for (auto &a : args) tr->using_columns.push_back(std::move(a));
		} else {
			tr->kind = TRK::Base;
			tr->name = name;
			tr->name_parts.push_back(schema);
			tr->name_parts.push_back(catalog);
		}
	}
	// alias
	if (at_kw("AS")) {
		p++;
		tr->alias = parse_identifier();
		if (at_op("(")) {
			p++;
			while (true) {
				if (at_op(")")) { p++; break; }
				tr->column_aliases.push_back(parse_identifier());
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
		}
	} else if ((cur().type == Token::IDENT && !is_keyword(cur().value)) || cur().type == Token::QUOTED) {
		tr->alias = cur().value;
		p++;
		if (at_op("(")) {
			p++;
			while (true) {
				if (at_op(")")) { p++; break; }
				tr->column_aliases.push_back(parse_identifier());
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
		}
	}
	// joins
	while (true) {
		int jt = -1;
		bool natural = false;
		if (at_op(",")) {
			jt = 4; // cross join
			p++;
		} else if (at_kw("JOIN")) {
			jt = 0;
			p++;
		} else if (at_kw("CROSS") && peek().type == Token::IDENT && iequals(peek().value, "JOIN")) {
			p += 2;
			jt = 4;
		} else if ((at_kw("INNER") || at_kw("LEFT") || at_kw("RIGHT") || at_kw("FULL") || at_kw("OUTER")) ) {
			std::string w = cur().value;
			p++;
			if (at_kw("OUTER")) p++;
			if (at_kw("JOIN")) { p++; }
			else if (at_kw("SEMI") || at_kw("ANTI")) { p++; expect_kw("JOIN"); }
			jt = iequals(w, "INNER") ? 0 : iequals(w, "LEFT") ? 1 : iequals(w, "RIGHT") ? 2 : 3;
		} else if (at_kw("NATURAL")) {
			p++;
			natural = true;
			if (at_kw("JOIN")) p++;
			else if (at_kw("LEFT") || at_kw("RIGHT") || at_kw("FULL")) { std::string w = cur().value; p++; if (at_kw("OUTER")) p++; expect_kw("JOIN"); jt = iequals(w, "LEFT") ? 1 : iequals(w, "RIGHT") ? 2 : 3; }
			jt = jt < 0 ? 0 : jt;
		} else break;
		if (natural && jt == -1) jt = 0;
		auto right = parse_table_ref();
		auto join = std::make_unique<TableRef>();
		join->kind = TRK::Join;
		join->join_type = jt;
		join->children.push_back(std::move(tr));
		join->children.push_back(std::move(right));
		if (at_kw("ON")) {
			p++;
			join->condition = parse_expr(0);
		} else if (at_kw("USING")) {
			p++;
			join->join_type = 5;
			expect_op("(");
			while (true) {
				if (at_op(")")) { p++; break; }
				join->using_columns.push_back(parse_expr(0));
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
		} else if (at_op("(")) {
			p++;
			if (at_op(")")) { p++; }
			else { syntax_error_here(); }
		}
		tr = std::move(join);
	}
	return tr;
}

std::unique_ptr<TableRef> Parser::parse_from_clause() {
	return parse_table_ref();
}

std::unique_ptr<Expr> Parser::parse_limit_expr() { return parse_expr(0); }

// -------------------------------------------------------------- statements
std::unique_ptr<Statement> Parser::parse_statement() {
	auto st = std::make_unique<Statement>();
	st->pos = cur().pos;
	st->raw_sql = sql;
	if (at_op("(") || at_kw("SELECT") || at_kw("WITH") || at_kw("VALUES") || at_kw("TABLE")) {
		st->kind = SK::Select;
		st->query = parse_query(true);
		return st;
	}
	if (at_kw("EXPLAIN")) {
		p++;
		st->kind = SK::Explain;
		if (at_kw("ANALYZE")) p++;
		st->query = parse_query(true);
		return st;
	}
	if (at_kw("PRAGMA")) { return parse_pragma(); }
	if (at_kw("SHOW")) { return parse_show(); }
	if (at_kw("DESCRIBE") || at_kw("DESC")) {
		p++;
		st->kind = SK::Describe;
		st->name_parts = parse_name_list(false);
		if (at_op("(")) { p++; }
		return st;
	}
	if (at_kw("CREATE")) { return parse_create(); }
	if (at_kw("INSERT")) { return parse_insert(); }
	if (at_kw("UPDATE")) { return parse_update(); }
	if (at_kw("DELETE")) { return parse_delete(); }
	if (at_kw("DROP")) { return parse_drop(); }
	if (at_kw("ALTER")) { return parse_alter(); }
	if (at_kw("SET") || at_kw("RESET")) { return parse_set(); }
	if (at_kw("COPY")) { return parse_copy(); }
	if (at_kw("ATTACH") || at_kw("USE") || at_kw("DETACH")) {
		std::string w = cur().value;
		p++;
		if (iequals(w, "USE")) {
			st->kind = SK::Attach;
			st->options.push_back(parse_identifier());
			st->txn_action = 3; // use
			return st;
		}
		if (iequals(w, "DETACH")) st->kind = SK::Detach;
		else st->kind = SK::Attach;
		if (at_kw("DATABASE")) p++;
		if (at_kw("IF")) {
			p++;
			if (at_kw("EXISTS") || at_kw("NOT")) { p++; }
			st->if_exists = true;
		}
		if (cur().type == Token::STRING) {
			st->file = cur().value;
			p++;
		} else {
			st->file = parse_identifier();
		}
		if (at_kw("AS")) {
			p++;
			st->table = parse_identifier();
		}
		if (at_op("(")) {
			p++;
			while (!at_op(")") && !at_end()) { st->options.push_back(cur().value); p++; }
			if (at_op(")")) p++;
		}
		return st;
	}
	if (at_kw("BEGIN") || at_kw("COMMIT") || at_kw("ROLLBACK") || at_kw("END") || at_kw("START") || at_kw("ABORT")) {
		std::string w = cur().value;
		p++;
		st->kind = SK::Transaction;
		if (iequals(w, "BEGIN") || iequals(w, "START")) st->txn_action = 1;
		else if (iequals(w, "COMMIT") || iequals(w, "END")) st->txn_action = 2;
		else st->txn_action = 3;
		while (!at_end() && !at_op(";")) p++;
		return st;
	}
	if (at_kw("CALL")) {
		p++;
		st->kind = SK::Call;
		st->call_name = parse_identifier();
		if (at_op("(")) {
			p++;
			auto args = parse_arg_list(nullptr, ")");
			for (auto &a : args) st->call_args.push_back(std::move(a));
		}
		return st;
	}
	if (at_kw("TRUNCATE")) {
		p++;
		st->kind = SK::Truncate;
		st->name_parts = parse_name_list(false);
		return st;
	}
	if (at_kw("VACUUM") || at_kw("CHECKPOINT") || at_kw("LOAD") || at_kw("INSTALL") || at_kw("FORCE") || at_kw("SUMMARY")) {
		st->kind = SK::Vacuum;
		while (!at_end() && !at_op(";")) p++;
		return st;
	}
	syntax_error_here();
	return st;
}

std::unique_ptr<Statement> Parser::parse_select_statement() {
	auto st = std::make_unique<Statement>();
	st->kind = SK::Select;
	st->query = parse_query(true);
	return st;
}

std::unique_ptr<Statement> Parser::parse_create() {
	auto st = std::make_unique<Statement>();
	p++; // CREATE
	if (at_kw("OR")) { p++; expect_kw("REPLACE"); st->or_replace = true; }
	bool temp = false;
	if (at_kw("TEMP") || at_kw("TEMPORARY")) { p++; temp = true; }
	st->temporary = temp;
	if (at_kw("TABLE")) {
		p++;
		st->kind = SK::CreateTable;
		if (at_kw("IF")) {
			p++;
			expect_kw("NOT");
			expect_kw("EXISTS");
			st->if_not_exists = true;
		}
		st->name_parts = parse_name_list(false);
		if (at_op("(")) {
			p++;
			while (true) {
				if (at_op(")")) { p++; break; }
				ColumnDef cd;
				cd.name = parse_identifier();
				if (at_op(".")) { p++; cd.name = parse_identifier(); }
				// type
				cd.type = parse_type();
				while (true) {
					if (at_kw("PRIMARY")) { p++; expect_kw("KEY"); cd.primary_key = true; continue; }
					if (at_kw("UNIQUE")) { p++; cd.unique = true; continue; }
					if (at_kw("NOT")) { p++; expect_kw("NULL"); cd.not_null = true; continue; }
					if (at_kw("NULL")) { p++; continue; }
					if (at_kw("DEFAULT")) {
						p++;
						cd.default_value = parse_expr(0);
						continue;
					}
					if (at_kw("CHECK")) { p++; if (at_op("(")) { p++; auto e = parse_expr(0); expect_op(")"); } continue; }
					if (at_kw("REFERENCES")) { p++; parse_identifier(); if (at_op("(")) { p++; while (!at_op(")") && !at_end()) p++; if (at_op(")")) p++; } continue; }
					if (at_kw("GENERATED")) {
						p++;
						if (at_kw("ALWAYS") || at_kw("BY")) p++;
						if (at_kw("AS")) {
							p++;
							if (at_op("(")) { p++; cd.generated_expr = parse_expr(0); expect_op(")"); }
							cd.generated = true;
						}
						if (at_kw("STORED") || at_kw("VIRTUAL")) p++;
						continue;
					}
					if (at_kw("AS")) {
						p++;
						if (at_op("(")) { p++; cd.generated_expr = parse_expr(0); expect_op(")"); }
						cd.generated = true;
						continue;
					}
					if (at_kw("COLLATE")) { p++; parse_identifier(); continue; }
					if (at_kw("COMMENT")) { p++; if (cur().type == Token::STRING) { p++; } continue; }
					if (at_kw("AUTOINCREMENT")) { p++; continue; }
					if (at_kw("KEY")) { p++; continue; }
					if (at_kw("CONSTRAINT")) { p++; parse_identifier(); continue; }
					break;
				}
				st->create_columns.push_back(std::move(cd));
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
			// table constraints
			while (at_op(",")) {
				p++;
				if (at_kw("PRIMARY")) { p++; expect_kw("KEY"); expect_op("("); while (!at_op(")") && !at_end()) p++; if (at_op(")")) p++; continue; }
				if (at_kw("UNIQUE")) { p++; expect_op("("); while (!at_op(")") && !at_end()) p++; if (at_op(")")) p++; continue; }
				if (at_kw("FOREIGN")) { p++; expect_kw("KEY"); expect_op("("); while (!at_op(")") && !at_end()) p++; if (at_op(")")) p++; if (at_kw("REFERENCES")) { p++; parse_identifier(); } continue; }
				if (at_kw("CHECK")) { p++; if (at_op("(")) { p++; parse_expr(0); expect_op(")"); } continue; }
				if (at_kw("CONSTRAINT")) { p++; parse_identifier(); continue; }
				syntax_error_here();
			}
		} else if (at_kw("AS")) {
			p++;
			st->as_select = true;
			st->create_query = parse_query(true);
		} else syntax_error_here();
		return st;
	}
	if (at_kw("VIEW")) {
		p++;
		st->kind = SK::CreateView;
		if (at_kw("IF")) { p++; expect_kw("NOT"); expect_kw("EXISTS"); st->if_not_exists = true; }
		st->name_parts = parse_name_list(false);
		if (at_op("(")) { p++; while (!at_op(")") && !at_end()) p++; if (at_op(")")) p++; }
		if (at_kw("AS")) {
			p++;
			st->as_select = true;
			st->create_query = parse_query(true);
		} else syntax_error_here();
		return st;
	}
	if (at_kw("SCHEMA")) {
		p++;
		st->kind = SK::CreateSchema;
		if (at_kw("IF")) { p++; expect_kw("NOT"); expect_kw("EXISTS"); st->if_not_exists = true; }
		st->table = parse_identifier();
		return st;
	}
	if (at_kw("SEQUENCE")) {
		p++;
		st->kind = SK::Vacuum;
		while (!at_end() && !at_op(";")) p++;
		return st;
	}
	if (at_kw("INDEX")) {
		p++;
		st->kind = SK::Vacuum;
		while (!at_end() && !at_op(";")) p++;
		return st;
	}
	if (at_kw("MACRO") || at_kw("FUNCTION")) {
		p++;
		st->kind = SK::Vacuum;
		while (!at_end() && !at_op(";")) p++;
		return st;
	}
	syntax_error_here();
	return st;
}

std::unique_ptr<Statement> Parser::parse_insert() {
	auto st = std::make_unique<Statement>();
	p++; // INSERT
	expect_kw("INTO");
	st->kind = SK::Insert;
	if (at_kw("OR")) {
		p++;
		if (at_kw("REPLACE") || at_kw("IGNORE")) p++;
	}
	st->name_parts = parse_name_list(false);
	if (at_op("(")) {
		p++;
		while (true) {
			if (at_op(")")) { p++; break; }
			st->columns.push_back(parse_identifier());
			if (accept_op(",")) continue;
			if (at_op(")")) { p++; break; }
			syntax_error_here();
		}
	}
	if (at_kw("VALUES")) {
		p++;
		while (true) {
			expect_op("(");
			std::vector<std::unique_ptr<Expr>> row;
			while (true) {
				if (at_op(")")) { p++; break; }
				if (at_kw("DEFAULT")) { p++; auto e = std::make_unique<Expr>(EK::Default); row.push_back(std::move(e)); }
				else row.push_back(parse_expr(0));
				if (accept_op(",")) continue;
				if (at_op(")")) { p++; break; }
				syntax_error_here();
			}
			st->values_rows.push_back(std::move(row));
			if (accept_op(",")) continue;
			break;
		}
	} else if (at_kw("SELECT") || at_kw("WITH") || at_op("(")) {
		if (at_op("(")) {
			p++;
			if (at_op("(")) {
				p++;
				st->source = parse_query(true);
				expect_op(")");
			} else {
				st->source = parse_query(true);
				expect_op(")");
			}
		} else {
			st->source = parse_query(true);
		}
	} else if (at_kw("DEFAULT")) {
		p++;
		expect_kw("VALUES");
	} else syntax_error_here();
	if (at_kw("ON")) {
		p++;
		if (at_kw("CONFLICT")) p++;
		while (!at_end() && !at_op(";")) p++;
	}
	if (at_kw("RETURNING")) {
		p++;
		st->kind = SK::Select;
		auto q = std::make_unique<Query>();
		q->from = parse_from_clause();
		st->query = std::move(q);
	}
	return st;
}

std::unique_ptr<Statement> Parser::parse_update() {
	auto st = std::make_unique<Statement>();
	p++;
	st->kind = SK::Update;
	st->name_parts = parse_name_list(false);
	if (at_kw("AS")) { p++; parse_identifier(); }
	expect_kw("SET");
	while (true) {
		std::string col = parse_identifier();
		if (at_op(".")) { p++; col = parse_identifier(); }
		expect_op("=");
		auto val = parse_expr(0);
		st->set_assignments.push_back({col, std::move(val)});
		if (accept_op(",")) continue;
		break;
	}
	if (at_kw("FROM")) {
		p++;
		parse_from_clause();
	}
	if (at_kw("WHERE")) {
		p++;
		st->where = parse_expr(0);
	}
	if (at_kw("RETURNING")) {
		p++;
		st->kind = SK::Select;
		auto q = std::make_unique<Query>();
		q->from = parse_from_clause();
		st->query = std::move(q);
	}
	return st;
}

std::unique_ptr<Statement> Parser::parse_delete() {
	auto st = std::make_unique<Statement>();
	p++;
	expect_kw("FROM");
	st->kind = SK::Delete;
	st->name_parts = parse_name_list(false);
	if (at_kw("WHERE")) {
		p++;
		st->where = parse_expr(0);
	}
	if (at_kw("RETURNING")) {
		p++;
		st->kind = SK::Select;
		auto q = std::make_unique<Query>();
		q->from = parse_from_clause();
		st->query = std::move(q);
	}
	return st;
}

std::unique_ptr<Statement> Parser::parse_drop() {
	auto st = std::make_unique<Statement>();
	p++;
	st->kind = SK::Drop;
	if (at_kw("TABLE")) st->table = "TABLE";
	else if (at_kw("VIEW")) st->table = "VIEW";
	else if (at_kw("SCHEMA")) st->table = "SCHEMA";
	else if (at_kw("SEQUENCE")) st->table = "SEQUENCE";
	else if (at_kw("INDEX")) st->table = "INDEX";
	else if (at_kw("MACRO") || at_kw("FUNCTION")) st->table = "FUNCTION";
	else if (at_kw("TYPE")) st->table = "TYPE";
	else syntax_error_here();
	p++;
	if (at_kw("IF")) {
		p++;
		expect_kw("EXISTS");
		st->if_exists = true;
	}
	st->name_parts = parse_name_list(false);
	while (!at_end() && !at_op(";")) p++;
	return st;
}

std::unique_ptr<Statement> Parser::parse_alter() {
	auto st = std::make_unique<Statement>();
	p++;
	st->kind = SK::Alter;
	if (at_kw("TABLE")) p++;
	else if (at_kw("VIEW")) p++;
	else if (at_kw("SEQUENCE")) p++;
	st->name_parts = parse_name_list(false);
	if (at_kw("RENAME")) {
		p++;
		if (at_kw("COLUMN")) {
			p++;
			st->action = 1;
			st->target_column = parse_identifier();
			expect_kw("TO");
			st->new_name = parse_identifier();
		} else if (at_kw("TO")) {
			p++;
			st->action = 0;
			st->new_name = parse_identifier();
		} else if (at_kw("CONSTRAINT")) {
			p++;
			st->action = 5;
			parse_identifier();
		} else syntax_error_here();
	} else if (at_kw("ADD")) {
		p++;
		if (at_kw("COLUMN")) p++;
		if (at_kw("CONSTRAINT") || at_kw("FOREIGN") || at_kw("PRIMARY") || at_kw("UNIQUE")) {
			st->action = 6;
			while (!at_end() && !at_op(";")) p++;
			return st;
		}
		st->action = 2;
		if (at_kw("IF")) { p++; expect_kw("NOT"); expect_kw("EXISTS"); st->if_not_exists = true; }
		ColumnDef cd;
		cd.name = parse_identifier();
		cd.type = parse_type();
		while (true) {
			if (at_kw("NOT")) { p++; expect_kw("NULL"); cd.not_null = true; continue; }
			if (at_kw("DEFAULT")) { p++; cd.default_value = parse_expr(0); continue; }
			if (at_kw("NULL")) { p++; continue; }
			if (at_kw("PRIMARY")) { p++; expect_kw("KEY"); cd.primary_key = true; continue; }
			if (at_kw("UNIQUE")) { p++; cd.unique = true; continue; }
			if (at_kw("REFERENCES")) { p++; parse_identifier(); continue; }
			if (at_kw("AS")) { p++; if (at_op("(")) { p++; cd.generated_expr = parse_expr(0); expect_op(")"); } cd.generated = true; continue; }
			break;
		}
		st->create_columns.push_back(std::move(cd));
	} else if (at_kw("DROP")) {
		p++;
		if (at_kw("COLUMN")) p++;
		if (at_kw("CONSTRAINT") || at_kw("PRIMARY")) { st->action = 6; while (!at_end() && !at_op(";")) p++; return st; }
		st->action = 3;
		if (at_kw("IF")) { p++; expect_kw("EXISTS"); st->if_exists = true; }
		st->target_column = parse_identifier();
	} else if (at_kw("ALTER")) {
		p++;
		if (at_kw("COLUMN")) p++;
		st->target_column = parse_identifier();
		if (at_kw("TYPE") || at_kw("SET")) {
			st->action = 4;
			if (at_kw("SET")) { p++; expect_kw("DATA"); expect_kw("TYPE"); }
			else p++;
			st->new_name = "";
			ColumnDef cd;
			cd.type = parse_type();
			st->create_columns.push_back(std::move(cd));
		} else {
			while (!at_end() && !at_op(";")) p++;
		}
	} else if (at_kw("SET")) {
		while (!at_end() && !at_op(";")) p++;
	} else if (at_kw("COLUMN")) {
		while (!at_end() && !at_op(";")) p++;
	} else syntax_error_here();
	return st;
}

std::unique_ptr<Statement> Parser::parse_set() {
	auto st = std::make_unique<Statement>();
	st->kind = SK::Set;
	bool reset = at_kw("RESET");
	p++;
	if (reset) {
		st->setting_name.push_back(parse_identifier());
		return st;
	}
	// SET [GLOBAL] name = value
	if (at_kw("GLOBAL")) p++;
	std::string first = parse_identifier();
	st->setting_name.push_back(first);
	while (at_op(".")) {
		p++;
		st->setting_name.push_back(parse_identifier());
	}
	if (at_op("=") || at_op("->")) {
		p++;
	} else if (at_kw("TO")) {
		p++;
	} else syntax_error_here();
	// value
	if (at_op("(")) {
		p++;
		st->pragma_expr = parse_expr(0);
		expect_op(")");
	} else {
		st->setting_value = parse_expr(0);
	}
	// extra set options: "SET x = y, z = w"
	while (accept_op(",")) {
		st->setting_name.push_back(parse_identifier());
		if (at_op("=")) p++;
		else if (at_kw("TO")) p++;
		st->setting_value = parse_expr(0);
	}
	return st;
}

std::unique_ptr<Statement> Parser::parse_pragma() {
	auto st = std::make_unique<Statement>();
	p++;
	st->kind = SK::Pragma;
	st->pragma_name = parse_identifier();
	if (at_op(".")) { p++; st->pragma_name += "." + parse_identifier(); }
	if (at_op("=")) {
		p++;
		if (cur().type == Token::STRING) { st->pragma_args.push_back(cur().value); p++; }
		else st->pragma_args.push_back(cur().text);
		return st;
	}
	if (at_op("(")) {
		p++;
		if (cur().type == Token::STRING) { st->pragma_args.push_back(cur().value); p++; }
		else if (at_op(")")) { }
		else { st->pragma_args.push_back(cur().text); p++; }
		while (accept_op(",")) { st->pragma_args.push_back(cur().text); p++; }
		expect_op(")");
	}
	return st;
}

std::unique_ptr<Statement> Parser::parse_show() {
	auto st = std::make_unique<Statement>();
	p++;
	st->kind = SK::Show;
	if (at_kw("ALL") || at_kw("TABLES")) {
		st->table = cur().value;
		p++;
		if (at_kw("TABLES")) st->table = "TABLES";
		return st;
	}
	if (at_op("*")) { p++; st->table = "TABLES"; return st; }
	st->table = "";
	st->name_parts = parse_name_list(false);
	return st;
}

std::unique_ptr<Statement> Parser::parse_copy() {
	auto st = std::make_unique<Statement>();
	p++;
	st->kind = SK::Copy;
	if (at_op("(")) {
		p++;
		st->source = parse_query(true);
		expect_op(")");
	} else {
		st->name_parts = parse_name_list(false);
	}
	if (at_kw("TO")) {
		p++;
		st->txn_action = 1; // to
	} else if (at_kw("FROM")) {
		p++;
		st->txn_action = 2; // from
	} else syntax_error_here();
	if (cur().type == Token::STRING) {
		st->file = cur().value;
		p++;
	} else syntax_error_here();
	if (at_op("(")) {
		p++;
		while (!at_op(")") && !at_end()) {
			if (cur().type == Token::IDENT) st->options.push_back(to_lower(cur().value));
			p++;
		}
		if (at_op(")")) p++;
	} else if (at_kw("FORMAT")) {
		p++;
		if (cur().type == Token::IDENT) st->options.push_back(to_lower(cur().value));
		p++;
	}
	return st;
}

std::vector<std::unique_ptr<Statement>> parse_statements(const std::string &sql) {
	std::vector<std::unique_ptr<Statement>> out;
	Parser parser(sql);
	parser.stmt_begin = 0;
	while (true) {
		while (parser.at_op(";")) parser.p++;
		if (parser.at_end()) break;
		parser.stmt_begin = parser.cur().pos;
		auto st = parser.parse_statement();
		st->pos = parser.stmt_begin;
		out.push_back(std::move(st));
		if (parser.at_op(";")) { parser.p++; continue; }
		if (parser.at_end()) break;
		// trailing garbage
		parser.syntax_error_here();
	}
	return out;
}

std::unique_ptr<Expr> parse_expression_text(const std::string &text) {
	Parser parser(text);
	if (parser.at_end()) throw_parser("empty expression");
	auto e = parser.parse_expr(0);
	if (!parser.at_end()) {
		throw DuckDBException(DuckDBException::Type::PARSER, "syntax error at or near \"" + parser.cur().value + "\"").with_location(0, parser.cur().pos);
	}
	return e;
}

