std::string format_option_help(const std::string &prog) {
	std::string out;
	out += "\x1b[1mUsage: \x1b[0m\x1b[32m" + prog + "\x1b[0m\x1b[33m [OPTIONS] FILENAME [SQL]\n\n";
	out += "\x1b[0m\x1b[1mFILENAME\x1b[0m is the name of a DuckDB database. A new database is created\nif the file does not previously exist.\n\n";
	out += "\x1b[1mOPTIONS:\n\x1b[0m";
	for (int i = 0; i < kOptionHelpCount; i++) {
		std::string line = "\x1b[32m  " + std::string(kOptionHelp[i].name) + "\x1b[0m";
		if (kOptionHelp[i].arg[0]) line += "\x1b[33m " + std::string(kOptionHelp[i].arg) + "\x1b[0m";
		int len = 2 + (int)strlen(kOptionHelp[i].name);
		if (kOptionHelp[i].arg[0]) len += 1 + (int)strlen(kOptionHelp[i].arg);
		while (len < 27) { line += " "; len++; }
		line += kOptionHelp[i].desc;
		out += line + "\n";
	}
	return out;
}

std::string dot_help_footer_text() {
	std::string o;
	for (int i = 0; i < kDotHelpFooterCount; i++) o += kDotHelpFooter[i] + std::string("\n");
	return o;
}

static bool pattern_match(const std::string &pat, const std::string &name) {
	if (pat.empty()) return true;
	return to_lower(name).find(to_lower(pat)) != std::string::npos;
}

std::string format_dot_help(const std::string &pattern, bool all) {
	std::string out;
	for (int i = 0; i < kDotHelpCount; i++) {
		std::string name = kDotHelp[i].name;
		std::string args = kDotHelp[i].args;
		if (!pattern_match(pattern, name.substr(1)) && !pattern_match(pattern, name)) continue;
		std::string line = "\x1b[32m" + name + "\x1b[0m\x1b[33m " + args + "\x1b[0m";
		int len = (int)name.size() + 1 + (int)args.size();
		while (len < 41) { line += " "; len++; }
		line += kDotHelp[i].desc;
		out += line + "\n";
		if (all && kDotExtra[i].lines) {
			out += std::string(kDotExtra[i].lines);
		}
	}
	return out;
}

