std::string format_option_help(const std::string &prog) {
	std::string out;
	out += "\x1b[1mUsage: \x1b[0m\x1b[32m" + prog + "\x1b[0m\x1b[33m [OPTIONS] FILENAME [SQL]\n\n";
	out += "\x1b[0m\x1b[1mFILENAME\x1b[0m is the name of a DuckDB database. A new database is created\nif the file does not previously exist.\n\n";
	out += "\x1b[1mOPTIONS:\n\x1b[0m";
	for (int i = 0; i < kOptionHelpCount; i++) {
		std::string line = "\x1b[32m  " + std::string(kOptionHelp[i].name) + "\x1b[0m";
		if (kOptionHelp[i].arg[0]) line += "\x1b[33m " + std::string(kOptionHelp[i].arg) + "\x1b[0m";
		int len = 2 + (int)strlen(kOptionHelp[i].name);
		if (kOptionHelp[i].arg[0]) len += 1 + (int)strlen(kOptionHelp[i].arg);
		while (len < 27) { line += " "; len++; }
		line += kOptionHelp[i].desc;
		out += line + "\n";
	}
	return out;
