}

static bool pattern_match(const std::string &pat, const std::string &name) {
	if (pat.empty()) return true;
	return to_lower(name).find(to_lower(pat)) != std::string::npos;
}

std::string format_dot_help(const std::string &pattern, bool all) {
	std::string out;
	for (int i = 0; i < kDotHelpCount; i++) {
		std::string name = kDotHelp[i].name;
		std::string args = kDotHelp[i].args;
		if (!pattern_match(pattern, name.substr(1)) && !pattern_match(pattern, name)) continue;
		std::string line = "\x1b[32m" + name + "\x1b[0m\x1b[33m " + args + "\x1b[0m";
		int len = (int)name.size() + 1 + (int)args.size();
		while (len < 41) { line += " "; len++; }
		line += kDotHelp[i].desc;
		out += line + "\n";
		if (all && kDotExtra[i].lines) {
			out += std::string(kDotExtra[i].lines);
		}
	}
	return out;
}

