// catalog definitions
#pragma once
#include "value.hpp"

namespace ddb {

struct Column {
	std::string name;
	LogicalType type;
	Value default_value;
	bool not_null = false;
	bool primary_key = false;
	bool unique = false;
	bool generated = false;
	std::string comment;
};

struct Table {
	std::string name;
	std::string schema = "main";
	std::vector<Column> columns;
	std::vector<std::vector<Value>> rows;
	bool is_view = false;
	std::string view_sql;
	std::string create_sql;
	bool temporary = false;
