		for (auto &c : columns) o.push_back(c.name);
		return o;
	}
	int column_index(const std::string &n) const {
		for (size_t i = 0; i < columns.size(); i++) if (iequals(columns[i].name, n)) return (int)i;
		return -1;
	}
};

struct Schema {
	std::string name;
	std::vector<std::shared_ptr<Table>> tables;
	std::shared_ptr<Table> find(const std::string &n, bool ignore_case = true) {
		for (auto &t : tables) if (iequals(t->name, n)) return t;
		return nullptr;
	}
};

struct Database {
	std::string name = "memory";
	std::string path = ":memory:";
	bool read_only = false;
	bool attached = false;
	std::vector<Schema> schemas;
	Schema *find_schema(const std::string &n, bool ignore_case = true) {
		for (auto &s : schemas) if (iequals(s.name, n)) return &s;
		return nullptr;
	}
	Schema *main_schema() { return find_schema("main"); }
	std::shared_ptr<Table> find_table(const std::string &schema, const std::string &name, bool ignore_case = true) {
		Schema *s = schema.empty() ? main_schema() : find_schema(schema, ignore_case);
		if (!s) return nullptr;
		return s->find(name, ignore_case);
	}
	std::shared_ptr<Table> find_table(const std::string &name) { return find_table("", name); }
};

// ---------------------------------------------------------------- functions
enum class FuncKind { Scalar, Aggregate, Table, Macro, Window };

struct FuncDef {
	std::string name;        // canonical (lowercase) name
	std::string display;     // how it is printed as a name (without arguments); "%s" = name
	int min_args = 0;
	int max_args = 1000;
	bool has_star_arg = false;   // count(*)
	bool has_variadic = false;
	FuncKind kind = FuncKind::Scalar;
	// return type
	std::function<LogicalType(const std::vector<LogicalType> &)> ret;
	std::function<Value(const std::vector<Value> &)> eval;
	// aggregates
	std::function<Value()> agg_init;
	std::function<void(Value &, const Value &)> agg_step;
	std::function<Value(Value &)> agg_final;
	// table functions
	std::function<bool(const std::vector<Value> &, std::vector<std::string> &, std::vector<LogicalType> &)> table_info;
	std::function<bool(const std::vector<Value> &, std::vector<std::string> &, std::vector<LogicalType> &, std::vector<std::vector<Value>> &, std::string &)> table_eval;
};

// function lookup
const FuncDef *find_function(const std::string &name);
FuncDef *add_function(const FuncDef &def);
void init_functions();

// helpers shared with the executor
Value func_concat(const std::vector<Value> &args);
std::string format_bigint(__int128 v);

} // namespace ddb
CPPEOF
echo catalog ok"}

