#include "catalog.hpp"
#include "value.hpp"
#include "ops.hpp"
#include "common.hpp"
#include <cmath>

namespace ddb {

static std::unordered_map<std::string, FuncDef> g_funcs;
static std::vector<FuncDef> g_funcs_storage;

const FuncDef *find_function(const std::string &name) {
	auto it = g_funcs.find(to_lower(name));
	if (it == g_funcs.end()) return nullptr;
	return &it->second;
}

FuncDef *add_function(const FuncDef &def) {
	g_funcs_storage.push_back(def);
	FuncDef *d = &g_funcs_storage.back();
	g_funcs[to_lower(def.name)] = *d;
	return d;
}

std::string format_bigint(__int128 v) { return huge_to_string(v); }

// ------------------------------------------------------------- helpers
static Value f_str(const std::vector<Value> &a, size_t i) { return a[i]; }
static bool arg_null(const std::vector<Value> &a) { for (auto &v : a) if (v.null) return true; return false; }
static double arg_d(const std::vector<Value> &a, size_t i) { return a[i].as_double(); }
static int64_t arg_i(const std::vector<Value> &a, size_t i) { return a[i].as_int(); }
static std::string arg_s(const std::vector<Value> &a, size_t i) { return a[i].s; }

static LogicalType t_double(const std::vector<LogicalType> &) { return LogicalType(TId::DOUBLE); }
static LogicalType t_varchar(const std::vector<LogicalType> &) { return LogicalType(TId::VARCHAR); }
static LogicalType t_bool(const std::vector<LogicalType> &) { return LogicalType(TId::BOOLEAN); }
static LogicalType t_int64(const std::vector<LogicalType> &) { return LogicalType(TId::BIGINT); }
static LogicalType t_first(const std::vector<LogicalType> &a) { return a.empty() ? LogicalType(TId::UNKNOWN) : a[0]; }
static LogicalType t_float(const std::vector<LogicalType> &) { return LogicalType(TId::FLOAT); }

static Value V(double d) { return Value::dbl(d); }
static Value Vb(bool b) { return Value::boolean(b); }
static Value Vi(int64_t i) { return Value::integer(i, TId::BIGINT); }
static Value Vs(const std::string &s) { return Value::str(s); }
static Value Vnull(const LogicalType &t) { return Value::nullval(t); }

// ---------------------------------------------------------------- math
static void init_math() {
	{
		FuncDef f;
		f.name = "abs"; f.min_args = 1; f.max_args = 1;
		f.ret = [](const std::vector<LogicalType> &a) { return a.empty() ? LogicalType() : a[0]; };
		f.eval = [](const std::vector<Value> &a) -> Value {
			if (a[0].null) return Vnull(a[0].type);
			if (a[0].type.id == TId::DECIMAL) return Value::decimalv(a[0].big < 0 ? -a[0].big : a[0].big, a[0].type.scale, a[0].type);
			if (a[0].type.id == TId::FLOAT || a[0].type.id == TId::DOUBLE) return Value(a[0].d < 0 ? -a[0].d : a[0].d);
			if (a[0].type.id == TId::HUGEINT) return Value::hugeint(a[0].big < 0 ? -a[0].big : a[0].big);
			if (tid_is_unsigned(a[0].type.id)) return a[0];
			return Value::intv(a[0].i < 0 ? -a[0].i : a[0].i, a[0].type);
		};
		add_function(f);
	}
	struct MathFn { const char *n; const char *disp; double (*fn)(double); int nargs; };
	MathFn mathfns[] = {
		{"sqrt","sqrt",[](double d){ return std::sqrt(d); },1},
		{"sin","sin",[](double d){ return std::sin(d); },1},
		{"cos","cos",[](double d){ return std::cos(d); },1},
		{"tan","tan",[](double d){ return std::tan(d); },1},
		{"asin","asin",[](double d){ return std::asin(d); },1},
		{"acos","acos",[](double d){ return std::acos(d); },1},
		{"atan","atan",[](double d){ return std::atan(d); },1},
		{"cbrt","cbrt",[](double d){ return std::cbrt(d); },1},
