// ----------------------------------------------------------------- strings
static bool like_match(const std::string &text, const std::string &pattern, bool ci) {
	// SQL LIKE with % and _
	size_t p = 0, t = 0;
	size_t star_p = (size_t)-1, star_t = 0;
	while (t < text.size()) {
		if (p < pattern.size() && (pattern[p] == '_' || (pattern[p] == '%' ))) {
			if (pattern[p] == '%') {
				star_p = p; star_t = t;
				p++;
				continue;
			}
			t++;
			p++;
			continue;
		}
		if (p < pattern.size() && (ci ? tolower(pattern[p]) == tolower(text[t]) : pattern[p] == text[t])) {
			t++; p++;
			continue;
		}
		if (star_p != (size_t)-1) { star_t++; t = star_t; p = star_p + 1; continue; }
		return false;
	}
	while (p < pattern.size() && pattern[p] == '%') p++;
	return p == pattern.size();
}

static bool glob_match(const std::string &text, const std::string &pattern) {
	size_t p = 0, t = 0;
	size_t star_p = (size_t)-1, star_t = 0;
	while (t < text.size()) {
		if (p < pattern.size() && pattern[p] == '*') { star_p = p; star_t = t; p++; continue; }
		if (p < pattern.size() && pattern[p] == '?') { t++; p++; continue; }
		if (p < pattern.size() && pattern[p] == '[') {
			// character class
			size_t q = p + 1;
			bool neg = false;
			if (q < pattern.size() && (pattern[q] == '^' || pattern[q] == '!')) { neg = true; q++; }
			bool match = false;
			char first = 0;
			while (q < pattern.size() && pattern[q] != ']') {
				if (pattern[q] == '-' && q + 1 < pattern.size() && pattern[q + 1] != ']' && q > p + 1 + (neg ? 1 : 0)) {
					if ((unsigned char)first <= (unsigned char)text[t] && (unsigned char)text[t] <= (unsigned char)pattern[q + 1]) match = true;
					q += 2;
				} else { first = pattern[q]; if (pattern[q] == text[t]) match = true; q++; }
			}
			if (q < pattern.size()) q++;
			if (match != neg) { p = q; t++; continue; }
		} else if (p < pattern.size() && pattern[p] == text[t]) { t++; p++; continue; }
		if (star_p != (size_t)-1) { star_t++; t = star_t; p = star_p + 1; continue; }
		return false;
	}
	while (p < pattern.size() && pattern[p] == '*') p++;
	return p == pattern.size();
}

static std::vector<std::string> regex_escape_split(const std::string &s, const std::string &sep) {
	std::vector<std::string> out;
	if (sep.empty()) { out.push_back(s); return out; }
	size_t pos = 0;
	while (true) {
		size_t e = s.find(sep, pos);
		if (e == std::string::npos) { out.push_back(s.substr(pos)); break; }
		out.push_back(s.substr(pos, e - pos));
		pos = e + sep.size();
	}
	return out;
}

