struct RegexNode;
struct RegexNode {
	virtual ~RegexNode() {}
	virtual bool match(const std::string &s, size_t &pos) const = 0;
};
struct RChar : RegexNode { std::string chars; bool match(const std::string &s, size_t &pos) const override { return false; } };
struct RSeq : RegexNode { std::vector<std::unique_ptr<RegexNode>> items; bool match(const std::string &s, size_t &pos) const override { return false; } };

// simple backtracking regex (subset)
struct SimpleRegex {
