};

// Parse a regex into an AST of nodes with quantifiers
struct RNode;
enum class RKind { Char, Any, Class, Group, Star, Plus, Opt, Alt, Anchor, Backref };
struct RNode {
	RKind kind;
	std::string chars;             // Char / Class chars (negated flag in num)
	std::vector<std::unique_ptr<RNode>> children;
	std::vector<std::vector<std::unique_ptr<RNode>>> alts;
	int num = 0;
};

static std::unique_ptr<RNode> r_parse_alt(const std::string &p, size_t &pos, int depth);
static std::unique_ptr<RNode> r_parse_atom(const std::string &p, size_t &pos, int depth) {
	if (pos >= p.size()) return nullptr;
	char c = p[pos];
	if (c == '(') {
		pos++;
		bool capture = true;
		if (pos + 1 < p.size() && p[pos] == '?') { capture = false; pos++; }
