		g->kind = RKind::Group;
		auto alt = r_parse_alt(p, pos, depth + 1);
		if (alt) g->alts.push_back(std::move(alt));
		while (pos < p.size() && p[pos] == '|') {
			pos++;
			auto a = r_parse_alt(p, pos, depth + 1);
			if (a) g->alts.push_back(std::move(a));
		}
		if (pos < p.size() && p[pos] == ')') pos++;
		return g;
	}
	if (c == '[') {
		pos++;
		auto n = std::make_unique<RNode>();
		n->kind = RKind::Class;
		if (pos < p.size() && (p[pos] == '^' || p[pos] == '!')) { n->num = 1; pos++; }
		if (pos < p.size() && p[pos] == ']') { n->chars += ']'; pos++; }
		while (pos < p.size() && p[pos] != ']') {
			if (p[pos] == '\\' && pos + 1 < p.size()) { n->chars += p[pos + 1]; pos += 2; continue; }
			if (pos + 2 < p.size() && p[pos + 1] == '-' && p[pos + 2] != ']') {
				for (char c2 = p[pos]; c2 <= p[pos + 2]; c2++) n->chars += c2;
				pos += 3;
				continue;
			}
			n->chars += p[pos];
			pos++;
		}
		if (pos < p.size() && p[pos] == ']') pos++;
		return n;
	}
	if (c == '.') { pos++; auto n = std::make_unique<RNode>(); n->kind = RKind::Any; return n; }
	if (c == '\\' && pos + 1 < p.size()) {
		char n2 = p[pos + 1];
		if (n2 == 'd' || n2 == 'w' || n2 == 's' || n2 == 'D' || n2 == 'W' || n2 == 'S') {
			pos += 2;
			auto n = std::make_unique<RNode>();
			n->kind = RKind::Class;
			n->num = 2;
			n->chars = n2;
			return n;
		}
		if (n2 == 'b' || n2 == 'B' || n2 == '^' || n2 == '$') {
			pos += 2;
			auto n = std::make_unique<RNode>();
			n->kind = RKind::Anchor;
			n->chars = n2;
			return n;
		}
		if (isdigit((unsigned char)n2)) {
			pos += 2;
			auto n = std::make_unique<RNode>();
			n->kind = RKind::Backref;
			n->num = n2 - '0';
			return n;
		}
		pos += 2;
		auto n = std::make_unique<RNode>();
		n->kind = RKind::Char;
		n->chars = n2;
		return n;
	}
	if (c == '^' || c == '$') {
		pos++;
		auto n = std::make_unique<RNode>();
		n->kind = RKind::Anchor;
		n->chars = c;
		return n;
	}
	pos++;
	auto n = std::make_unique<RNode>();
	n->kind = RKind::Char;
	n->chars = c;
	return n;
