static std::vector<std::unique_ptr<RNode>> r_parse_seq(const std::string &p, size_t &pos, int depth) {
	std::vector<std::unique_ptr<RNode>> out;
	while (pos < p.size() && p[pos] != '|' && p[pos] != ')') {
		auto atom = r_parse_atom(p, pos, depth);
		if (!atom) break;
		// quantifiers
		while (pos < p.size()) {
			char q = p[pos];
			int minr = 0, maxr = 0;
			bool greedy = true;
			if (q == '*') { pos++; minr = 0; maxr = -1; }
			else if (q == '+') { pos++; minr = 1; maxr = -1; }
			else if (q == '?') { pos++; minr = 0; maxr = 1; }
			else if (q == '{') {
				size_t end = p.find('}', pos);
				if (end != std::string::npos) {
					std::string spec = p.substr(pos + 1, end - pos - 1);
					auto parts = split_string(spec, ',');
					if (parts.size() == 1) { minr = maxr = atoi(parts[0].c_str()); }
					else { minr = atoi(parts[0].c_str()); maxr = parts[1].empty() ? -1 : atoi(parts[1].c_str()); }
					pos = end + 1;
				} else break;
			} else break;
			if (pos < p.size() && p[pos] == '?') { greedy = false; pos++; }
			auto qn = std::make_unique<RNode>();
			qn->kind = q == '*' ? RKind::Star : (minr == 1 && maxr == 1 ? RKind::Char : (minr == 0 ? RKind::Opt : RKind::Plus));
			qn->num = (int)greedy * 2;
			qn->num = minr * 10 + (maxr < 0 ? 1 : maxr) + (greedy ? 100 : 0);
			qn->children.push_back(std::move(atom));
			out.push_back(std::move(qn));
			atom = std::move(out.back());
			// rewrap: convert quantified node into children
			if (!out.empty()) { }
			break;
		}
		if (out.empty() || out.back().get() != atom.get()) {
			out.push_back(std::move(atom));
		}
	}
	return out;
}

static std::unique_ptr<RNode> r_parse_alt(const std::string &p, size_t &pos, int depth) {
	auto n = std::make_unique<RNode>();
	n->kind = RKind::Alt;
	n->alts.push_back(r_parse_seq(p, pos, depth));
	while (pos < p.size() && p[pos] == '|') {
		pos++;
		n->alts.push_back(r_parse_seq(p, pos, depth));
	}
	return n;
}

