static bool r_match_seq(const std::vector<std::unique_ptr<RNode>> &seq, size_t idx, const std::string &s, size_t &pos,
                        std::vector<std::string> &caps) {
	if (idx >= seq.size()) return true;
	// try to match with backtracking
	std::function<bool(size_t, size_t)> rec = [&](size_t i, size_t p) -> bool {
		if (i >= seq.size()) { pos = p; return true; }
		const RNode &n = *seq[i];
		if (n.kind == RKind::Star || n.kind == RKind::Plus || n.kind == RKind::Opt) {
			int minr = (n.num % 100) / 10;
			int maxr = n.num % 10;
			if (n.children.empty()) return rec(i + 1, p);
			std::function<bool(int, size_t)> rep = [&](int count, size_t pp) -> bool {
				if (count >= minr) {
					if (rec(i + 1, pp)) { pos = pp; return true; }
				}
				if (maxr < 0 || count < maxr) {
					size_t save = pp;
					size_t np = pp;
					if (r_match_seq(*n.children[0], 0, s, np, caps)) {
						if (np != save) if (rep(count + 1, np)) return true;
					}
				}
				return false;
			};
			return rep(0, p);
		}
		size_t np = p;
		if (!r_match_seq(n.children.size() ? *n.children[0] : *(RNode *)nullptr, 0, s, np, caps)) {
			// normal node
			np = p;
			if (!r_match_node(n, s, np, caps)) return false;
		}
		return rec(i + 1, np);
	};
	size_t res = pos;
	if (rec(idx, pos)) { res = pos; return true; }
	return false;
}

