struct RegexNode;
struct RegexNode {
	virtual ~RegexNode() {}
	virtual bool match(const std::string &s, size_t &pos) const = 0;
};
struct RChar : RegexNode { std::string chars; bool match(const std::string &s, size_t &pos) const override { return false; } };
struct RSeq : RegexNode { std::vector<std::unique_ptr<RegexNode>> items; bool match(const std::string &s, size_t &pos) const override { return false; } };

// simple backtracking regex (subset)
struct SimpleRegex {
	std::string pat;
	bool anchored_start = false;
	bool anchored_end = false;
	SimpleRegex(const std::string &p) : pat(p) {}
};

// Parse a regex into an AST of nodes with quantifiers
struct RNode;
enum class RKind { Char, Any, Class, Group, Star, Plus, Opt, Alt, Anchor, Backref };
struct RNode {
	RKind kind;
	std::string chars;             // Char / Class chars (negated flag in num)
	std::vector<std::unique_ptr<RNode>> children;
	std::vector<std::vector<std::unique_ptr<RNode>>> alts;
	int num = 0;
};

static std::unique_ptr<RNode> r_parse_alt(const std::string &p, size_t &pos, int depth);
static std::unique_ptr<RNode> r_parse_atom(const std::string &p, size_t &pos, int depth) {
	if (pos >= p.size()) return nullptr;
	char c = p[pos];
	if (c == '(') {
		pos++;
		bool capture = true;
		if (pos + 1 < p.size() && p[pos] == '?') { capture = false; pos++; }
		auto g = std::make_unique<RNode>();
		g->kind = RKind::Group;
		auto alt = r_parse_alt(p, pos, depth + 1);
		if (alt) g->alts.push_back(std::move(alt));
		while (pos < p.size() && p[pos] == '|') {
			pos++;
			auto a = r_parse_alt(p, pos, depth + 1);
			if (a) g->alts.push_back(std::move(a));
		}
		if (pos < p.size() && p[pos] == ')') pos++;
		return g;
	}
	if (c == '[') {
		pos++;
		auto n = std::make_unique<RNode>();
		n->kind = RKind::Class;
		if (pos < p.size() && (p[pos] == '^' || p[pos] == '!')) { n->num = 1; pos++; }
		if (pos < p.size() && p[pos] == ']') { n->chars += ']'; pos++; }
		while (pos < p.size() && p[pos] != ']') {
			if (p[pos] == '\\' && pos + 1 < p.size()) { n->chars += p[pos + 1]; pos += 2; continue; }
			if (pos + 2 < p.size() && p[pos + 1] == '-' && p[pos + 2] != ']') {
				for (char c2 = p[pos]; c2 <= p[pos + 2]; c2++) n->chars += c2;
				pos += 3;
				continue;
			}
			n->chars += p[pos];
			pos++;
		}
		if (pos < p.size() && p[pos] == ']') pos++;
		return n;
	}
	if (c == '.') { pos++; auto n = std::make_unique<RNode>(); n->kind = RKind::Any; return n; }
	if (c == '\\' && pos + 1 < p.size()) {
		char n2 = p[pos + 1];
		if (n2 == 'd' || n2 == 'w' || n2 == 's' || n2 == 'D' || n2 == 'W' || n2 == 'S') {
			pos += 2;
			auto n = std::make_unique<RNode>();
			n->kind = RKind::Class;
			n->num = 2;
			n->chars = n2;
			return n;
		}
		if (n2 == 'b' || n2 == 'B' || n2 == '^' || n2 == '$') {
			pos += 2;
			auto n = std::make_unique<RNode>();
			n->kind = RKind::Anchor;
			n->chars = n2;
			return n;
		}
		if (isdigit((unsigned char)n2)) {
			pos += 2;
			auto n = std::make_unique<RNode>();
			n->kind = RKind::Backref;
			n->num = n2 - '0';
			return n;
		}
		pos += 2;
		auto n = std::make_unique<RNode>();
		n->kind = RKind::Char;
		n->chars = n2;
		return n;
	}
	if (c == '^' || c == '$') {
		pos++;
		auto n = std::make_unique<RNode>();
		n->kind = RKind::Anchor;
		n->chars = c;
		return n;
	}
	pos++;
	auto n = std::make_unique<RNode>();
	n->kind = RKind::Char;
	n->chars = c;
	return n;
}

static std::vector<std::unique_ptr<RNode>> r_parse_seq(const std::string &p, size_t &pos, int depth) {
	std::vector<std::unique_ptr<RNode>> out;
	while (pos < p.size() && p[pos] != '|' && p[pos] != ')') {
		auto atom = r_parse_atom(p, pos, depth);
		if (!atom) break;
		// quantifiers
		while (pos < p.size()) {
			char q = p[pos];
			int minr = 0, maxr = 0;
			bool greedy = true;
			if (q == '*') { pos++; minr = 0; maxr = -1; }
			else if (q == '+') { pos++; minr = 1; maxr = -1; }
			else if (q == '?') { pos++; minr = 0; maxr = 1; }
			else if (q == '{') {
				size_t end = p.find('}', pos);
				if (end != std::string::npos) {
					std::string spec = p.substr(pos + 1, end - pos - 1);
					auto parts = split_string(spec, ',');
					if (parts.size() == 1) { minr = maxr = atoi(parts[0].c_str()); }
					else { minr = atoi(parts[0].c_str()); maxr = parts[1].empty() ? -1 : atoi(parts[1].c_str()); }
					pos = end + 1;
				} else break;
			} else break;
			if (pos < p.size() && p[pos] == '?') { greedy = false; pos++; }
			auto qn = std::make_unique<RNode>();
			qn->kind = q == '*' ? RKind::Star : (minr == 1 && maxr == 1 ? RKind::Char : (minr == 0 ? RKind::Opt : RKind::Plus));
			qn->num = (int)greedy * 2;
			qn->num = minr * 10 + (maxr < 0 ? 1 : maxr) + (greedy ? 100 : 0);
			qn->children.push_back(std::move(atom));
			out.push_back(std::move(qn));
			atom = std::move(out.back());
			// rewrap: convert quantified node into children
			if (!out.empty()) { }
			break;
		}
		if (out.empty() || out.back().get() != atom.get()) {
			out.push_back(std::move(atom));
		}
	}
	return out;
}

static std::unique_ptr<RNode> r_parse_alt(const std::string &p, size_t &pos, int depth) {
	auto n = std::make_unique<RNode>();
	n->kind = RKind::Alt;
	n->alts.push_back(r_parse_seq(p, pos, depth));
	while (pos < p.size() && p[pos] == '|') {
		pos++;
		n->alts.push_back(r_parse_seq(p, pos, depth));
	}
	return n;
}

static bool r_match_seq(const std::vector<std::unique_ptr<RNode>> &seq, size_t idx, const std::string &s, size_t &pos,
                        std::vector<std::string> &caps);

static bool r_match_node(const RNode &n, const std::string &s, size_t &pos, std::vector<std::string> &caps) {
	switch (n.kind) {
	case RKind::Char:
		if (pos < s.size() && s[pos] == n.chars[0]) { pos++; return true; }
		return false;
	case RKind::Any:
		if (pos < s.size() && s[pos] != '\n') { pos++; return true; }
		return false;
	case RKind::Class: {
		if (pos >= s.size()) return false;
		char c = s[pos];
		bool found = false;
		if (n.num == 2) {
			switch (n.chars[0]) {
			case 'd': found = isdigit((unsigned char)c); break;
			case 'w': found = isalnum((unsigned char)c) || c == '_'; break;
			case 's': found = isspace((unsigned char)c); break;
			case 'D': found = !isdigit((unsigned char)c); break;
			case 'W': found = !(isalnum((unsigned char)c) || c == '_'); break;
			case 'S': found = !isspace((unsigned char)c); break;
			}
		} else {
			for (char x : n.chars) if (x == c) found = true;
			if (n.num == 1) found = !found;
		}
		if (found) { pos++; return true; }
		return false;
	}
	case RKind::Group: {
		for (auto &alt : n.alts) {
			size_t save = pos;
			std::vector<std::string> savecaps = caps;
			if (r_match_seq(*alt, 0, s, pos, caps)) {
				if (n.num > 0) {
					if ((size_t)n.num < caps.size()) caps[n.num - 1] = s.substr(save, pos - save);
					else caps.push_back(s.substr(save, pos - save));
				}
				return true;
			}
			caps = savecaps;
			pos = save;
		}
		return false;
	}
	case RKind::Anchor:
		if (n.chars == "^") return pos == 0;
		if (n.chars == "$") return pos == s.size();
		if (n.chars == "\\b") {
			bool before = pos > 0 && (isalnum((unsigned char)s[pos - 1]) || s[pos - 1] == '_');
			bool after = pos < s.size() && (isalnum((unsigned char)s[pos]) || s[pos] == '_');
			return before != after;
		}
		if (n.chars == "\\B") {
			bool before = pos > 0 && (isalnum((unsigned char)s[pos - 1]) || s[pos - 1] == '_');
			bool after = pos < s.size() && (isalnum((unsigned char)s[pos]) || s[pos] == '_');
			return before == after;
		}
		return true;
	case RKind::Opt: case RKind::Star: case RKind::Plus: {
		int minr = n.num / 100 >= 1 ? (n.num % 100) / 10 : (n.num % 100) / 10;
		int maxr = n.num % 10;
		bool greedy = n.num >= 100;
		(void)greedy;
		// greedy backtracking
		std::function<bool(int, size_t)> tryrep = [&](int count, size_t start) -> bool {
			if (count >= minr && (maxr < 0 || count <= maxr)) {
				size_t save = pos;
				if (r_match_seq(*(n.children[0].get() ? nullptr : nullptr), 0, s, pos, caps)) { }
			}
			return false;
		};
		// iterative greedy with recursion
		auto rep = [&](auto &&self, int count, size_t start) -> bool {
			if (greedy) {
				if (maxr < 0 || count < maxr) {
					size_t save = pos;
					if (r_match_seq(n.children.size() ? *n.children[0] : *(RNode *)nullptr, 0, s, pos, caps)) {
						if (pos == save) { /* empty match; stop */ }
						else if (self(self, count + 1, pos)) return true;
						pos = save;
					}
				}
				if (count >= minr) return true;
				return false;
			} else {
				if (count >= minr) {
					size_t save = pos;
					if (r_match_seq(n.children[0] ? *n.children[0] : *(RNode *)nullptr, 0, s, pos, caps)) {
						pos = save;
					}
					return true;
				}
				return false;
			}
		};
		// handle empty-body quantifiers safely
		if (!n.children.empty()) {
			return rep(rep, 0, pos);
		}
		return minr == 0;
	}
	default: return false;
	}
}

static bool r_match_seq(const std::vector<std::unique_ptr<RNode>> &seq, size_t idx, const std::string &s, size_t &pos,
                        std::vector<std::string> &caps) {
	if (idx >= seq.size()) return true;
	// try to match with backtracking
	std::function<bool(size_t, size_t)> rec = [&](size_t i, size_t p) -> bool {
		if (i >= seq.size()) { pos = p; return true; }
		const RNode &n = *seq[i];
		if (n.kind == RKind::Star || n.kind == RKind::Plus || n.kind == RKind::Opt) {
			int minr = (n.num % 100) / 10;
			int maxr = n.num % 10;
			if (n.children.empty()) return rec(i + 1, p);
			std::function<bool(int, size_t)> rep = [&](int count, size_t pp) -> bool {
				if (count >= minr) {
					if (rec(i + 1, pp)) { pos = pp; return true; }
				}
				if (maxr < 0 || count < maxr) {
					size_t save = pp;
					size_t np = pp;
					if (r_match_seq(*n.children[0], 0, s, np, caps)) {
						if (np != save) if (rep(count + 1, np)) return true;
					}
				}
				return false;
			};
			return rep(0, p);
		}
		size_t np = p;
		if (!r_match_seq(n.children.size() ? *n.children[0] : *(RNode *)nullptr, 0, s, np, caps)) {
			// normal node
			np = p;
			if (!r_match_node(n, s, np, caps)) return false;
		}
		return rec(i + 1, np);
	};
	size_t res = pos;
	if (rec(idx, pos)) { res = pos; return true; }
	return false;
}

