std::string simple_regex_replace(const std::string &s, const std::string &pattern, const std::string &repl, bool global) {
	std::string out;
	size_t i = 0;
	bool replaced = false;
	while (i <= s.size()) {
		size_t pos = 0;
		auto root = r_parse_alt(pattern, pos, 0);
		bool matched = false;
		size_t best_len = 0;
		size_t match_start = i;
		for (size_t start = i; start <= s.size(); start++) {
			size_t p2 = start;
			if (r_match_seq(root->alts[0], 0, s, p2)) {
				matched = true;
				match_start = start;
				best_len = p2 - start;
				break;
			}
		}
