			out += s.substr(0, match_start);
			// substitute \1 references
			std::string rp = repl;
			out += simple_regex_expand(repl, s.substr(match_start, best_len));
			i = match_start + best_len;
			replaced = true;
			s = s.substr(i);
			i = 0;
			if (!global) break;
			if (s.empty()) break;
			continue;
		}
		break;
	}
	out += s;
	return out;
}

std::string simple_regex_extract(const std::string &s, const std::string &pattern, int group) {
	size_t pos = 0;
	auto root = r_parse_alt(pattern, pos, 0);
	for (size_t start = 0; start <= s.size(); start++) {
		size_t p2 = start;
		if (r_match_seq(root->alts[0], 0, s, p2)) {
			if (group == 0) return s.substr(start, p2 - start);
			return "";
