	}
	return "";
}

std::string simple_regex_expand(const std::string &repl, const std::string &matched) {
	std::string out;
	for (size_t i = 0; i < repl.size(); i++) {
		if (repl[i] == '\\' && i + 1 < repl.size()) {
			char c = repl[i + 1];
			if (isdigit((unsigned char)c)) { out += (c == '1') ? matched : ""; i++; continue; }
			out += c;
			i++;
			continue;
		}
		out += repl[i];
	}
	return out;
}

std::string base_n(int64_t value, int base) {
	if (base < 2 || base > 36) return std::to_string(value);
	const char *digits = "0123456789abcdefghijklmnopqrstuvwxyz";
	std::string out;
	bool neg = value < 0;
	unsigned long long v = neg ? (unsigned long long)(-value) : (unsigned long long)value;
	if (v == 0) return "0";
	while (v) { out = digits[v % base] + out; v /= base; }
	if (neg) out = "-" + out;
	return out;
}

