// ---------------------------------------------------------------- regex
enum class RKind { Char, Any, Class, Group, Quant, Anchor };

struct RNode {
	RKind kind = RKind::Char;
	std::string chars;
	bool negated = false;
	bool greedy = true;
	int minr = 0, maxr = 0;
	std::vector<std::vector<std::unique_ptr<RNode>>> alts;
	std::vector<std::unique_ptr<RNode>> children;
};

using RSeq = std::vector<std::unique_ptr<RNode>>;

static RSeq r_parse_alt(const std::string &p, size_t &pos, int depth);

static std::unique_ptr<RNode> r_parse_atom(const std::string &p, size_t &pos, int depth) {
	auto n = std::make_unique<RNode>();
	if (pos >= p.size()) return nullptr;
	char c = p[pos];
	switch (c) {
	case '(': {
		pos++;
		auto g = std::make_unique<RNode>();
		g->kind = RKind::Group;
		g->alts.push_back(r_parse_alt(p, pos, depth + 1));
		while (pos < p.size() && p[pos] == '|') {
			pos++;
			g->alts.push_back(r_parse_alt(p, pos, depth + 1));
		}
		if (pos < p.size() && p[pos] == ')') pos++;
		return g;
	}
	case '[': {
		pos++;
		n->kind = RKind::Class;
		if (pos < p.size() && p[pos] == '^') { n->negated = true; pos++; }
		while (pos < p.size() && p[pos] != ']') {
			if (p[pos] == '\\' && pos + 1 < p.size()) { n->chars += p[pos + 1]; pos += 2; continue; }
			if (pos + 2 < p.size() && p[pos + 1] == '-' && p[pos + 2] != ']') {
				for (char x = p[pos]; x <= p[pos + 2]; x++) n->chars += x;
				pos += 3;
				continue;
			}
			n->chars += p[pos];
			pos++;
		}
		if (pos < p.size() && p[pos] == ']') pos++;
		return n;
	}
	case '.': pos++; n->kind = RKind::Any; return n;
	case '^': pos++; n->kind = RKind::Anchor; n->chars = "^"; return n;
	case '$': pos++; n->kind = RKind::Anchor; n->chars = "$"; return n;
	case '\\': {
		if (pos + 1 >= p.size()) { pos++; n->kind = RKind::Char; n->chars = "\\"; return n; }
		char n2 = p[pos + 1];
		if (n2 == 'd' || n2 == 'w' || n2 == 's' || n2 == 'D' || n2 == 'W' || n2 == 'S') {
			pos += 2;
			n->kind = RKind::Class;
			n->negated = isupper((unsigned char)n2) != 0;
			n->chars = to_lower(std::string(1, n2));
			return n;
		}
		if (n2 == 'b' || n2 == 'B') {
			pos += 2;
			n->kind = RKind::Anchor;
			n->chars = to_lower(std::string(1, n2));
			return n;
		}
		pos += 2;
		n->kind = RKind::Char;
		n->chars = n2;
		return n;
	}
	default:
		pos++;
		n->kind = RKind::Char;
		n->chars = c;
		return n;
	}
}

static bool r_match_seq(const RSeq &seq, size_t idx, const std::string &s, size_t &pos);

static bool r_match_node(const RNode &n, const std::string &s, size_t &pos) {
	switch (n.kind) {
	case RKind::Char:
		if (pos < s.size() && s[pos] == n.chars[0]) { pos++; return true; }
		return false;
	case RKind::Any:
		if (pos < s.size() && s[pos] != '\n') { pos++; return true; }
		return false;
	case RKind::Class: {
		if (pos >= s.size()) return false;
		char c = s[pos];
		bool found = false;
		if (n.chars == "d") { found = isdigit((unsigned char)c) != 0; }
		else if (n.chars == "w") { found = isalnum((unsigned char)c) || c == '_'; }
		else if (n.chars == "s") { found = isspace((unsigned char)c) != 0; }
		else { for (char x : n.chars) if (x == c) found = true; }
		if (n.negated) found = !found;
		if (found) { pos++; return true; }
		return false;
	}
	case RKind::Anchor:
		if (n.chars == "^") return pos == 0;
		if (n.chars == "$") return pos == s.size();
		if (n.chars == "b") {
			bool before = pos > 0 && (isalnum((unsigned char)s[pos - 1]) || s[pos - 1] == '_');
			bool after = pos < s.size() && (isalnum((unsigned char)s[pos]) || s[pos] == '_');
			return before != after;
		}
		if (n.chars == "B") {
			bool before = pos > 0 && (isalnum((unsigned char)s[pos - 1]) || s[pos - 1] == '_');
			bool after = pos < s.size() && (isalnum((unsigned char)s[pos]) || s[pos] == '_');
			return before == after;
		}
		return true;
	case RKind::Group: {
		for (auto &alt : n.alts) {
			size_t save = pos;
			if (r_match_seq(*alt, 0, s, pos)) return true;
			pos = save;
		}
		return false;
	}
	default: return false;
	}
}

static bool r_match_seq(const RSeq &seq, size_t idx, const std::string &s, size_t &pos) {
	if (idx >= seq.size()) return true;
	const RNode &n = *seq[idx];
	if (n.kind == RKind::Quant) {
		if (n.children.empty()) return n.minr == 0 && r_match_seq(seq, idx + 1, s, pos);
		auto rep = [&](auto &&self, int count, size_t p) -> bool {
			if (n.greedy) {
				if (n.maxr < 0 || count < n.maxr) {
					size_t np = p;
					if (r_match_seq(*n.children[0], 0, s, np)) {
						if (np != p) {
							if (self(count + 1, np)) return true;
						} else {
							// empty match: treat as satisfying the min
						}
					}
				}
				if (count >= n.minr) { pos = p; return r_match_seq(seq, idx + 1, s, pos); }
				return false;
			} else {
				if (count >= n.minr) {
					size_t save = pos;
					pos = p;
					if (r_match_seq(seq, idx + 1, s, pos)) return true;
					pos = save;
				}
				if (n.maxr < 0 || count < n.maxr) {
					size_t np = p;
					if (r_match_seq(*n.children[0], 0, s, np)) {
						if (np != p) return self(count + 1, np);
					}
				}
				return false;
			}
		};
		return rep(0, pos);
	}
	size_t np = pos;
	if (!r_match_node(n, s, np)) return false;
	return r_match_seq(seq, idx + 1, s, np);
}

static RSeq r_parse_alt(const std::string &p, size_t &pos, int depth) {
	RSeq out;
	while (pos < p.size() && p[pos] != '|' && p[pos] != ')') {
		auto atom = r_parse_atom(p, pos, depth);
		if (!atom) break;
		int minr = 0, maxr = 0;
		bool greedy = true;
		if (pos < p.size()) {
			char q = p[pos];
			if (q == '*') { pos++; minr = 0; maxr = -1; }
			else if (q == '+') { pos++; minr = 1; maxr = -1; }
			else if (q == '?') { pos++; minr = 0; maxr = 1; greedy = false; }
			else if (q == '{') {
				size_t end = p.find('}', pos);
				if (end != std::string::npos) {
					std::string spec = p.substr(pos + 1, end - pos - 1);
					auto parts = split_string(spec, ',');
					if (parts.size() == 1) { minr = maxr = atoi(parts[0].c_str()); }
					else { minr = atoi(parts[0].c_str()); maxr = parts.size() > 1 && !parts[1].empty() ? atoi(parts[1].c_str()) : -1; }
					pos = end + 1;
				}
			}
			if (pos < p.size() && p[pos] == '?') { greedy = false; pos++; }
		}
		if (minr != 0 || maxr != 0) {
			auto qn = std::make_unique<RNode>();
			qn->kind = RKind::Quant;
			qn->minr = minr;
			qn->maxr = maxr;
			qn->greedy = greedy;
			qn->children.push_back(std::move(atom));
			out.push_back(std::move(qn));
		} else {
			out.push_back(std::move(atom));
		}
	}
	return out;
}

static std::unique_ptr<RNode> r_parse_top(const std::string &p) {
	size_t pos = 0;
	auto root = std::make_unique<RNode>();
	root->kind = RKind::Group;
	root->alts.push_back(r_parse_alt(p, pos, 0));
	while (pos < p.size() && p[pos] == '|') {
		pos++;
		root->alts.push_back(r_parse_alt(p, pos, 0));
	}
	return root;
}

bool simple_regex_search(const std::string &s, const std::string &pattern) {
	auto root = r_parse_top(pattern);
	for (size_t start = 0; start <= s.size(); start++) {
		size_t p2 = start;
		if (r_match_seq(root->alts[0], 0, s, p2)) return true;
	}
	return false;
}

bool simple_regex_full_match(const std::string &s, const std::string &pattern) {
	auto root = r_parse_top(pattern);
	for (size_t start = 0; start <= s.size(); start++) {
		size_t p2 = start;
		if (r_match_seq(root->alts[0], 0, s, p2) && p2 == s.size()) return true;
	}
	return false;
}

static bool r_match_at(const std::string &s, size_t start, const std::unique_ptr<RNode> &root, size_t &endpos) {
	size_t p2 = start;
	if (r_match_seq(root->alts[0], 0, s, p2)) {
		endpos = p2;
		return true;
	}
	return false;
}

std::string simple_regex_replace(const std::string &s, const std::string &pattern, const std::string &repl, bool global) {
	auto root = r_parse_top(pattern);
	std::string out;
	size_t i = 0;
	while (i <= s.size()) {
		size_t end = 0;
		size_t found = std::string::npos;
		for (size_t start = i; start <= s.size(); start++) {
			if (r_match_at(s, start, root, end)) { found = start; break; }
		}
		if (found == std::string::npos) break;
		out += s.substr(i, found - i);
		out += simple_regex_expand(repl, s.substr(found, end - found));
		i = end;
		if (end == found) i++; // avoid infinite loop on empty match
		if (!global) break;
	}
	out += s.substr(std::min(i, s.size()));
	return out;
}

std::string simple_regex_extract(const std::string &s, const std::string &pattern, int group) {
	(void)group;
	auto root = r_parse_top(pattern);
	for (size_t start = 0; start <= s.size(); start++) {
		size_t end = 0;
		if (r_match_at(s, start, root, end)) return s.substr(start, end - start);
	}
	return "";
}

std::string simple_regex_expand(const std::string &repl, const std::string &matched) {
	std::string out;
	for (size_t i = 0; i < repl.size(); i++) {
		if (repl[i] == '\\' && i + 1 < repl.size()) {
			char c = repl[i + 1];
			if (isdigit((unsigned char)c)) { out += (c == '1') ? matched : ""; i++; continue; }
			out += c;
			i++;
			continue;
		}
		out += repl[i];
	}
	return out;
}

std::string base_n(int64_t value, int base) {
	if (base < 2 || base > 36) return std::to_string(value);
	const char *digits = "0123456789abcdefghijklmnopqrstuvwxyz";
	std::string out;
	bool neg = value < 0;
	unsigned long long v = neg ? (unsigned long long)(-value) : (unsigned long long)value;
	if (v == 0) return "0";
	while (v) { out = digits[v % base] + out; v /= base; }
	if (neg) out = "-" + out;
	return out;
}

