		f.eval = [](const std::vector<Value> &a) -> Value {
			if (a[0].null) return Vnull(a[0].type);
			auto items = a[0].children;
			std::reverse(items.begin(), items.end());
			return Value::listval(items, a[0].type);
		};
		add_function(f);
	}
	{
		FuncDef f; f.name = "list_distinct"; f.min_args = 1; f.max_args = 1;
		f.ret = [](const std::vector<LogicalType> &a) { return a.empty() ? LogicalType() : a[0]; };
