			auto items = a[0].children;
			bool desc = a.size() > 1 && to_lower(a[1].to_string()) == "desc";
			std::sort(items.begin(), items.end(), [desc](const Value &x, const Value &y) {
				if (x.null && y.null) return false;
				if (x.null) return !desc;
				if (y.null) return desc;
				return desc ? x.compare(y) > 0 : x.compare(y) < 0;
			});
			return Value::listval(items, a[0].type);
		};
		add_function(f);
	}
	{
		FuncDef f; f.name = "list_resize"; f.min_args = 2; f.max_args = 3;
