			if (a[0].null || a[1].null) return Vnull(a[0].type);
			auto items = a[0].children;
			int64_t n = a[1].as_int();
			Value fill = a.size() > 2 ? a[2] : Vnull(items.empty() ? LogicalType() : items[0].type);
			while ((int64_t)items.size() < n) items.push_back(fill);
			while ((int64_t)items.size() > n) items.pop_back();
			return Value::listval(items, a[0].type);
		};
