			if (a[0].null) return Vnull(LogicalType(TId::UNKNOWN));
			Value total;
			bool any = false;
			for (auto &c : a[0].children) {
				if (c.null) continue;
				if (!any) { total = c; any = true; continue; }
				total = apply_binary_op(OP_ADD, total, c);
