			else if (a.size() == 2) { start = a[0].as_int(); stop = a[1].as_int(); }
			else { start = a[0].as_int(); stop = a[1].as_int(); step = a[2].as_int(); }
			if (step == 0) return Vnull(LogicalType::list_type(LogicalType(TId::BIGINT)));
			std::vector<Value> items;
			if (step > 0) for (int64_t i = start; i < stop; i += step) items.push_back(Value::intv(i, TId::BIGINT));
			else for (int64_t i = start; i > stop; i += step) items.push_back(Value::intv(i, TId::BIGINT));
