		add_function(f);
	}
	{
		FuncDef f; f.name = "generate_series"; f.min_args = 1; f.max_args = 3; f.ret = [](const std::vector<LogicalType> &) { return LogicalType::list_type(LogicalType(TId::BIGINT)); };
