// ------------------------------------------------------------------ dates
static int64_t ts_micros(const Value &v) {
	if (v.type.id == TId::TIMESTAMP || v.type.id == TId::TIMESTAMP_TZ) return v.i;
	if (v.type.id == TId::DATE) return v.i * 86400000000LL;
	if (v.type.id == TId::TIME) return v.i;
	return (int64_t)(v.as_double() * 1000000.0);
}

