				if (i) o += ", ";
				o += expr_name_impl(e->args[i].get());
			}
			return o + " )";
		}
		const FuncDef *def = find_function("list_value");
		return "main." + func_display_name(def, false) + "(" + args_to_name(e->args) + ")";
	}
	case EK::StructCtor: {
		std::string args;
		for (size_t i = 0; i < e->args.size(); i++) {
			if (i) args += ", ";
			args += (e->args[i]->text.empty() ? "v" + std::to_string(i + 1) : e->args[i]->text) + " := " + expr_name_impl(e->args[i].get());
		}
		return "main.struct_pack(" + args + ")";
	}
	case EK::MapCtor: {
		std::string args;
		for (size_t i = 0; i < e->args.size(); i++) {
			if (i) args += ", ";
			args += expr_name_impl(e->args[i].get()) + " := " + expr_name_impl(e->extra[i].get());
		}
		return "main.map(" + args + ")";
	}
	case EK::Window: return expr_name_impl(e->args.empty() ? nullptr : e->args[0].get());
	case EK::Collate: return "(" + expr_name_impl(e->args[0].get()) + " COLLATE \"" + e->text + "\")";
	case EK::Default: return "DEFAULT";
	default: return e->text;
	}
}

std::string expr_name(const Expr *e, const std::string &alias) {
	if (!alias.empty()) return alias;
	return expr_name_impl(e);
}

