// --------------------------------------------------------------- evaluation
static Value eval_like_expr(const Expr *e, Scope &scope, Engine *eng) {
	Value l = eval_expr(e->args[0].get(), scope, eng);
	Value r = eval_expr(e->args[1].get(), scope, eng);
	if (l.null || r.null) return Value::nullval(LogicalType(TId::BOOLEAN));
	std::string s = l.to_string(), p = r.to_string();
	bool res = false;
	if (e->text == "glob") res = glob_match_impl(s, p);
	else if (e->text == "regexp_matches" || e->text == "regexp") res = simple_regex_search(s, p);
	else if (e->text == "similar_to") res = simple_regex_search(s, p);
	else res = like_match_impl(s, p, e->case_insensitive);
	return Value::boolean(e->negated ? !res : res);
}

Value eval_expr(const Expr *e, Scope &scope, Engine *eng) {
	if (!e) return Value();
	switch (e->kind) {
	case EK::ColumnRef: {
		if (e->bound_index >= 0 && (size_t)e->bound_index < scope.cols.size()) {
			if (!scope.row) return Value::nullval(scope.cols[e->bound_index].type);
			return (*scope.row)[e->bound_index];
		}
		int ti = -1;
		int idx = scope.resolve(e->table, e->column, ti);
		if (idx < 0) idx = scope.resolve_any(e->column);
		if (idx >= 0) {
			if (!scope.row) return Value::nullval(scope.cols[idx].type);
			return (*scope.row)[idx];
		}
		if (scope.parent) {
			Scope ps = *scope.parent;
			ps.row = scope.parent->row;
			ps.cols = scope.parent->cols;
			ps.agg_results = scope.parent->agg_results;
