// ------------------------------------------------------- aggregate handling
static void collect_exprs(Expr *e, int &agg_counter, int &win_counter, bool inside_agg, bool inside_win) {
	if (!e) return;
	if (e->kind == EK::Subquery || e->kind == EK::Exists) return; // subqueries have their own scope
	if (e->kind == EK::Func) {
		if (e->op == 200) { // FILTER
			if (e->args.size() >= 1) {
				Expr *inner = e->args[0].get();
				const FuncDef *def = find_function(inner->text);
				if (def && def->kind == FuncKind::Aggregate) {
					if (inside_agg) {
						throw DuckDBException(DuckDBException::Type::BINDER, "aggregate function calls cannot be nested").with_location(e->pos, e->pos);
					}
					inner->is_aggregate = true;
					inner->agg_id = agg_counter++;
					e->is_aggregate = true;
					e->agg_id = inner->agg_id;
					inside_agg = true;
					for (auto &a : inner->args) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
					return;
				}
			}
		}
		const FuncDef *def = find_function(e->text);
		if (def && def->kind == FuncKind::Aggregate && !inside_agg) {
			e->is_aggregate = true;
			e->agg_id = agg_counter++;
			for (auto &a : e->args) collect_exprs(a.get(), agg_counter, win_counter, true, inside_win);
			return;
		}
		if (e->flags.size() > 0 && e->flags[0] && !inside_win) {
			e->is_window = true;
			e->window_id = win_counter++;
			for (auto &a : e->partition_by) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
			for (auto &a : e->order_by_exprs) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
			return;
		}
	}
	for (auto &a : e->args) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
	for (auto &a : e->extra) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
	for (auto &a : e->partition_by) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
	for (auto &a : e->order_by_exprs) collect_exprs(a.get(), agg_counter, win_counter, inside_agg, inside_win);
}

static bool has_aggregate(const Expr *e) {
	if (!e) return false;
	if (e->kind == EK::Subquery || e->kind == EK::Exists) return false;
	if (e->is_aggregate) return true;
	for (auto &a : e->args) if (has_aggregate(a.get())) return true;
	for (auto &a : e->extra) if (has_aggregate(a.get())) return true;
	return false;
}

static bool has_window(const Expr *e) {
	if (!e) return false;
	if (e->is_window) return true;
	for (auto &a : e->args) if (has_window(a.get())) return true;
	return false;
}

