	std::vector<std::vector<Value>> source_rep; // representative source row per result row
	Scope sc;
	sc.cols = src.cols;
	sc.parent = outer;
	if (any_agg || !q.group_by.empty()) {
		// resolve group by expressions (alias / position references)
		std::vector<const Expr *> group_exprs;
		for (auto &g : q.group_by) {
			const Expr *ge = g.get();
			if (ge->kind == EK::Constant && ge->value.type.is_integral()) {
				int64_t n = ge->value.as_int();
				if (n >= 1 && n <= (int64_t)outcols.size()) ge = outcols[n - 1].expr;
			} else if (ge->kind == EK::ColumnRef && ge->table.empty()) {
				bool matched = false;
				for (size_t i = 0; i < outcols.size(); i++) {
					if (i < q.select_list.size() && !q.select_list[i].alias.empty() && iequals(q.select_list[i].alias, ge->column)) {
						ge = outcols[i].expr;
						matched = true;
						break;
					}
				}
				if (!matched) {
					// maybe it is a select expression's column name
					for (size_t i = 0; i < outcols.size(); i++) {
						if (iequals(outcols[i].name, ge->column) && outcols[i].expr && outcols[i].expr->kind != EK::ColumnRef) {
							ge = outcols[i].expr;
							matched = true;
							break;
						}
					}
				}
			}
			group_exprs.push_back(ge);
		}
		std::vector<std::vector<Value>> keys;
		std::vector<std::vector<std::vector<Value> *>> groups;
		for (auto &row : src.rows) {
			sc.row = &row;
			sc.agg_results = nullptr;
			std::vector<Value> key;
			for (auto *ge : group_exprs) key.push_back(eval_expr(ge, sc, this));
			size_t found = (size_t)-1;
			for (size_t i = 0; i < keys.size(); i++) {
				bool eq = keys[i].size() == key.size();
				for (size_t k = 0; eq && k < key.size(); k++) {
					if (keys[i][k].null && key[k].null) continue;
					if (keys[i][k].null != key[k].null) { eq = false; break; }
					if (!keys[i][k].equals(key[k])) { eq = false; break; }
				}
				if (eq) { found = i; break; }
			}
			if (found == (size_t)-1) {
				keys.push_back(key);
				groups.push_back({});
				found = groups.size() - 1;
			}
			groups[found].push_back(&row);
		}
		// compute per group
		for (auto &g : groups) {
			std::vector<Value> ar = compute_aggs(g, sc);
			sc.agg_results = &ar;
			sc.row = g.empty() ? nullptr : g[0];
			std::vector<Value> out;
			for (auto &oc : outcols) {
				Value v = eval_expr(oc.expr, sc, this);
				out.push_back(v);
			}
			if (q.having) {
				sc.row = g.empty() ? nullptr : g[0];
				sc.agg_results = &ar;
				Value hv = eval_expr(q.having.get(), sc, this);
				if (hv.null || !hv.as_bool()) continue;
			}
			result_rows.push_back(out);
			source_rep.push_back(g.empty() ? std::vector<Value>() : *g[0]);
			if (!g.empty()) sc.agg_results = nullptr;
		}
		if (!q.having && q.group_by.empty() && !agg_exprs.empty()) {
			// aggregate without group by: no groups means one empty group
			if (result_rows.empty()) {
				std::vector<Value> ar = compute_aggs({}, sc);
				sc.agg_results = &ar;
				sc.row = nullptr;
				std::vector<Value> out;
				for (auto &oc : outcols) out.push_back(eval_expr(oc.expr, sc, this));
				result_rows.push_back(out);
				source_rep.push_back({});
			}
		}
	} else {
		for (auto &row : src.rows) {
			result_rows.push_back(compute_row(row, nullptr, nullptr, sc));
			source_rep.push_back(row);
		}
	}
	// window functions
	if (any_window) {
		std::vector<Value> wr(windows.size());
		for (size_t w = 0; w < windows.size(); w++) {
			Expr *we = windows[w];
			if (!we) continue;
			Expr *inner = we->args.empty() ? nullptr : we->args[0].get();
			const FuncDef *def = inner ? find_function(inner->text) : nullptr;
			// partition + order
			std::vector<int> order(result_rows.size());
			for (size_t i = 0; i < order.size(); i++) order[i] = (int)i;
			Scope wsc;
			wsc.cols = src.cols;
			wsc.parent = outer;
			std::vector<std::vector<Value>> pkeys;
			for (auto &row : source_rep) {
				wsc.row = &row;
				std::vector<Value> k;
				for (auto &p : we->partition_by) k.push_back(eval_expr(p.get(), wsc, this));
				pkeys.push_back(k);
			}
			// sort by partition then order by
			std::vector<int> sortkeys;
			for (size_t i = 0; i < order.size(); i++) {
				// sort by partition, then by order by exprs
			}
			std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
				for (size_t k = 0; k < pkeys.size(); k++) {
					const Value &x = pkeys[a][k], &y = pkeys[b][k];
					if (x.null && y.null) continue;
					if (x.null) return false;
					if (y.null) return true;
					int c = x.compare(y);
					if (c != 0) return c < 0;
				}
				for (size_t k = 0; k < we->order_by_exprs.size(); k++) {
					wsc.row = &source_rep[a];
					Value x = eval_expr(we->order_by_exprs[k].get(), wsc, this);
					wsc.row = &source_rep[b];
					Value y = eval_expr(we->order_by_exprs[k].get(), wsc, this);
					bool desc = k < we->order_by_desc.size() ? we->order_by_desc[k] : false;
					if (x.null && y.null) continue;
					if (x.null) return desc;
					if (y.null) return !desc;
					int c = x.compare(y);
					if (c != 0) return desc ? c > 0 : c < 0;
				}
				return false;
			});
			// compute per partition
			size_t i = 0;
			std::vector<Value> results(result_rows.size(), Value::nullval(LogicalType(TId::UNKNOWN)));
			while (i < order.size()) {
				size_t j = i;
				while (j < order.size() && pkeys[order[j]] == pkeys[order[i]]) j++;
				size_t n = j - i;
				for (size_t k = i; k < j; k++) {
					int ri = order[k];
					Value v;
					if (def && def->kind == FuncKind::Aggregate) {
						if (inner->text == "row_number") {
							v = Value::intv((int64_t)(k - i) + 1, TId::BIGINT);
						} else if (inner->text == "rank") {
							int64_t r = 1;
							for (size_t m = i; m < k; m++) {
								bool same = false;
								if (m == i) same = true;
								else {
									same = true;
									for (size_t kk = 0; kk < we->order_by_exprs.size(); kk++) {
										wsc.row = &source_rep[order[m]];
										Value x = eval_expr(we->order_by_exprs[kk].get(), wsc, this);
										wsc.row = &source_rep[ri];
										Value y = eval_expr(we->order_by_exprs[kk].get(), wsc, this);
										if (x.null != y.null || (!x.null && x.compare(y) != 0)) { same = false; break; }
									}
								}
								if (!same) r++;
							}
							v = Value::intv(r, TId::BIGINT);
						} else if (inner->text == "dense_rank") {
							v = Value::intv((int64_t)0, TId::BIGINT);
						} else {
							// aggregate over the frame (default: whole partition)
							std::vector<std::vector<Value> *> rows;
							for (size_t m = i; m < j; m++) rows.push_back(&source_rep[order[m]]);
							Scope asc;
							asc.cols = src.cols;
							asc.parent = outer;
							v = compute_aggs(rows, asc)[0];
						}
					} else {
						v = Value::nullval(LogicalType(TId::UNKNOWN));
					}
					results[ri] = v;
				}
				i = j;
			}
			wr[w] = Value(); // placeholder
			win_results_buf[w] = Value();
			// store into a per-row map
			for (size_t r2 = 0; r2 < result_rows.size(); r2++) {
				// handled below
			}
			win_row_values.push_back(results);
		}
	}

