// ------------------------------------------------------- query execution
static bool type_infer_expr(const Expr *e, const SourceData &src, std::vector<Expr *> &agg_exprs, LogicalType &out);

Result Engine::execute_query(const Query &q, Scope *outer) {
	Result res;
	size_t temp_save = g_temp_tables.size();
	try {
		// CTEs
		for (size_t i = 0; i < q.cte_names.size(); i++) {
			auto t = std::make_shared<Table>();
			t->name = q.cte_names[i];
