// ------------------------------------------------------- query execution
static bool type_infer_expr(const Expr *e, const SourceData &src, std::vector<Expr *> &agg_exprs, LogicalType &out);

Result Engine::execute_query(const Query &q, Scope *outer) {
	Result res;
	size_t temp_save = g_temp_tables.size();
	try {
		// CTEs
		for (size_t i = 0; i < q.cte_names.size(); i++) {
			auto t = std::make_shared<Table>();
			t->name = q.cte_names[i];
			t->schema = "temp";
			t->temporary = true;
			std::vector<std::string> names;
			std::vector<LogicalType> types;
			std::vector<std::vector<Value>> rows;
			materialize_query(this, q.cte_bodies[i].get(), outer, names, types, rows);
			size_t ncols = names.size();
			for (size_t c = 0; c < ncols; c++) {
				Column col;
				col.name = names[c];
				col.type = types[c];
				t->columns.push_back(col);
			}
			t->rows = rows;
			g_temp_tables.push_back({t->name, t});
		}
		// top-level VALUES
		if (q.is_values) {
			size_t ncols = 0;
			for (auto &r : q.values_rows) ncols = std::max(ncols, r.size());
			Scope empty;
			std::vector<std::vector<Value>> out;
			for (auto &r : q.values_rows) {
				std::vector<Value> row;
				for (size_t i = 0; i < ncols; i++) {
					if (i < r.size()) row.push_back(eval_expr(r[i].get(), empty, this));
					else row.push_back(Value::nullval(LogicalType(TId::UNKNOWN)));
				}
				out.push_back(row);
			}
			for (size_t i = 0; i < ncols; i++) {
				LogicalType ty(TId::UNKNOWN);
				for (auto &row : out) {
					if (row[i].null) continue;
					if (ty.id == TId::UNKNOWN) ty = row[i].type;
					else if (!(ty == row[i].type)) ty = numeric_op_result(OP_ADD, ty, row[i].type);
				}
				if (ty.id == TId::UNKNOWN) ty = LogicalType(TId::INTEGER);
				res.names.push_back("col" + std::to_string(i));
				res.types.push_back(ty);
			}
			res.rows = out;
			g_temp_tables.resize(temp_save);
			return res;
		}
		SourceData src;
		if (q.from) bind_table_ref(this, q.from.get(), src, outer);
		// column aliases
		if (q.from && !q.from->column_aliases.empty() && !src.cols.empty()) {
			size_t start = 0;
			for (size_t i = 0; i < src.cols.size(); i++) {
				if (i == 0 || src.cols[i].table_name != src.cols[i - 1].table_name) start = i;
			}
			for (size_t i = start; i < src.cols.size(); i++) {
				if (i - start < q.from->column_aliases.size()) src.cols[i].column_name = q.from->column_aliases[i - start];
			}
		}
		// WHERE
		Scope wscope;
		wscope.cols = src.cols;
		wscope.parent = outer;
		if (q.where) {
			std::vector<std::vector<Value>> filtered;
			for (auto &row : src.rows) {
				wscope.row = &row;
				Value c = eval_expr(q.where.get(), wscope, this);
				if (!c.null && c.as_bool()) filtered.push_back(row);
			}
			src.rows = filtered;
		}
		// collect aggregates and window functions
		int agg_counter = 0, win_counter = 0;
		std::vector<Expr *> agg_exprs;
		std::vector<Expr *> agg_filters;
		auto collect_all = [&](Expr *e) {
			int a0 = agg_counter, w0 = win_counter;
			collect_exprs(e, agg_counter, win_counter, false, false);
			while ((int)agg_exprs.size() < agg_counter) { agg_exprs.push_back(nullptr); agg_filters.push_back(nullptr); }
			(void)a0; (void)w0;
		};
		for (auto &it : q.select_list) if (!it.star && it.expr) collect_all(it.expr.get());
		if (q.having) collect_all(q.having.get());
		for (auto &g : q.group_by) collect_all(g.get());
		for (auto &o : q.order_by) collect_all(o.expr.get());
		// find the aggregate function expressions (for evaluation) and their filters
		{
			std::vector<std::pair<Expr *, Expr *>> found;
			std::function<void(Expr *)> walk = [&](Expr *e) {
				if (!e) return;
				if (e->kind == EK::Subquery || e->kind == EK::Exists) return;
				if (e->kind == EK::Func && e->op == 200 && e->args.size() >= 1) {
					Expr *inner = e->args[0].get();
					const FuncDef *def = find_function(inner->text);
					if (def && def->kind == FuncKind::Aggregate) {
						found.push_back({inner, e->extra.empty() ? nullptr : e->extra[0].get()});
						for (auto &a : inner->args) walk(a.get());
						return;
					}
				}
				if (e->kind == EK::Func && e->is_aggregate) {
					const FuncDef *def = find_function(e->text);
					if (def && def->kind == FuncKind::Aggregate) { found.push_back({e, nullptr}); return; }
				}
				for (auto &a : e->args) walk(a.get());
				for (auto &a : e->extra) walk(a.get());
			};
			for (auto &it : q.select_list) if (!it.star && it.expr) walk(it.expr.get());
			if (q.having) walk(q.having.get());
			for (auto &g : q.group_by) walk(g.get());
			for (auto &o : q.order_by) walk(o.expr.get());
			std::vector<std::pair<Expr *, Expr *>> by_id(agg_counter);
			for (auto &p : found) if (p.first->agg_id >= 0 && p.first->agg_id < (int)by_id.size() && !by_id[p.first->agg_id].first) by_id[p.first->agg_id] = p;
			for (int i = 0; i < (int)by_id.size(); i++) { agg_exprs[i] = by_id[i].first; agg_filters[i] = by_id[i].second; }
		}
		bool any_agg = !q.group_by.empty() || q.having != nullptr;
		for (auto &it : q.select_list) if (!it.star && it.expr && has_aggregate(it.expr.get())) any_agg = true;
		if (!any_agg) for (auto &e : agg_exprs) if (e) { any_agg = true; break; }
		// window functions
		std::vector<Expr *> windows(win_counter, nullptr);
		{
			std::function<void(Expr *)> walkw = [&](Expr *e) {
				if (!e) return;
				if (e->is_window) { if (e->window_id >= 0 && e->window_id < (int)windows.size()) windows[e->window_id] = e; return; }
				for (auto &a : e->args) walkw(a.get());
				for (auto &a : e->extra) walkw(a.get());
			};
			for (auto &it : q.select_list) if (!it.star && it.expr) walkw(it.expr.get());
		}
		bool any_window = false;
		for (auto &w : windows) if (w) any_window = true;

		// ------------------------------------------------ expand stars
		std::vector<const Expr *> out_exprs;
		std::vector<std::string> out_names;
		std::vector<std::unique_ptr<Expr>> owned_exprs;
		auto add_star = [&](size_t idx) {
			auto e = std::make_unique<Expr>(EK::ColumnRef);
			e->column = src.cols[idx].column_name;
			e->bound_index = (int)idx;
			e->type = src.cols[idx].type;
			e->pos = 0;
			out_names.push_back(src.cols[idx].column_name);
			out_exprs.push_back(e.get());
			owned_exprs.push_back(std::move(e));
		};
		for (auto &it : q.select_list) {
			if (it.star) {
				if (!it.star_table.empty()) {
					bool found = false;
					for (size_t i = 0; i < src.cols.size(); i++) {
						if (iequals(src.cols[i].table_name, it.star_table)) { found = true; add_star(i); }
					}
					if (!found) throw DuckDBException(DuckDBException::Type::BINDER, "Table \"" + it.star_table + "\" does not exist").with_location(it.pos, it.pos);
				} else {
					for (size_t i = 0; i < src.cols.size(); i++) add_star(i);
				}
				continue;
			}
			out_exprs.push_back(it.expr.get());
			out_names.push_back(expr_name(it.expr.get(), it.alias));
		}
		res.names = out_names;
		// output types
		for (size_t c = 0; c < out_exprs.size(); c++) {
			LogicalType ty(TId::UNKNOWN);
			if (!type_infer_expr(out_exprs[c], src, agg_exprs, ty)) {
				if (!src.rows.empty()) {
					wscope.row = &src.rows[0];
					Value v = eval_expr(out_exprs[c], wscope, this);
					ty = v.type;
				} else ty = LogicalType(TId::VARCHAR);
			}
			res.types.push_back(ty);
		}

		// aggregate computation helper
		auto compute_aggs = [&](const std::vector<const std::vector<Value> *> &rows, Scope &asc) {
			std::vector<Value> ar(agg_exprs.size());
			for (size_t i = 0; i < agg_exprs.size(); i++) {
				Expr *ae = agg_exprs[i];
				if (!ae) continue;
				const FuncDef *def = find_function(ae->text);
				if (!def) continue;
				Value st = def->agg_init();
				for (auto *rp : rows) {
					asc.row = rp;
					asc.agg_results = nullptr;
					if (agg_filters[i]) {
						Value f = eval_expr(agg_filters[i], asc, this);
						if (f.null || !f.as_bool()) continue;
					}
					if (ae->args.empty() || (ae->args.size() == 1 && ae->args[0]->kind == EK::Star)) {
						def->agg_step(st, Value::intv(1, TId::BIGINT));
						continue;
					}
					Value v = eval_expr(ae->args[0].get(), asc, this);
					def->agg_step(st, v);
				}
				Value fv = def->agg_final(st);
				LogicalType ty = def->ret({});
				fv.type = ty.id == TId::UNKNOWN ? fv.type : ty;
				ar[i] = fv;
			}
			return ar;
		};

		// --------------------------------------------------- candidates
		struct Cand {
			const std::vector<Value> *row = nullptr;
			std::vector<Value> owned_row;
		};
		std::vector<Cand> cands;
		std::vector<std::vector<Value>> agg_buffers;
		Scope sc;
		sc.cols = src.cols;
		sc.parent = outer;
		if (any_agg || !q.group_by.empty()) {
			std::vector<const Expr *> group_exprs;
			for (auto &g : q.group_by) {
				const Expr *ge = g.get();
				if (ge->kind == EK::Constant && ge->value.type.is_integral()) {
					int64_t n = ge->value.as_int();
					size_t nonstar = 0;
					for (size_t i = 0; i < q.select_list.size(); i++) {
						if (!q.select_list[i].star) nonstar++;
						if ((int64_t)nonstar == n && !q.select_list[i].star) { ge = q.select_list[i].expr.get(); break; }
					}
				} else if (ge->kind == EK::ColumnRef && ge->table.empty()) {
					size_t nonstar = 0;
					for (size_t i = 0; i < q.select_list.size(); i++) {
						if (q.select_list[i].star) continue;
						if (!q.select_list[i].alias.empty() && iequals(q.select_list[i].alias, ge->column)) { ge = q.select_list[i].expr.get(); break; }
						if (iequals(out_names[nonstar], ge->column) && q.select_list[i].expr->kind != EK::ColumnRef) { ge = q.select_list[i].expr.get(); break; }
						nonstar++;
					}
				}
				group_exprs.push_back(ge);
			}
			std::vector<std::vector<Value>> keys;
			std::vector<std::vector<const std::vector<Value> *>> groups;
			for (auto &row : src.rows) {
				sc.row = &row;
				sc.agg_results = nullptr;
				std::vector<Value> key;
				for (auto *ge : group_exprs) key.push_back(ge ? eval_expr(ge, sc, this) : Value::nullval(LogicalType(TId::UNKNOWN)));
				size_t found = (size_t)-1;
				for (size_t i = 0; i < keys.size(); i++) {
					bool eq = keys[i].size() == key.size();
					for (size_t k = 0; eq && k < key.size(); k++) {
						if (keys[i][k].null && key[k].null) continue;
						if (keys[i][k].null != key[k].null) { eq = false; break; }
						if (!keys[i][k].equals(key[k])) { eq = false; break; }
					}
					if (eq) { found = i; break; }
				}
				if (found == (size_t)-1) {
					keys.push_back(key);
					groups.push_back({});
					found = groups.size() - 1;
				}
				groups[found].push_back(&row);
			}
			if (groups.empty()) { groups.push_back({}); }
			for (size_t gi = 0; gi < groups.size(); gi++) {
				Cand c;
				if (!groups[gi].empty()) c.row = groups[gi][0];
				cands.push_back(c);
				std::vector<const std::vector<Value> *> grp;
				for (auto *r : groups[gi]) grp.push_back(r);
				sc.agg_results = nullptr;
				agg_buffers.push_back(compute_aggs(grp, sc));
			}
		} else {
			for (auto &row : src.rows) {
				Cand c;
				c.row = &row;
				cands.push_back(c);
				agg_buffers.push_back({});
			}
		}
		// HAVING
		if (q.having) {
			std::vector<Cand> keep;
			std::vector<std::vector<Value>> keepbuf;
			for (size_t i = 0; i < cands.size(); i++) {
				sc.row = cands[i].row ? cands[i].row : &cands[i].owned_row;
				sc.agg_results = &agg_buffers[i];
				Value hv = eval_expr(q.having.get(), sc, this);
				if (!hv.null && hv.as_bool()) { keep.push_back(cands[i]); keepbuf.push_back(agg_buffers[i]); }
			}
			cands = keep;
			agg_buffers = keepbuf;
		}
		// window functions: share the aggregate buffer
		for (auto &w : windows) if (w) w->window_id += agg_counter;
		std::vector<std::vector<Value>> win_vals(windows.size());
		if (any_window) {
			for (size_t w = 0; w < windows.size(); w++) {
				Expr *we = windows[w];
				if (!we) { win_vals[w].assign(cands.size(), Value::nullval(LogicalType(TId::UNKNOWN))); continue; }
				Expr *inner = we->args.empty() ? nullptr : we->args[0].get();
				const FuncDef *def = inner ? find_function(inner->text) : nullptr;
				std::vector<int> order(cands.size());
				for (size_t i = 0; i < order.size(); i++) order[i] = (int)i;
				Scope wsc;
				wsc.cols = src.cols;
				wsc.parent = outer;
				std::vector<std::vector<Value>> pkeys;
				for (auto &c : cands) {
					wsc.row = c.row ? c.row : &c.owned_row;
					std::vector<Value> k;
					for (auto &p : we->partition_by) k.push_back(eval_expr(p.get(), wsc, this));
					pkeys.push_back(k);
				}
				std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
					for (size_t k = 0; k < pkeys.size(); k++) {
						const Value &x = pkeys[a][k], &y = pkeys[b][k];
						if (x.null && y.null) continue;
						if (x.null) return false;
						if (y.null) return true;
						int c = x.compare(y);
						if (c != 0) return c < 0;
					}
					for (size_t k = 0; k < we->order_by_exprs.size(); k++) {
						wsc.row = cands[a].row ? cands[a].row : &cands[a].owned_row;
						Value x = eval_expr(we->order_by_exprs[k].get(), wsc, this);
						wsc.row = cands[b].row ? cands[b].row : &cands[b].owned_row;
						Value y = eval_expr(we->order_by_exprs[k].get(), wsc, this);
						bool desc = k < we->order_by_desc.size() ? we->order_by_desc[k] : false;
						if (x.null && y.null) continue;
						if (x.null) return desc;
						if (y.null) return !desc;
						int c = x.compare(y);
						if (c != 0) return desc ? c > 0 : c < 0;
					}
					return false;
				});
				std::vector<Value> results(cands.size(), Value::nullval(LogicalType(TId::UNKNOWN)));
				size_t i = 0;
				while (i < order.size()) {
					size_t j = i;
					while (j < order.size() && pkeys[order[j]] == pkeys[order[i]]) j++;
					size_t n = j - i;
					std::vector<std::vector<Value>> obvals;
					for (size_t k = i; k < j; k++) {
						std::vector<Value> vals;
						for (size_t kk = 0; kk < we->order_by_exprs.size(); kk++) {
							wsc.row = cands[order[k]].row ? cands[order[k]].row : &cands[order[k]].owned_row;
							vals.push_back(eval_expr(we->order_by_exprs[kk].get(), wsc, this));
						}
						obvals.push_back(vals);
					}
					auto same_rank = [&](size_t x, size_t y) {
						if (obvals[x].size() != obvals[y].size()) return false;
						for (size_t kk = 0; kk < obvals[x].size(); kk++) {
							if (obvals[x][kk].null && obvals[y][kk].null) continue;
							if (obvals[x][kk].null != obvals[y][kk].null) return false;
							if (!obvals[x][kk].equals(obvals[y][kk])) return false;
						}
						return true;
					};
					std::vector<int64_t> rank(n, 1), drank(n, 1);
					for (size_t k = 0; k < n; k++) {
						if (k == 0) { rank[0] = 1; drank[0] = 1; }
						else if (!same_rank(k, k - 1)) { rank[k] = (int64_t)k + 1; drank[k] = drank[k - 1] + 1; }
						else { rank[k] = rank[k - 1]; drank[k] = drank[k - 1]; }
					}
					for (size_t k = 0; k < n; k++) {
						size_t ri = order[i + k];
						Value v;
						std::string fname = inner ? inner->text : std::string("");
						auto rowof = [&](size_t idx) -> Scope & {
							wsc.row = cands[order[i + idx]].row ? cands[order[i + idx]].row : &cands[order[i + idx]].owned_row;
							return wsc;
						};
						if (fname == "row_number") v = Value::intv((int64_t)k + 1, TId::BIGINT);
						else if (fname == "rank") v = Value::intv(rank[k], TId::BIGINT);
						else if (fname == "dense_rank") v = Value::intv(drank[k], TId::BIGINT);
						else if (fname == "percent_rank") v = Value::dbl(n > 1 ? (double)(rank[k] - 1) / (double)(n - 1) : 0.0);
						else if (fname == "cume_dist") {
							int64_t cnt = 0;
							for (size_t m = 0; m < n; m++) if (same_rank(k, m)) cnt++;
							v = Value::dbl((double)cnt / (double)n);
						} else if (fname == "ntile") {
							int64_t nb = 1;
							if (inner && !inner->args.empty()) { auto &s = rowof(k); nb = eval_expr(inner->args[0].get(), s, this).as_int(); }
							v = Value::intv((k * nb) / n + 1, TId::BIGINT);
						} else if (fname == "first_value" || fname == "last_value") {
							v = Value::nullval(LogicalType(TId::UNKNOWN));
							if (inner && !inner->args.empty()) {
								if (fname == "first_value") {
									for (size_t m = 0; m < n; m++) { auto &s = rowof(m); Value x = eval_expr(inner->args[0].get(), s, this); if (!x.null) { v = x; break; } }
								} else {
									for (size_t m = n; m > 0; m--) { auto &s = rowof(m - 1); Value x = eval_expr(inner->args[0].get(), s, this); if (!x.null) { v = x; break; } }
								}
							}
						} else if (fname == "lag" || fname == "lead") {
							v = Value::nullval(LogicalType(TId::UNKNOWN));
							if (inner && !inner->args.empty()) {
								int64_t off = 1;
								if (inner->args.size() > 1) { auto &s = rowof(k); off = eval_expr(inner->args[1].get(), s, this).as_int(); }
								int64_t target = fname == "lag" ? (int64_t)k - off : (int64_t)k + off;
								if (target >= 0 && target < (int64_t)n) { auto &s = rowof((size_t)target); v = eval_expr(inner->args[0].get(), s, this); }
								else if (inner->args.size() > 2) { auto &s = rowof(k); v = eval_expr(inner->args[2].get(), s, this); }
							}
						} else if (def && def->kind == FuncKind::Aggregate) {
							std::vector<const std::vector<Value> *> rows;
							size_t lo = 0, hi = n;
							if (!we->frame.empty() && we->frame.find("current row") != std::string::npos) {
								if (we->frame.find("unbounded preceding") != std::string::npos) hi = k + 1;
								else { lo = k; hi = k + 1; }
							}
							for (size_t m = lo; m < hi; m++) rows.push_back(cands[order[i + m]].row ? cands[order[i + m]].row : &cands[order[i + m]].owned_row);
							Scope asc;
							asc.cols = src.cols;
							asc.parent = outer;
							auto ar = compute_aggs(rows, asc);
							v = ar.empty() ? Value::nullval(LogicalType(TId::UNKNOWN)) : ar[0];
							v.type = def->ret({});
						}
						results[ri] = v;
					}
					i = j;
				}
				win_vals[w] = results;
			}
		}
		// ------------------------------------------- evaluate the select list
		std::vector<std::vector<Value>> rows_out;
		rows_out.reserve(cands.size());
		for (size_t i = 0; i < cands.size(); i++) {
			std::vector<Value> combined = agg_buffers[i];
			combined.resize(agg_counter + windows.size());
			for (size_t w = 0; w < windows.size(); w++) combined[agg_counter + w] = win_vals[w][i];
			sc.row = cands[i].row ? cands[i].row : &cands[i].owned_row;
			sc.agg_results = &combined;
			std::vector<Value> out;
			for (size_t c = 0; c < out_exprs.size(); c++) {
				Value v = eval_expr(out_exprs[c], sc, this);
				if (c < res.types.size() && res.types[c].id != TId::UNKNOWN && !v.null) v.type = res.types[c];
				out.push_back(v);
			}
			rows_out.push_back(out);
		}
		// DISTINCT
		if (q.distinct) {
			std::vector<std::vector<Value>> uniq;
			for (auto &row : rows_out) {
				bool dup = false;
				for (auto &u : uniq) {
					bool eq = u.size() == row.size();
					for (size_t k = 0; eq && k < row.size(); k++) {
						if (u[k].null && row[k].null) continue;
						if (u[k].null != row[k].null) { eq = false; break; }
						if (!u[k].equals(row[k])) { eq = false; break; }
					}
					if (eq) { dup = true; break; }
				}
				if (!dup) uniq.push_back(row);
			}
			rows_out = uniq;
		}
		// ORDER BY
		if (!q.order_by.empty()) {
			// build an ordering scope: source columns + select aliases
			Scope osc;
			osc.cols = src.cols;
			osc.parent = outer;
			struct OrdKey {
				std::vector<Value> vals;
				size_t idx;
			};
			std::vector<OrdKey> keys;
			for (size_t i = 0; i < rows_out.size(); i++) {
				const std::vector<Value> &row = rows_out[i];
				sc.row = cands[i].row ? cands[i].row : &cands[i].owned_row;
				sc.agg_results = nullptr;
				std::vector<Value> kv;
				for (auto &o : q.order_by) {
					const Expr *oe = o.expr.get();
					Value v;
					if (oe->kind == EK::Constant && oe->value.type.is_integral()) {
						int64_t n = oe->value.as_int();
						if (n >= 1 && n <= (int64_t)row.size()) v = row[n - 1];
						else v = Value::nullval(LogicalType(TId::UNKNOWN));
					} else if (oe->kind == EK::ColumnRef && oe->table.empty()) {
						bool matched = false;
						size_t nonstar = 0;
						for (size_t c = 0; c < q.select_list.size() && c < row.size(); c++) {
							if (q.select_list[c].star) continue;
							if (!q.select_list[c].alias.empty() && iequals(q.select_list[c].alias, oe->column)) { v = row[nonstar]; matched = true; break; }
							if (iequals(out_names[nonstar], oe->column)) { v = row[nonstar]; matched = true; break; }
							nonstar++;
						}
						if (!matched) v = eval_expr(oe, sc, this);
					} else {
						v = eval_expr(oe, sc, this);
					}
					kv.push_back(v);
				}
				keys.push_back({kv, i});
			}
			std::stable_sort(keys.begin(), keys.end(), [&](const OrdKey &a, const OrdKey &b) {
				for (size_t k = 0; k < q.order_by.size(); k++) {
					const Value &x = a.vals[k], &y = b.vals[k];
					const OrderItem &o = q.order_by[k];
					bool desc = o.desc;
					bool nulls_first = o.has_nulls_spec ? o.nulls_first : (!desc); // ASC: nulls last, DESC: nulls first
					if (x.null && y.null) continue;
					if (x.null) return nulls_first;
					if (y.null) return !nulls_first;
					int c = x.compare(y);
					if (c == 2) {
						std::string sx = x.to_string(), sy = y.to_string();
						c = sx < sy ? -1 : (sx > sy ? 1 : 0);
					}
					if (c != 0) return desc ? c > 0 : c < 0;
				}
				return false;
			});
			std::vector<std::vector<Value>> sorted;
			for (auto &k : keys) sorted.push_back(rows_out[k.idx]);
			rows_out = sorted;
		}
		// LIMIT / OFFSET
		int64_t offset = 0, limit = -1;
		if (q.offset) {
			Scope ls;
			ls.parent = outer;
			Value v = eval_expr(q.offset.get(), ls, this);
			offset = v.as_int();
		}
		if (q.limit) {
			Scope ls;
			ls.parent = outer;
			Value v = eval_expr(q.limit.get(), ls, this);
			limit = v.as_int();
		}
		if (offset > 0 || limit >= 0) {
			std::vector<std::vector<Value>> out;
			for (size_t i = (size_t)std::max<int64_t>(0, offset); i < rows_out.size(); i++) {
				if (limit >= 0 && (int64_t)out.size() >= limit) break;
				out.push_back(rows_out[i]);
			}
			rows_out = out;
		}
		// set operations
		if (!q.set_ops.empty()) {
			Result right;
			// union all parts progressively
			std::vector<std::vector<Value>> acc = rows_out;
			for (auto &so : q.set_ops) {
				Result r2 = execute_query(*so.query, outer);
				if (so.type == 1) { // union all
					for (auto &row : r2.rows) acc.push_back(row);
				} else if (so.type == 0) { // union
					for (auto &row : r2.rows) {
						bool dup = false;
						for (auto &u : acc) {
							bool eq = u.size() == row.size();
							for (size_t k = 0; eq && k < row.size(); k++) {
								if (u[k].null && row[k].null) continue;
								if (u[k].null != row[k].null) { eq = false; break; }
								if (!u[k].equals(row[k])) { eq = false; break; }
							}
							if (eq) { dup = true; break; }
						}
						if (!dup) acc.push_back(row);
					}
				} else if (so.type == 2 || so.type == 5) { // intersect
					std::vector<std::vector<Value>> out;
					for (auto &row : acc) {
						for (auto &r : r2.rows) {
							bool eq = r.size() == row.size();
							for (size_t k = 0; eq && k < row.size(); k++) {
								if (r[k].null && row[k].null) continue;
								if (r[k].null != row[k].null) { eq = false; break; }
								if (!r[k].equals(row[k])) { eq = false; break; }
							}
							if (eq) { out.push_back(row); break; }
						}
					}
					acc = out;
				} else { // except
					std::vector<std::vector<Value>> out;
					for (auto &row : acc) {
						bool found = false;
						for (auto &r : r2.rows) {
							bool eq = r.size() == row.size();
							for (size_t k = 0; eq && k < row.size(); k++) {
								if (r[k].null && row[k].null) continue;
								if (r[k].null != row[k].null) { eq = false; break; }
								if (!r[k].equals(row[k])) { eq = false; break; }
							}
							if (eq) { found = true; break; }
						}
						if (!found) out.push_back(row);
					}
					acc = out;
				}
			}
			rows_out = acc;
			if (!q.order_by.empty()) { /* already applied */ }
		}
		res.rows = rows_out;
		g_temp_tables.resize(temp_save);
		return res;
	} catch (...) {
		g_temp_tables.resize(temp_save);
		throw;
	}
}

