{"command": "cat >> src/engine.cpp <<'CPPEOF'
static bool type_infer_expr(const Expr *e, const SourceData &src, std::vector<Expr *> &agg_exprs, LogicalType &out) {
	if (!e) return false;
	switch (e->kind) {
	case EK::ColumnRef:
		if (e->bound_index >= 0 && (size_t)e->bound_index < src.cols.size()) { out = src.cols[e->bound_index].type; return true; }
		return false;
	case EK::Constant: out = e->value.type; return true;
	case EK::Cast: out = e->type; return true;
	case EK::TableStar: out = LogicalType(TId::UNKNOWN); return false;
	case EK::Star: out = LogicalType(TId::BIGINT); return true;
	case EK::Binary: {
		if (e->args.size() != 2) return false;
		if (e->flags.size() > 0 && e->flags[0]) { out = LogicalType(TId::BOOLEAN); return true; }
		if (e->op == 100 || e->op == 101) { out = LogicalType(TId::BOOLEAN); return true; }
		LogicalType a(TId::UNKNOWN), b(TId::UNKNOWN);
		bool oa = type_infer_expr(e->args[0].get(), src, agg_exprs, a);
		bool ob = type_infer_expr(e->args[1].get(), src, agg_exprs, b);
		if (!oa || !ob) return false;
		out = numeric_op_result(e->op, a, b);
		return out.id != TId::UNKNOWN;
	}
	case EK::Unary: {
		if (e->args.size() != 1) return false;
		if (e->op == 2) { out = LogicalType(TId::BOOLEAN); return true; }
		LogicalType a(TId::UNKNOWN);
		if (!type_infer_expr(e->args[0].get(), src, agg_exprs, a)) return false;
		out = a;
		return true;
	}
	case EK::Func: {
		const FuncDef *def = find_function(e->text);
		if (!def) return false;
		std::vector<LogicalType> ats;
		if (e->is_aggregate) {
			Expr *ae = (e->agg_id >= 0 && e->agg_id < (int)agg_exprs.size()) ? agg_exprs[e->agg_id] : nullptr;
			if (!ae) return false;
			for (auto &a : ae->args) {
				LogicalType at(TId::UNKNOWN);
				type_infer_expr(a.get(), src, agg_exprs, at);
				ats.push_back(at);
			}
			out = def->ret(ats);
			return out.id != TId::UNKNOWN;
		}
		for (auto &a : e->args) {
			LogicalType at(TId::UNKNOWN);
			type_infer_expr(a.get(), src, agg_exprs, at);
			ats.push_back(at);
		}
		out = def->ret(ats);
		return out.id != TId::UNKNOWN;
	}
	case EK::Case: {
		LogicalType t(TId::UNKNOWN);
		for (size_t i = 1; i < e->args.size(); i += 2) {
			LogicalType a(TId::UNKNOWN);
			if (type_infer_expr(e->args[i].get(), src, agg_exprs, a)) {
				if (t.id == TId::UNKNOWN) t = a;
				else if (!(t == a)) t = numeric_op_result(OP_ADD, t, a);
			}
		}
		if (e->args.size() % 2 == 1) {
			LogicalType a(TId::UNKNOWN);
			if (type_infer_expr(e->args.back().get(), src, agg_exprs, a)) {
				if (t.id == TId::UNKNOWN) t = a;
				else if (!(t == a)) t = numeric_op_result(OP_ADD, t, a);
			}
		}
		if (t.id == TId::UNKNOWN) return false;
		out = t;
		return true;
	}
	case EK::In: case EK::Between: case EK::Like: case EK::IsNull: out = LogicalType(TId::BOOLEAN); return true;
	case EK::ListCtor: {
		if (e->op == 10) { out = LogicalType(TId::STRUCT); return true; }
		LogicalType inner(TId::UNKNOWN);
		std::vector<LogicalType> ats;
		for (auto &a : e->args) {
			LogicalType at(TId::UNKNOWN);
			if (type_infer_expr(a.get(), src, agg_exprs, at)) {
				ats.push_back(at);
				if (inner.id == TId::UNKNOWN) inner = at;
				else inner = numeric_op_result(OP_ADD, inner, at);
			} else ats.push_back(LogicalType(TId::UNKNOWN));
		}
		const FuncDef *def = find_function("list_value");
		if (def) out = def->ret(ats);
		else out = LogicalType::list_type(inner);
		return out.id != TId::UNKNOWN;
	}
	case EK::StructCtor: {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		for (auto &a : e->args) {
			LogicalType at(TId::UNKNOWN);
			type_infer_expr(a.get(), src, agg_exprs, at);
			names.push_back(a->text.empty() ? "v" + std::to_string(names.size() + 1) : a->text);
			types.push_back(at);
		}
		out = LogicalType::struct_type(names, types);
		return true;
	}
	case EK::MapCtor: {
		LogicalType k(TId::UNKNOWN), v(TId::UNKNOWN);
		for (size_t i = 0; i < e->args.size(); i++) {
			LogicalType at(TId::UNKNOWN);
			if (type_infer_expr(e->args[i].get(), src, agg_exprs, at) && k.id == TId::UNKNOWN) k = at;
			LogicalType bt(TId::UNKNOWN);
			if (i < e->extra.size() && type_infer_expr(e->extra[i].get(), src, agg_exprs, bt) && v.id == TId::UNKNOWN) v = bt;
		}
		out = LogicalType::map_type(k.id == TId::UNKNOWN ? LogicalType(TId::VARCHAR) : k, v.id == TId::UNKNOWN ? LogicalType(TId::VARCHAR) : v);
		return true;
	}
	case EK::Exists: out = LogicalType(TId::BOOLEAN); return true;
	case EK::Collate: return type_infer_expr(e->args.empty() ? nullptr : e->args[0].get(), src, agg_exprs, out);
	case EK::Window: return type_infer_expr(e->args.empty() ? nullptr : e->args[0].get(), src, agg_exprs, out);
	default: return false;
	}
}

