				Value c = eval_expr(st.where.get(), sc, this);
				if (c.null || !c.as_bool()) { keep.push_back(row); continue; }
			}
			n++;
		}
		t->rows = keep;
		if (changed) *changed = n;
		res.is_statement = true;
		res.changed_rows = n;
		return res;
	}
	case SK::CreateTable: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		if (db.find_schema(schema) == nullptr) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name " + schema + " does not exist!");
		}
		auto existing = db.find_table(schema, name);
		if (existing) {
			if (st.if_not_exists || st.or_replace) {
				if (st.if_not_exists) return res;
			} else {
				throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" already exists!");
			}
		}
		auto t = std::make_shared<Table>();
		t->name = name;
		t->schema = schema;
		t->temporary = st.temporary;
		if (st.as_select && st.create_query) {
			Result r = execute_query(*st.create_query, nullptr);
			for (size_t i = 0; i < r.names.size(); i++) {
				Column col;
				col.name = r.names[i];
				col.type = r.types[i];
				t->columns.push_back(col);
			}
			t->rows = r.rows;
		} else {
			for (auto &cd : st.create_columns) {
				Column col;
				col.name = cd.name;
				col.type = cd.type;
				col.not_null = cd.not_null;
				col.primary_key = cd.primary_key;
				col.unique = cd.unique;
				if (cd.default_value) {
					Scope empty;
					col.default_value = eval_expr(cd.default_value.get(), empty, this);
					col.default_value = do_cast(col.default_value, cd.type);
				}
				t->columns.push_back(col);
			}
		}
		add_table(t);
		res.is_statement = true;
		return res;
	}
	case SK::CreateView: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		auto t = std::make_shared<Table>();
		t->name = name;
		t->schema = schema;
		t->is_view = true;
		t->temporary = st.temporary;
		if (st.create_query) {
			std::string qtext;
			// store the view definition text
			t->view_sql = "CREATE VIEW " + (schema == "main" ? name : schema + "." + name) + " AS " + view_sql_text;
		}
		if (st.create_query) {
			Result r = execute_query(*st.create_query, nullptr);
			for (size_t i = 0; i < r.names.size(); i++) {
				Column col;
				col.name = r.names[i];
				col.type = r.types[i];
				t->columns.push_back(col);
			}
		}
		if (db.find_table(schema, name) && !st.or_replace && !st.if_not_exists) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "View with name \"" + name + "\" already exists!");
		}
		add_table(t);
		res.is_statement = true;
		return res;
	}
	case SK::CreateSchema: {
		std::string name = st.table;
		if (db.find_schema(name)) {
			if (!st.if_not_exists) throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name \"" + name + "\" already exists!");
		} else {
			db.schemas.push_back({name, {}});
		}
		res.is_statement = true;
		return res;
	}
	case SK::Drop: {
		if (st.table == "TABLE" || st.table == "VIEW") {
			std::string schema = "main", name;
			if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
			else name = st.name_parts.empty() ? "" : st.name_parts[0];
			auto t = db.find_table(schema, name);
			if (!t) {
				if (!st.if_exists) {
					std::string kind = st.table == "VIEW" ? "View" : "Table";
					throw DuckDBException(DuckDBException::Type::CATALOG, kind + " with name \"" + name + "\" does not exist!");
				}
			} else drop_table(schema, name);
		} else if (st.table == "SCHEMA") {
			std::string name = st.name_parts.empty() ? "" : st.name_parts[0];
			for (size_t i = 0; i < db.schemas.size(); i++) {
				if (iequals(db.schemas[i].name, name)) {
					if (db.schemas[i].name == "main") throw DuckDBException(DuckDBException::Type::CATALOG, "Cannot drop schema \"main\"");
					db.schemas.erase(db.schemas.begin() + i);
					return res;
				}
			}
			if (!st.if_exists) throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name \"" + name + "\" does not exist!");
		}
		res.is_statement = true;
		return res;
	}
	case SK::Alter: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		auto t = db.find_table(schema, name);
		if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" does not exist!");
		if (st.action == 0) { t->name = st.new_name; }
		else if (st.action == 1) {
			int idx = t->column_index(st.target_column);
			if (idx < 0) throw DuckDBException(DuckDBException::Type::CATALOG, "Column with name \"" + st.target_column + "\" does not exist!");
			t->columns[idx].name = st.new_name;
		} else if (st.action == 2) {
			Column col;
			col.name = st.create_columns[0].name;
			col.type = st.create_columns[0].type;
			col.not_null = st.create_columns[0].not_null;
			if (st.create_columns[0].default_value) {
				Scope empty;
				col.default_value = eval_expr(st.create_columns[0].default_value.get(), empty, this);
			} else col.default_value = Value::nullval(col.type);
			t->columns.push_back(col);
			for (auto &row : t->rows) row.push_back(col.default_value.null ? Value::nullval(col.type) : col.default_value);
		} else if (st.action == 3) {
			int idx = t->column_index(st.target_column);
			if (idx < 0) {
				if (!st.if_exists) throw DuckDBException(DuckDBException::Type::CATALOG, "Column with name \"" + st.target_column + "\" does not exist!");
			} else {
				t->columns.erase(t->columns.begin() + idx);
				for (auto &row : t->rows) if (idx < (int)row.size()) row.erase(row.begin() + idx);
			}
		} else if (st.action == 4) {
			int idx = t->column_index(st.target_column);
			if (idx >= 0) {
				t->columns[idx].type = st.create_columns[0].type;
				for (auto &row : t->rows) row[idx] = do_cast(row[idx], st.create_columns[0].type);
			}
		}
		res.is_statement = true;
		return res;
	}
	case SK::Truncate: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		auto t = db.find_table(schema, name);
		if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" does not exist!");
		t->rows.clear();
		res.is_statement = true;
		return res;
	}
	case SK::Transaction: {
		res.is_statement = true;
		return res;
	}
	case SK::Set: {
		std::string name;
		for (auto &s : st.setting_name) { if (!name.empty()) name += "."; name += to_lower(s); }
		std::string value;
		if (st.setting_value) value = st.setting_value->text;
		if (st.pragma_expr) value = st.pragma_expr->text;
		set_setting_string(name, value);
		res.is_statement = true;
		return res;
	}
	case SK::Pragma: {
		std::string name = to_lower(st.pragma_name);
		if (name == "table_info") {
			std::string tname = st.pragma_args.empty() ? std::string("") : st.pragma_args[0];
			auto t = db.find_table(tname);
			res.names = {"cid", "name", "type", "notnull", "dflt_value", "pk"};
			res.types = {LogicalType(TId::INTEGER), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::BOOLEAN), LogicalType(TId::VARCHAR), LogicalType(TId::BOOLEAN)};
			if (t) {
				for (size_t i = 0; i < t->columns.size(); i++) {
					std::vector<Value> row;
					row.push_back(Value::intv((int64_t)i, TId::INTEGER));
					row.push_back(Value::str(t->columns[i].name));
					row.push_back(Value::str(t->columns[i].type.sql_name()));
					row.push_back(Value::boolean(t->columns[i].not_null));
					row.push_back(t->columns[i].default_value.null ? Value::nullval(LogicalType(TId::VARCHAR)) : Value::str(t->columns[i].default_value.to_string()));
					row.push_back(Value::boolean(t->columns[i].primary_key));
					res.rows.push_back(row);
				}
			}
			return res;
		}
		if (name == "show_tables" || name == "database_size" || name == "collations" || name == "storage_info" || name == "metadata_info") {
			res.is_statement = true;
			return res;
		}
		res.is_statement = true;
		return res;
	}
	case SK::Explain: {
		res.names = {"explain_key", "explain_value"};
		res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
		res.rows.push_back({Value::str("plan"), Value::str("")});
		return res;
	}
	case SK::Show: {
		if (iequals(st.table, "TABLES") || st.table.empty()) {
			res.names = {"schema_name", "table_name"};
			res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
			for (auto &t : all_tables()) {
				if (t->is_view) continue;
				res.rows.push_back({Value::str(t->schema), Value::str(t->name)});
			}
			return res;
		}
		if (!st.name_parts.empty()) {
			auto t = db.find_table(st.name_parts.back());
			if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + st.name_parts.back() + "\" does not exist!");
			res.names = {"column_name", "column_type", "null", "key", "default", "extra"};
			res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
			for (auto &c : t->columns) {
				res.rows.push_back({Value::str(c.name), Value::str(c.type.sql_name()), Value::str(c.not_null ? "NO" : "YES"), Value::str(c.primary_key ? "PRI" : ""), Value::str(""), Value::str("")});
			}
			return res;
		}
		res.is_statement = true;
		return res;
	}
	case SK::Describe: {
		std::string name = st.name_parts.empty() ? std::string("") : st.name_parts.back();
		auto t = db.find_table(name);
		if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" does not exist!");
		res.names = {"column_name", "column_type", "null", "key", "default", "extra"};
		res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
		for (auto &c : t->columns) {
			res.rows.push_back({Value::str(c.name), Value::str(c.type.sql_name()), Value::str(c.not_null ? "NO" : "YES"), Value::str(c.primary_key ? "PRI" : ""), Value::str(""), Value::str("")});
		}
		return res;
	}
	case SK::Call: {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		std::vector<std::vector<Value>> rows;
		std::vector<Value> args;
		Scope empty;
		for (auto &a : st.call_args) args.push_back(eval_expr(a.get(), empty, this));
		if (!eval_table_function(st.call_name, args, names, types, rows)) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table Function with name " + st.call_name + " does not exist!");
		}
		res.names = names;
		res.types = types;
		res.rows = rows;
		return res;
	}
	case SK::Copy: {
		res.is_statement = true;
		return res;
	}
	case SK::Attach: case SK::Detach: {
		res.is_statement = true;
		return res;
	}
	case SK::Vacuum: {
		res.is_statement = true;
		return res;
	}
	default: return res;
	}
}

