// --------------------------------------------------------------- duckbox
struct BoxCol {
	int width = 0;
	bool right_align = false;
};

static bool is_right_aligned(const LogicalType &t) {
	switch (t.id) {
	case TId::BOOLEAN: return false;
	case TId::TINYINT: case TId::SMALLINT: case TId::INTEGER: case TId::BIGINT: case TId::HUGEINT:
	case TId::UTINYINT: case TId::USMALLINT: case TId::UINTEGER: case TId::UBIGINT:
	case TId::FLOAT: case TId::DOUBLE: case TId::DECIMAL: return true;
	default: return false;
	}
}

static std::string center(const std::string &s, int width) {
	int w = utf8_display_width(s);
	int left = (width - w) / 2;
	int right = width - w - left;
	std::string o;
	for (int i = 0; i < left; i++) o += ' ';
	o += s;
	for (int i = 0; i < right; i++) o += ' ';
	return o;
}

static std::string align(const std::string &s, int width, bool right) {
	int w = utf8_display_width(s);
	if (w > width) return s;
	std::string o;
	if (right) {
		for (int i = 0; i < width - w; i++) o += ' ';
		o += s;
	} else {
		o += s;
		for (int i = 0; i < width - w; i++) o += ' ';
	}
	return o;
}

std::string render_duckbox(const Result &res, const RenderSettings &st) {
	std::string out;
	if (res.types.empty()) return out;
	size_t ncols = res.types.size();
	std::vector<BoxCol> cols(ncols);
	for (size_t i = 0; i < ncols; i++) {
		std::string name = i < res.names.size() ? res.names[i] : "";
		std::string tname = res.types[i].short_name();
		cols[i].width = std::max((int)utf8_display_width(name), (int)utf8_display_width(tname));
		cols[i].right_align = is_right_aligned(res.types[i]);
	}
	for (auto &row : res.rows) {
		for (size_t i = 0; i < ncols && i < row.size(); i++) {
			std::string s = render_value_string(row[i], st);
			if (!row[i].null && row[i].type.id == TId::VARCHAR) s = escape_string(s);
			cols[i].width = std::max(cols[i].width, (int)utf8_display_width(s));
		}
	}
	if (st.maxwidth > 0) {
		for (size_t i = 0; i < ncols; i++) {
			if (cols[i].width > st.maxwidth) cols[i].width = st.maxwidth;
		}
	}
	if (!st.widths.empty()) {
		for (size_t i = 0; i < ncols && i < st.widths.size(); i++) {
			int w = std::abs(st.widths[i]);
			if (w > cols[i].width) cols[i].width = w;
		}
	}
	// horizontal border
	auto hborder = [&](char left, char mid, char right) {
		std::string o;
		o += left;
		for (size_t i = 0; i < ncols; i++) {
			if (i) o += mid;
			for (int j = 0; j < cols[i].width + 2; j++) o += "\u2500";
		}
		o += right;
		return o;
	};
	out += hborder(0x250c, 0x252c, 0x2510) + "\n";
	// header
	if (st.headers) {
		out += "\u2502";
		for (size_t i = 0; i < ncols; i++) {
			std::string name = i < res.names.size() ? res.names[i] : "";
			out += " " + center(name, cols[i].width) + " ";
			out += "\u2502";
		}
		out += "\n";
	}
	// types
	out += "\u2502";
	for (size_t i = 0; i < ncols; i++) {
		out += " " + center(res.types[i].short_name(), cols[i].width) + " ";
		out += "\u2502";
	}
	out += "\n";
	out += hborder(0x251c, 0x253c, 0x2524) + "\n";
	// rows
	bool truncated = false;
	size_t row_count = res.rows.size();
	size_t half = (size_t)std::max(0, st.maxrows / 2);
	size_t first_n = row_count, skip_start = 0, skip_end = 0;
	if (st.maxrows > 0 && row_count > (size_t)st.maxrows + 3) {
		truncated = true;
		first_n = half;
		skip_start = half;
		skip_end = row_count - half;
	}
	auto render_row = [&](const std::vector<Value> &row) {
		out += "\u2502";
		for (size_t i = 0; i < ncols; i++) {
			std::string s = i < row.size() ? render_value_string(row[i], st) : std::string(st.nullvalue);
			if (!row[i].null && row[i].type.id == TId::VARCHAR) s = escape_string(s);
			out += " " + align(s, cols[i].width, cols[i].right_align) + " ";
			out += "\u2502";
		}
		out += "\n";
	};
	for (size_t r = 0; r < first_n && r < row_count; r++) render_row(res.rows[r]);
	if (truncated) {
		for (int k = 0; k < 3; k++) {
			out += "\u2502";
			for (size_t i = 0; i < ncols; i++) {
				std::string s = "\u00b7";
				out += " " + align(s, cols[i].width, false) + " ";
				out += "\u2502";
			}
			out += "\n";
		}
		for (size_t r = skip_end; r < row_count; r++) render_row(res.rows[r]);
	}
	out += hborder(0x2514, 0x2534, 0x2518) + "\n";
	if (row_count == 0) {
		out += "  0 rows\n";
	} else if (truncated) {
		out += "  " + std::to_string(row_count) + " rows \n";
		out += "  (" + std::to_string(first_n + (row_count - skip_end)) + " shown) \n";
	}
	return out;
}

