static std::string quoted_sql(const Value &v, const RenderSettings &st) {
	if (v.null) return st.nullvalue;
	if (v.type.id == TId::VARCHAR || v.type.id == TId::BLOB) {
		std::string o = "'";
		for (char c : v.to_string()) { if (c == '\'') o += "''"; else o += c; }
		return o + "'";
	}
	return v.to_string();
}

std::string render_csv(const Result &res, const RenderSettings &st) {
	std::string out;
	auto vals = value_strings(res, st);
	if (st.headers) {
		for (size_t i = 0; i < res.names.size(); i++) {
			if (i) out += ",";
			out += csv_escape(res.names[i]);
		}
		out += "\r\n";
	}
	for (auto &r : vals) {
		for (size_t i = 0; i < r.size(); i++) {
			if (i) out += ",";
			out += csv_escape(r[i]);
		}
		out += "\r\n";
	}
	return out;
}

std::string json_value(const Value &v, const RenderSettings &st) {
	if (v.null) return "null";
	switch (v.type.id) {
	case TId::BOOLEAN: return v.b ? "true" : "false";
	case TId::TINYINT: case TId::SMALLINT: case TId::INTEGER: case TId::BIGINT: case TId::HUGEINT:
	case TId::UTINYINT: case TId::USMALLINT: case TId::UINTEGER: case TId::UBIGINT:
		return v.to_string();
	case TId::FLOAT: case TId::DOUBLE: case TId::DECIMAL: return v.to_string();
	case TId::VARCHAR: case TId::BLOB: return "\"" + json_escape(v.to_string()) + "\"";
	case TId::LIST: case TId::ARRAY: {
		std::string o = "[";
		for (size_t i = 0; i < v.children.size(); i++) {
			if (i) o += ",";
			o += json_value(v.children[i], st);
		}
		return o + "]";
	}
	case TId::STRUCT: {
		std::string o = "{";
		for (size_t i = 0; i < v.type.child_names.size(); i++) {
			if (i) o += ",";
			o += "\"" + json_escape(v.type.child_names[i]) + "\":" + (i < v.children.size() ? json_value(v.children[i], st) : "null");
		}
		return o + "}";
	}
	case TId::MAP: {
		std::string o = "{";
		for (size_t i = 0; i < v.kv.size(); i++) {
			if (i) o += ",";
			o += "\"" + json_escape(v.kv[i].first) + "\":" + json_value(v.kv[i].second, st);
		}
		return o + "}";
	}
	default: return "\"" + json_escape(v.to_string()) + "\"";
	}
}

std::string render_json(const Result &res, const RenderSettings &st) {
	std::string out = "[";
	for (size_t r = 0; r < res.rows.size(); r++) {
		if (r) out += ",\n";
		out += "{";
		for (size_t i = 0; i < res.names.size(); i++) {
			if (i) out += ",";
			out += "\"" + json_escape(res.names[i]) + "\":" + (i < res.rows[r].size() ? json_value(res.rows[r][i], st) : "null");
		}
		out += "}";
	}
	out += "]\n";
	return out;
}

