std::string render_latex(const Result &res, const RenderSettings &st) {
	std::string out;
	auto vals = value_strings(res, st);
	size_t ncols = res.names.size();
	std::vector<int> widths(ncols, 0);
	for (size_t i = 0; i < ncols; i++) widths[i] = (int)utf8_display_width(res.names[i]);
	for (auto &r : vals) for (size_t i = 0; i < r.size() && i < ncols; i++) widths[i] = std::max(widths[i], (int)utf8_display_width(r[i]));
	out += "\\begin{tabular}{|";
	for (size_t i = 0; i < ncols; i++) out += is_right_aligned(res.types[i]) ? "r" : "l";
	out += "|}\n";
	out += "\\hline\n";
	// header
	{
		std::string o = " ";
		for (size_t i = 0; i < ncols; i++) {
			std::string s = res.names[i];
			if (i) o += " & ";
			if (is_right_aligned(res.types[i])) o += std::string(widths[i] - utf8_display_width(s), ' ') + s;
			else o += s + std::string(widths[i] - utf8_display_width(s), ' ');
		}
		o += " \\\\";
		out += o + "\n";
	}
	out += "\\hline\n";
	for (auto &r : vals) {
		std::string o = "";
		for (size_t i = 0; i < ncols; i++) {
			std::string s = i < r.size() ? r[i] : "";
			if (i) o += " & ";
			if (is_right_aligned(res.types[i])) o += std::string(widths[i] - utf8_display_width(s), ' ') + s;
			else o += s + std::string(widths[i] - utf8_display_width(s), ' ');
		}
		o += " \\\\";
		out += o + "\n";
	}
	out += "\\hline\n";
	out += "\\end{tabular}\n";
	return out;
}

std::string render_result(const Result &res, const RenderSettings &st) {
	switch (st.mode) {
	case RenderMode::DuckBox: return render_duckbox(res, st);
	case RenderMode::CSV: return render_csv(res, st);
	case RenderMode::JSON: return render_json(res, st);
	case RenderMode::JSONLines: return render_jsonlines(res, st);
	case RenderMode::Line: return render_line(res, st);
	case RenderMode::List: return render_list(res, st);
	case RenderMode::Column: return render_column(res, st);
	case RenderMode::Table: return render_table(res, st);
	case RenderMode::Markdown: return render_markdown(res, st);
	case RenderMode::Quote: return render_quote(res, st);
	case RenderMode::ASCII: return render_ascii(res, st);
	case RenderMode::HTML: return render_html(res, st);
	case RenderMode::Insert: return render_insert(res, st);
	case RenderMode::Latex: return render_latex(res, st);
	case RenderMode::Tabs: return render_tabs(res, st);
	case RenderMode::TCL: return render_tcl(res, st);
	case RenderMode::Trash: return "";
	case RenderMode::Binary: return "";
	}
	return "";
}

