std::string render_column(const Result &res, const RenderSettings &st) {
	std::string out;
	auto vals = value_strings(res, st);
	size_t ncols = res.names.size();
	std::vector<int> widths(ncols, 0);
	for (size_t i = 0; i < ncols; i++) widths[i] = (int)utf8_display_width(res.names[i]);
	for (auto &r : vals) for (size_t i = 0; i < r.size() && i < ncols; i++) widths[i] = std::max(widths[i], (int)utf8_display_width(r[i]));
	if (!st.widths.empty()) {
		for (size_t i = 0; i < ncols && i < st.widths.size(); i++) {
			int w = std::abs(st.widths[i]);
			if (w > widths[i]) widths[i] = w;
		}
	}
	auto row_line = [&](const std::vector<std::string> &r, const std::vector<LogicalType> *types) {
		std::string o;
		for (size_t i = 0; i < ncols; i++) {
			std::string s = i < r.size() ? r[i] : "";
			bool right = types && i < types->size() && is_right_aligned((*types)[i]);
			if (right && (int)utf8_display_width(s) < widths[i]) {
				o += std::string(widths[i] - utf8_display_width(s), ' ') + s;
			} else {
				o += s + std::string(widths[i] - utf8_display_width(s), ' ');
			}
			o += "  ";
		}
		// trim trailing spaces
		while (!o.empty() && o.back() == ' ') o.pop_back();
		return o + "\n";
	};
	if (st.headers) {
		std::vector<std::string> hdr;
		for (size_t i = 0; i < ncols; i++) hdr.push_back(res.names[i]);
		out += row_line(hdr, nullptr);
		std::string sep;
		for (size_t i = 0; i < ncols; i++) {
			if (i) sep += "  ";
			bool right = i < res.types.size() && is_right_aligned(res.types[i]);
			if (right) sep += std::string(widths[i], '-');
			else sep += std::string(std::min(widths[i], (int)utf8_display_width(res.names[i])), '-');
		}
		out += sep + "\n";
	}
	for (auto &r : vals) out += row_line(r, &res.types);
	return out;
}

