// render a list of tables the way DuckDB's .tables does
static std::string render_tables_box(const std::vector<std::shared_ptr<Table>> &tables, const std::string &dbname, const std::string &schemaname) {
	std::string out;
	if (tables.empty()) return out;
	// database / schema header lines
	{
		size_t total = 0;
		for (auto &t : tables) {
			size_t w = 0;
			for (auto &c : t->columns) w = std::max(w, std::max(utf8_display_width(c.name), utf8_display_width(c.type.short_name())));
			total += w + 4;
		}
		std::string dn = " " + dbname + " ";
		std::string sn = " " + schemaname + " ";
		std::string dbline = "\x1b[38;5;172m";
		size_t dash = total > dn.size() ? (total - dn.size()) / 2 : 0;
		for (size_t i = 0; i < dash; i++) dbline += "\u2500";
		dbline += dn;
		while (dbline.size() < total + 1) dbline += "\u2500";
		dbline += " \x1b[0m";
		out += dbline + "\n";
		std::string sline = "\x1b[00m\x1b[38;5;39m";
		dash = total > sn.size() ? (total - sn.size()) / 2 : 0;
		for (size_t i = 0; i < dash; i++) sline += "\u2500";
		sline += sn;
		while (sline.size() < total + 1) sline += "\u2500";
		sline += " \x1b[0m";
		out += sline + "\n";
	}
	// each table as a box
	std::vector<std::vector<std::string>> boxes;
	size_t maxlines = 0;
	for (auto &t : tables) {
		std::vector<std::string> lines;
		size_t ncols = t->columns.size();
		std::vector<int> widths(ncols);
		size_t w = 0;
		for (size_t i = 0; i < ncols; i++) widths[i] = std::max((int)utf8_display_width(t->columns[i].name), (int)utf8_display_width(t->columns[i].type.short_name()));
		for (size_t i = 0; i < ncols; i++) w = std::max(w, (size_t)widths[i]);
		w = w == 0 ? 0 : w;
		size_t bw = 0;
		for (size_t i = 0; i < ncols; i++) bw += widths[i] + 3;
		bw += 1;
		auto border = [&](char l, char m, char r) {
			std::string o;
			o += l;
			for (size_t i = 0; i < ncols; i++) {
				if (i) o += m;
				for (int j = 0; j < widths[i] + 2; j++) o += "\u2500";
			}
			o += r;
			return o;
		};
		lines.push_back(border(0x250c, 0x252c, 0x2510));
		{
			std::string o = "\u2502";
