static void set_output_file(const std::string &name, bool once) {
	FILE *f = nullptr;
	if (name.empty()) { f = stdout; }
	else if (name[0] == '|') { f = popen(name.c_str() + 1, "w"); }
	else f = fopen(name.c_str(), "wb");
	if (once) {
		if (g_once_file) fclose(g_once_file);
		g_once_file = f;
		g_once_name = name;
		g_once_is_pipe = !name.empty() && name[0] == '|';
		g_once_count++;
	} else {
		if (g_out && g_out != stdout) fclose(g_out);
		g_out = f;
		g_output_file = name;
	}
}

static void close_once() {
	if (g_once_file) {
		if (g_once_is_pipe) pclose(g_once_file);
		else fclose(g_once_file);
		g_once_file = nullptr;
		g_once_name.clear();
	}
}

static void run_dot_command(const std::string &line) {
	std::string args = line;
	// split the command name
	size_t i = 0;
	while (i < args.size() && !isspace((unsigned char)args[i])) i++;
	std::string cmd = args.substr(0, i);
	std::string rest = trim_ws(args.substr(i));
	if (rest.size() > 0) {
		// handle quoting for .print etc later
	}
	std::string c = to_lower(cmd);
	auto next_arg = [&]() {
		size_t j = 0;
		while (j < rest.size() && isspace((unsigned char)rest[j])) j++;
		size_t start = j;
		while (j < rest.size() && !isspace((unsigned char)rest[j])) j++;
		std::string a = rest.substr(start, j - start);
		rest = trim_ws(rest.substr(j));
		return a;
	};
	if (c == ".quit" || c == ".exit") {
		int code = 0;
		if (!rest.empty()) {
			try { code = (int)std::stol(rest); } catch (...) { code = 0; }
		}
		fflush(stdout);
		exit(code);
	}
	if (c == ".version") {
		print_stdout(std::string("DuckDB ") + kVersion + "\n" + kCompiler + "\n");
		return;
	}
	if (c == ".help") {
		bool all = false;
		std::string pat;
		if (iequals(trim_ws(rest), "-all") || iequals(trim_ws(rest), "--all")) { all = true; }
		else if (!rest.empty()) pat = rest;
		std::string out = format_dot_help(pat, all);
		if (!all && pat.empty()) out += dot_help_footer_text();
		print_stdout(out);
		return;
	}
	if (c == ".mode") {
		std::string m = next_arg();
		if (m.empty()) { print_stdout("current output mode: " + g_rs.mode_name() + "\n"); return; }
		RenderMode nm;
		if (m == "ascii") nm = RenderMode::ASCII;
		else if (m == "box" || m == "duckbox") nm = RenderMode::DuckBox;
		else if (m == "column") nm = RenderMode::Column;
		else if (m == "csv") nm = RenderMode::CSV;
		else if (m == "html") nm = RenderMode::HTML;
		else if (m == "insert") nm = RenderMode::Insert;
		else if (m == "json") nm = RenderMode::JSON;
		else if (m == "jsonlines") nm = RenderMode::JSONLines;
		else if (m == "latex") nm = RenderMode::Latex;
		else if (m == "line") nm = RenderMode::Line;
		else if (m == "list") nm = RenderMode::List;
		else if (m == "markdown") nm = RenderMode::Markdown;
		else if (m == "quote") nm = RenderMode::Quote;
		else if (m == "table") nm = RenderMode::Table;
		else if (m == "tabs") nm = RenderMode::Tabs;
		else if (m == "tcl") nm = RenderMode::TCL;
