static void set_output_file(const std::string &name, bool once) {
	FILE *f = nullptr;
	if (name.empty()) { f = stdout; }
	else if (name[0] == '|') { f = popen(name.c_str() + 1, "w"); }
	else f = fopen(name.c_str(), "wb");
	if (once) {
		if (g_once_file) fclose(g_once_file);
		g_once_file = f;
		g_once_name = name;
		g_once_is_pipe = !name.empty() && name[0] == '|';
		g_once_count++;
	} else {
		if (g_out && g_out != stdout) fclose(g_out);
		g_out = f;
		g_output_file = name;
	}
}

static void close_once() {
	if (g_once_file) {
		if (g_once_is_pipe) pclose(g_once_file);
		else fclose(g_once_file);
		g_once_file = nullptr;
		g_once_name.clear();
	}
}

