static bool statement_complete(const std::string &s) {
	// a statement is complete when the semicolons outside of strings/parens balance
	bool in_str = false, in_ident = false;
	int depth = 0;
	for (size_t i = 0; i < s.size(); i++) {
		char c = s[i];
		if (in_str) {
			if (c == '\'') {
				if (i + 1 < s.size() && s[i + 1] == '\'') { i++; continue; }
				in_str = false;
			}
			continue;
		}
		if (in_ident) {
			if (c == '"') {
				if (i + 1 < s.size() && s[i + 1] == '"') { i++; continue; }
				in_ident = false;
			}
			continue;
		}
		if (c == '\'') { in_str = true; continue; }
		if (c == '"') { in_ident = true; continue; }
		if (c == '-' && i + 1 < s.size() && s[i + 1] == '-') { while (i < s.size() && s[i] != '\n') i++; continue; }
		if (c == '/' && i + 1 < s.size() && s[i + 1] == '*') { i += 2; while (i + 1 < s.size() && !(s[i] == '*' && s[i + 1] == '/')) i++; i++; continue; }
		if (c == '(' || c == '[' || c == '{') depth++;
		if (c == ')' || c == ']' || c == '}') depth--;
		if (c == ';' && depth <= 0) return true;
	}
	return false;
}

