static void run_file(const std::string &path, bool echo) {
	FILE *fp = fopen(path.c_str(), "rb");
	if (!fp) {
		print_error("IO Error: Cannot open file \"" + path + "\": No such file or directory");
		exit(1);
	}
	std::string content;
	char buf[4096];
	size_t n;
	while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) content.append(buf, n);
	fclose(fp);
	// process line by line
	std::string pending, cur;
	for (size_t k = 0; k < content.size(); k++) {
		char ch = content[k];
		if (ch == '\r') continue;
		if (ch == '\n') {
			std::string l = trim_ws(pending);
			pending.clear();
			if (l.empty()) continue;
			if (l[0] == '.') run_dot_command(l);
			else {
				cur += l;
				if (statement_complete(cur)) { run_sql(cur, echo); cur.clear(); }
				else cur += "\n";
			}
		} else pending += ch;
	}
	if (!trim_ws(pending).empty()) {
		std::string l = trim_ws(pending);
		if (l[0] == '.') run_dot_command(l);
		else { cur += l; }
	}
	if (!trim_ws(cur).empty()) run_sql(cur, echo);
}

