s=open('src/parser.cpp').read()
i=0
n=len(s)
depth=0
line=1
state='code'
stack=[]
while i<n:
    c=s[i]
    if c=='\n': line+=1; i+=1; continue
    if state=='code':
        if c=='"':
            state='str'; i+=1; continue
        if c=="'":
            state='chr'; i+=1; continue
        if c=='/' and i+1<n and s[i+1]=='/':
            while i<n and s[i]!='\n': i+=1
            continue
        if c=='/' and i+1<n and s[i+1]=='*':
            state='blk'; i+=2; continue
        if c=='{':
            depth+=1; stack.append(line); i+=1; continue
        if c=='}':
            depth-=1
            if stack: stack.pop()
            i+=1; continue
        i+=1; continue
    if state=='str':
        if c=='\\': i+=2; continue
        if c=='"': state='code'
        i+=1; continue
    if state=='chr':
        if c=='\\': i+=2; continue
        if c=="'": state='code'
        i+=1; continue
    if state=='blk':
        if c=='*' and i+1<n and s[i+1]=='/': state='code'; i+=2; continue
        i+=1; continue
print("final depth", depth, "unclosed opens at lines", stack[:10])
PYEOF"}

