namespace ddb {

// ------------------------------------------------------------------- scope
int Scope::resolve(const std::string &table, const std::string &column, int &out_table_index) const {
	for (size_t i = 0; i < cols.size(); i++) {
		if (!table.empty() && !iequals(cols[i].table_name, table)) continue;
		if (iequals(cols[i].column_name, column) || (!cols[i].alias.empty() && iequals(cols[i].alias, column))) {
			out_table_index = cols[i].table_index;
			return (int)i;
		}
	}
	return -1;
}
int Scope::resolve_any(const std::string &column) const {
	for (size_t i = 0; i < cols.size(); i++) {
		if (iequals(cols[i].column_name, column) || (!cols[i].alias.empty() && iequals(cols[i].alias, column))) return (int)i;
	}
	return -1;
}
std::vector<int> Scope::resolve_all(const std::string &column) const {
	std::vector<int> out;
	for (size_t i = 0; i < cols.size(); i++) {
		if (iequals(cols[i].column_name, column) || (!cols[i].alias.empty() && iequals(cols[i].alias, column))) out.push_back((int)i);
	}
	return out;
}

// ------------------------------------------------------------ name rendering
static std::string type_to_cast_name(const LogicalType &t) {
	if (t.id == TId::DATE) return "\"DATE\"";
	if (t.id == TId::DECIMAL) {
		char buf[64];
		snprintf(buf, sizeof(buf), "DECIMAL(%d,%d)", t.width, t.scale);
		return buf;
	}
	if (t.id == TId::STRUCT) {
		std::string o = "STRUCT(";
		for (size_t i = 0; i < t.children.size(); i++) {
			if (i) o += ", ";
			o += "\"" + t.child_names[i] + "\" " + t.children[i].sql_name();
		}
		return o + ")";
	}
	if (t.id == TId::MAP) {
		std::string a = t.children.size() > 0 ? t.children[0].sql_name() : std::string("UNKNOWN");
		std::string b = t.children.size() > 1 ? t.children[1].sql_name() : std::string("UNKNOWN");
		return "MAP(" + a + ", " + b + ")";
	}
	if (t.id == TId::LIST) return (t.children.empty() ? std::string("UNKNOWN") : t.children[0].sql_name()) + "[]";
	if (t.id == TId::ARRAY) {
		std::string base = t.children.empty() ? std::string("UNKNOWN") : t.children[0].sql_name();
		char buf[64];
		snprintf(buf, sizeof(buf), "[%d]", t.length);
		return base + buf;
	}
	if (t.id == TId::UNION) {
		std::string o = "UNION(";
		for (size_t i = 0; i < t.children.size(); i++) {
			if (i) o += ", ";
			o += "\"" + t.child_names[i] + "\" " + t.children[i].sql_name();
		}
		return o + ")";
	}
	return t.sql_name();
}

static const char *op_symbol(int op, const std::string &text = "") {
	switch (op) {
	case OP_ADD: return text == "||" ? "||" : "+";
	case OP_SUB: return "-";
	case OP_MUL: return "*";
	case OP_DIV: return "/";
	case OP_INTDIV: return "//";
	case OP_MOD: return "%";
	case OP_POW: return "**";
	case OP_AND_BIT: return "&";
	case OP_OR_BIT: return "|";
	case OP_SHL: return "<<";
	case OP_SHR: return ">>";
	case 20: return "=";
	case 21: return "!=";
	case 22: return "<";
	case 23: return "<=";
	case 24: return ">";
	case 25: return ">=";
	case 100: return "AND";
	case 101: return "OR";
	default: return "?";
	}
}

static std::string func_display_name(const FuncDef *def, bool has_star) {
	if (has_star) return "count_star";
	if (def && !def->display.empty()) return def->display;
	if (def && def->name == "version") return "\"version\"";
	if (def) return def->name;
	return "";
}

static std::string expr_name_impl(const Expr *e);

static std::string args_to_name(const std::vector<std::unique_ptr<Expr>> &args, const std::vector<std::string> *named = nullptr) {
	std::string o;
	for (size_t i = 0; i < args.size(); i++) {
		if (i) o += ", ";
		std::string a = expr_name_impl(args[i].get());
		if (named && i < named->size() && !(*named)[i].empty()) a = (*named)[i] + " := " + a;
		o += a;
	}
	return o;
}

static std::string expr_name_impl(const Expr *e) {
	if (!e) return "";
	switch (e->kind) {
	case EK::ColumnRef:
		if (!e->column.empty()) return e->column;
		return e->text;
	case EK::Star: return "*";
	case EK::TableStar: return e->table + ".*";
	case EK::Constant: {
		if (e->value.null) return "NULL";
		if (e->value.type.id == TId::VARCHAR) return "'" + e->value.s + "'";
		if (e->value.type.id == TId::BLOB) return "'" + e->value.to_string() + "'";
		if (e->value.type.id == TId::INTERVAL) return e->value.to_string();
		return e->value.to_string();
	}
	case EK::Cast: {
		if (e->args.size() != 1) return "CAST(...)";
		return "CAST(" + expr_name_impl(e->args[0].get()) + " AS " + type_to_cast_name(e->type) + ")";
	}
	case EK::Binary: {
		if (e->args.size() != 2) return "";
		return "(" + expr_name_impl(e->args[0].get()) + " " + op_symbol(e->op, e->text) + " " + expr_name_impl(e->args[1].get()) + ")";
	}
	case EK::Unary: {
		if (e->args.size() != 1) return "";
		if (e->op == OP_SUB) return "(-" + expr_name_impl(e->args[0].get()) + ")";
		if (e->op == 2) return "(NOT " + expr_name_impl(e->args[0].get()) + ")";
		if (e->op == 3) return "(~" + expr_name_impl(e->args[0].get()) + ")";
		return expr_name_impl(e->args[0].get());
	}
	case EK::Func: {
		if (e->op == 200) {
			return expr_name_impl(e->args[0].get()) + " FILTER (WHERE " + expr_name_impl(e->extra.empty() ? nullptr : e->extra[0].get()) + ")";
		}
		if (e->op == 300) {
			return e->text + "()";
		}
		const FuncDef *def = find_function(e->text);
		bool has_star = e->args.size() == 1 && e->args[0]->kind == EK::Star && !e->distinct;
		std::string dn;
		std::string args;
		std::string prefix;
		if (has_star) {
			dn = "count_star";
		} else if (def && !def->display.empty()) {
			dn = def->display;
		} else if (def) {
			dn = def->name;
			if (def->name == "version" || def->name == "first" || def->name == "last" || def->name == "range" ||
			    def->name == "row" || def->name == "unnest" || def->name == "generate_series" || def->name == "list" ||
			    def->name == "first_value" || def->name == "last_value") {
				dn = "\"" + def->name + "\"";
			}
			if (def->kind == FuncKind::Macro) {
				if (def->name == "list_value" || def->name == "struct_pack" || def->name == "map") prefix = "main.";
				else if (!e->schema_name.empty()) prefix = e->schema_name + ".";
			}
		} else {
			dn = e->text;
		}
		if (!has_star) args = args_to_name(e->args, &e->named_args);
		if (e->distinct) args = "DISTINCT " + args;
		return prefix + dn + "(" + args + ")";
	}
	case EK::Case: {
		std::string o = "CASE ";
		if (e->extra.size() == 1) o += expr_name_impl(e->extra[0].get()) + " ";
		for (size_t i = 0; i + 1 < e->args.size(); i += 2) {
			o += " WHEN (" + expr_name_impl(e->args[i].get()) + ") THEN (" + expr_name_impl(e->args[i + 1].get()) + ")";
		}
		if (e->args.size() % 2 == 1) o += " ELSE " + expr_name_impl(e->args.back().get());
		return o + " END";
	}
	case EK::In: {
		std::string o = "(" + expr_name_impl(e->args[0].get()) + (e->negated ? " NOT IN (" : " IN (");
		if (!e->extra.empty() && e->extra[0]->kind == EK::Subquery) {
			o += "SELECT ...)";
		} else {
			for (size_t i = 0; i < e->extra.size(); i++) {
				if (i) o += ", ";
				o += expr_name_impl(e->extra[i].get());
			}
			o += ")";
		}
		return o + ")";
	}
	case EK::Between: {
		if (e->negated) {
			return "((" + expr_name_impl(e->args[0].get()) + " < " + expr_name_impl(e->args[1].get()) + ") OR (" +
			       expr_name_impl(e->args[0].get()) + " > " + expr_name_impl(e->args[2].get()) + "))";
		}
		return "((" + expr_name_impl(e->args[0].get()) + " >= " + expr_name_impl(e->args[1].get()) + ") AND (" +
		       expr_name_impl(e->args[0].get()) + " <= " + expr_name_impl(e->args[2].get()) + "))";
	}
	case EK::Like: {
		std::string op = e->text == "glob" ? "GLOB" : (e->text == "regexp_matches" ? "REGEXP_MATCHES" : (e->text == "ilike" ? "ILIKE" : "LIKE"));
		if (e->negated) op = "NOT " + op;
		return "(" + expr_name_impl(e->args[0].get()) + " " + op + " " + expr_name_impl(e->args[1].get()) + ")";
	}
	case EK::IsNull: {
		return "(" + expr_name_impl(e->args[0].get()) + (e->negated ? " IS NOT NULL)" : " IS NULL)");
	}
	case EK::Subquery: return "(SELECT ...)";
	case EK::Exists: return "EXISTS(SELECT ...)";
	case EK::ListCtor: {
		if (e->op == 10) {
			std::string o = "( ";
			for (size_t i = 0; i < e->args.size(); i++) {
				if (i) o += ", ";
				o += expr_name_impl(e->args[i].get());
			}
			return o + " )";
		}
		std::string args;
		for (size_t i = 0; i < e->args.size(); i++) {
			if (i) args += ", ";
			args += expr_name_impl(e->args[i].get());
		}
		return "main.list_value(" + args + ")";
	}
	case EK::StructCtor: {
		std::string args;
		for (size_t i = 0; i < e->args.size(); i++) {
			if (i) args += ", ";
			args += (e->args[i]->text.empty() ? "v" + std::to_string(i + 1) : e->args[i]->text) + " := " + expr_name_impl(e->args[i].get());
		}
		return "main.struct_pack(" + args + ")";
	}
	case EK::MapCtor: {
		std::string args;
		for (size_t i = 0; i < e->args.size(); i++) {
			if (i) args += ", ";
			args += expr_name_impl(e->args[i].get()) + " := " + expr_name_impl(e->extra[i].get());
		}
		return "main.map(" + args + ")";
	}
	case EK::Window: return expr_name_impl(e->args.empty() ? nullptr : e->args[0].get());
	case EK::Collate: return "(" + expr_name_impl(e->args[0].get()) + " COLLATE \"" + e->text + "\")";
	case EK::Default: return "DEFAULT";
	default: return e->text;
	}
}

std::string expr_name(const Expr *e, const std::string &alias) {
	if (!alias.empty()) return alias;
	return expr_name_impl(e);
}
