// --------------------------------------------------------------- evaluation
Value eval_expr(const Expr *e, Scope &scope, Engine *eng) {
	if (!e) return Value();
	switch (e->kind) {
	case EK::ColumnRef: {
		if (e->bound_index >= 0 && (size_t)e->bound_index < scope.cols.size()) {
			if (!scope.row) return Value::nullval(scope.cols[e->bound_index].type);
			return (*scope.row)[e->bound_index];
		}
		int ti = -1;
		int idx = scope.resolve(e->table, e->column, ti);
		if (idx < 0) idx = scope.resolve_any(e->column);
		if (idx >= 0) {
			if (!scope.row) return Value::nullval(scope.cols[idx].type);
			return (*scope.row)[idx];
		}
		if (scope.parent) {
			Scope ps = *scope.parent;
			return eval_expr(e, ps, eng);
		}
		if (scope.cols.empty()) {
			throw DuckDBException(DuckDBException::Type::BINDER, "Referenced column \"" + e->column + "\" was not found because the FROM clause is missing").with_location(e->pos, e->pos);
		}
		std::string cands;
		for (size_t i = 0; i < scope.cols.size(); i++) {
			cands += "\t" + scope.cols[i].table_name + "." + scope.cols[i].column_name + " (" + scope.cols[i].type.sql_name() + ")\n";
		}
		throw DuckDBException(DuckDBException::Type::BINDER, "Referenced column \"" + e->column + "\" not found in FROM clause!\nCandidate bindings: \n" + cands).with_location(e->pos, e->pos);
	}
	case EK::Star: case EK::TableStar:
		return Value::intv(1, TId::BIGINT);
	case EK::Constant: return e->value;
	case EK::Cast: {
		Value v = eval_expr(e->args[0].get(), scope, eng);
		if (e->type.id == TId::UNKNOWN) return v;
		return do_cast(v, e->type);
	}
	case EK::Binary: {
		if (e->op == 100) {
			Value l = eval_expr(e->args[0].get(), scope, eng);
			if (!l.null && !l.as_bool()) return Value::boolean(false);
			Value r = eval_expr(e->args[1].get(), scope, eng);
			if (!r.null && !r.as_bool()) return Value::boolean(false);
			if (l.null || r.null) return Value::nullval(LogicalType(TId::BOOLEAN));
			return Value::boolean(true);
		}
		if (e->op == 101) {
			Value l = eval_expr(e->args[0].get(), scope, eng);
			if (!l.null && l.as_bool()) return Value::boolean(true);
			Value r = eval_expr(e->args[1].get(), scope, eng);
			if (!r.null && r.as_bool()) return Value::boolean(true);
			if (l.null || r.null) return Value::nullval(LogicalType(TId::BOOLEAN));
			return Value::boolean(false);
		}
		Value l = eval_expr(e->args[0].get(), scope, eng);
		Value r = eval_expr(e->args[1].get(), scope, eng);
		if (e->flags.size() > 0 && e->flags[0]) return apply_comparison(e->op, l, r);
