// --------------------------------------------------------------- evaluation
Value eval_expr(const Expr *e, Scope &scope, Engine *eng) {
	if (!e) return Value();
	switch (e->kind) {
	case EK::ColumnRef: {
		if (e->bound_index >= 0 && (size_t)e->bound_index < scope.cols.size()) {
			if (!scope.row) return Value::nullval(scope.cols[e->bound_index].type);
			return (*scope.row)[e->bound_index];
		}
		int ti = -1;
		int idx = scope.resolve(e->table, e->column, ti);
		if (idx < 0) idx = scope.resolve_any(e->column);
		if (idx >= 0) {
			if (!scope.row) return Value::nullval(scope.cols[idx].type);
			return (*scope.row)[idx];
		}
		if (scope.parent) {
			Scope ps = *scope.parent;
			return eval_expr(e, ps, eng);
		}
		if (scope.cols.empty()) {
			throw DuckDBException(DuckDBException::Type::BINDER, "Referenced column \"" + e->column + "\" was not found because the FROM clause is missing").with_location(e->pos, e->pos);
		}
		std::string cands;
		for (size_t i = 0; i < scope.cols.size(); i++) {
			cands += "\t" + scope.cols[i].table_name + "." + scope.cols[i].column_name + " (" + scope.cols[i].type.sql_name() + ")\n";
		}
		throw DuckDBException(DuckDBException::Type::BINDER, "Referenced column \"" + e->column + "\" not found in FROM clause!\nCandidate bindings: \n" + cands).with_location(e->pos, e->pos);
	}
	case EK::Star: case EK::TableStar:
		return Value::intv(1, TId::BIGINT);
	case EK::Constant: return e->value;
	case EK::Cast: {
		Value v = eval_expr(e->args[0].get(), scope, eng);
		if (e->type.id == TId::UNKNOWN) return v;
		return do_cast(v, e->type);
	}
	case EK::Binary: {
		if (e->op == 100) {
			Value l = eval_expr(e->args[0].get(), scope, eng);
			if (!l.null && !l.as_bool()) return Value::boolean(false);
			Value r = eval_expr(e->args[1].get(), scope, eng);
			if (!r.null && !r.as_bool()) return Value::boolean(false);
			if (l.null || r.null) return Value::nullval(LogicalType(TId::BOOLEAN));
			return Value::boolean(true);
		}
		if (e->op == 101) {
			Value l = eval_expr(e->args[0].get(), scope, eng);
			if (!l.null && l.as_bool()) return Value::boolean(true);
			Value r = eval_expr(e->args[1].get(), scope, eng);
			if (!r.null && r.as_bool()) return Value::boolean(true);
			if (l.null || r.null) return Value::nullval(LogicalType(TId::BOOLEAN));
			return Value::boolean(false);
		}
		Value l = eval_expr(e->args[0].get(), scope, eng);
		Value r = eval_expr(e->args[1].get(), scope, eng);
		if (e->flags.size() > 0 && e->flags[0]) return apply_comparison(e->op, l, r);
		return apply_binary_op(e->op, l, r);
	}
	case EK::Unary: {
		if (e->op == 2) {
			Value v = eval_expr(e->args[0].get(), scope, eng);
			if (v.null) return Value::nullval(LogicalType(TId::BOOLEAN));
			return Value::boolean(!v.as_bool());
		}
		if (e->op == 3) {
			Value v = eval_expr(e->args[0].get(), scope, eng);
			if (v.null) return Value::nullval(v.type);
			return Value::intv(~v.as_int(), v.type.id == TId::HUGEINT ? TId::HUGEINT : v.type.id);
		}
		Value v = eval_expr(e->args[0].get(), scope, eng);
		return apply_unary_op(e->negated ? OP_SUB : OP_ADD, v);
	}
	case EK::Func: {
		if (e->op == 200) {
			if (e->is_aggregate && scope.agg_results && e->agg_id >= 0 && (size_t)e->agg_id < scope.agg_results->size()) {
				return (*scope.agg_results)[e->agg_id];
			}
			return eval_expr(e->args[0].get(), scope, eng);
		}
		if (e->op == 300) {
			std::string n = e->text;
			if (n == "current_date" || n == "today") {
				throw DuckDBException(DuckDBException::Type::CATALOG, "Scalar Function with name \"" + n + "\" is not in the catalog, but it exists in the icu extension.\n\nPlease try installing and loading the icu extension by running:\nINSTALL icu;\nLOAD icu;\n\nAlternatively, consider enabling auto-install and auto-load by running:\nSET autoinstall_known_extensions=1;\nSET autoload_known_extensions=1;").with_location(e->pos, e->pos);
			}
			if (n == "current_timestamp") return Value::timestamp(now_micros());
			if (n == "current_time") return Value::time(now_micros() % 86400000000LL);
			if (n == "localtime" || n == "localtimestamp") return Value::timestamp(now_micros());
			return Value();
		}
		if (e->is_aggregate) {
			if (scope.agg_results && e->agg_id >= 0 && (size_t)e->agg_id < scope.agg_results->size()) {
				return (*scope.agg_results)[e->agg_id];
			}
			const FuncDef *def0 = find_function(e->text);
			if (def0) return Value::nullval(def0->ret({}));
			return Value();
		}
		if (e->is_window) {
			if (scope.agg_results && e->window_id >= 0 && (size_t)e->window_id < scope.agg_results->size()) {
				return (*scope.agg_results)[e->window_id];
			}
			const FuncDef *def0 = find_function(e->text);
			if (def0) return Value::nullval(def0->ret({}));
			return Value();
		}
		const FuncDef *def = find_function(e->text);
		if (!def) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "Scalar Function with name " + e->text + " does not exist!\n" +
			              suggestion_for(e->text, kFunctionNames)).with_location(e->pos, e->pos);
		}
		if (def->kind == FuncKind::Table) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table Function with name " + e->text + " does not exist!").with_location(e->pos, e->pos);
		}
		std::vector<Value> args;
		for (auto &a : e->args) {
			Value v = eval_expr(a.get(), scope, eng);
			v.text = a->text;
			args.push_back(v);
		}
		if (e->args.size() < (size_t)def->min_args || (!def->has_variadic && e->args.size() > (size_t)def->max_args)) {
			std::string msg = "No function matches the given name and argument types: '" + e->text + "(";
			for (size_t i = 0; i < e->args.size(); i++) {
				if (i) msg += ", ";
				msg += e->args[i]->type.sql_name();
			}
			msg += ")'. You might need to add explicit type casts.\n\tCandidate functions:\n";
			throw DuckDBException(DuckDBException::Type::CATALOG, msg).with_location(e->pos, e->pos);
		}
		return def->eval(args);
	}
	case EK::Case: {
		Value base;
		bool has_base = false;
		if (e->extra.size() == 1) { base = eval_expr(e->extra[0].get(), scope, eng); has_base = true; }
		for (size_t i = 0; i + 1 < e->args.size(); i += 2) {
			bool cond;
			if (has_base) {
				Value w = eval_expr(e->args[i].get(), scope, eng);
				cond = !w.null && base.equals(w);
			} else {
				Value c = eval_expr(e->args[i].get(), scope, eng);
				cond = !c.null && c.as_bool();
			}
			if (cond) return eval_expr(e->args[i + 1].get(), scope, eng);
		}
		if (e->args.size() % 2 == 1) return eval_expr(e->args.back().get(), scope, eng);
		return Value::nullval(LogicalType(TId::UNKNOWN));
	}
	case EK::In: {
		Value l = eval_expr(e->args[0].get(), scope, eng);
		if (e->op == 30) {
			if (e->extra.size() != 1) return Value::nullval(LogicalType(TId::BOOLEAN));
			Value r = eval_expr(e->extra[0].get(), scope, eng);
			if (l.null && r.null) return Value::boolean(false);
			if (l.null || r.null) return Value::boolean(true);
			return Value::boolean(!l.equals(r));
		}
		if (e->op == 31) {
			if (l.null) return Value::nullval(LogicalType(TId::BOOLEAN));
			bool v = l.as_bool();
			bool target = e->flags.empty() ? true : e->flags[0];
			bool res = (v == target);
			return Value::boolean(e->negated ? !res : res);
		}
		if (e->extra.size() == 1 && e->extra[0]->kind == EK::Subquery) {
			Result r = eng->execute_query(*e->extra[0]->query, &scope);
			bool found = false;
			for (auto &row : r.rows) {
				if (row.empty()) continue;
				if (!row[0].null && l.equals(row[0])) { found = true; break; }
			}
			return Value::boolean(e->negated ? !found : found);
		}
		bool found = false, has_null = false;
		for (auto &x : e->extra) {
			Value v = eval_expr(x.get(), scope, eng);
			if (v.null) { has_null = true; continue; }
			if (!l.null && l.equals(v)) { found = true; break; }
		}
		if (found) return Value::boolean(!e->negated);
		if (has_null) return Value::nullval(LogicalType(TId::BOOLEAN));
		return Value::boolean(e->negated);
	}
	case EK::Between: {
		Value v = eval_expr(e->args[0].get(), scope, eng);
		Value lo = eval_expr(e->args[1].get(), scope, eng);
		Value hi = eval_expr(e->args[2].get(), scope, eng);
		if (v.null || lo.null || hi.null) return Value::nullval(LogicalType(TId::BOOLEAN));
		bool in = v.compare(lo) >= 0 && v.compare(hi) <= 0;
		return Value::boolean(e->negated ? !in : in);
	}
	case EK::Like: {
		Value l = eval_expr(e->args[0].get(), scope, eng);
		Value r = eval_expr(e->args[1].get(), scope, eng);
		if (l.null || r.null) return Value::nullval(LogicalType(TId::BOOLEAN));
		std::string s = l.to_string(), p = r.to_string();
		bool res = false;
		if (e->text == "glob") res = glob_match_impl(s, p);
		else if (e->text == "regexp_matches" || e->text == "regexp") res = simple_regex_search(s, p);
		else if (e->text == "similar_to") res = simple_regex_search(s, p);
		else res = like_match_impl(s, p, e->case_insensitive);
		return Value::boolean(e->negated ? !res : res);
	}
	case EK::IsNull: {
		Value v = eval_expr(e->args[0].get(), scope, eng);
		return Value::boolean(e->negated ? !v.null : v.null);
	}
	case EK::Subquery: {
		Result r = eng->execute_query(*e->query, &scope);
		if (r.rows.empty()) return Value::nullval(r.types.empty() ? LogicalType(TId::UNKNOWN) : r.types[0]);
		if (r.rows[0].empty()) return Value::nullval(LogicalType(TId::UNKNOWN));
		return r.rows[0][0];
	}
	case EK::Exists: {
		Result r = eng->execute_query(*e->query, &scope);
		return Value::boolean(!r.rows.empty());
	}
	case EK::ListCtor: {
		if (e->op == 10) {
			std::vector<std::string> names;
			std::vector<LogicalType> types;
			std::vector<Value> vals;
			for (auto &a : e->args) {
				Value v = eval_expr(a.get(), scope, eng);
				v.text = a->text;
				names.push_back(a->text.empty() ? "v" + std::to_string(names.size() + 1) : a->text);
				types.push_back(v.type);
				vals.push_back(v);
			}
			return Value::structval(vals, LogicalType::struct_type(names, types));
		}
		LogicalType inner(TId::UNKNOWN);
		std::vector<Value> items;
		for (auto &a : e->args) {
			Value v = eval_expr(a.get(), scope, eng);
			items.push_back(v);
			if (!v.null && inner.id == TId::UNKNOWN) inner = v.type;
		}
		return Value::listval(items, LogicalType::list_type(inner));
	}
	case EK::StructCtor: {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		std::vector<Value> vals;
		for (auto &a : e->args) {
			Value v = eval_expr(a.get(), scope, eng);
			v.text = a->text;
			names.push_back(a->text.empty() ? "v" + std::to_string(names.size() + 1) : a->text);
			types.push_back(v.type);
			vals.push_back(v);
		}
		return Value::structval(vals, LogicalType::struct_type(names, types));
	}
	case EK::MapCtor: {
		Value o;
		o.type = LogicalType(TId::MAP);
		o.null = false;
		for (size_t i = 0; i < e->args.size(); i++) {
			Value k = eval_expr(e->args[i].get(), scope, eng);
			Value v = eval_expr(e->extra[i].get(), scope, eng);
			o.kv.push_back({k.to_string(), v});
		}
		return o;
	}
	case EK::Window: return eval_expr(e->args.empty() ? nullptr : e->args[0].get(), scope, eng);
	case EK::Collate: return eval_expr(e->args[0].get(), scope, eng);
	case EK::Default: return Value();
	default: return Value();
	}
