// ------------------------------------------------------- table functions
bool Engine::eval_table_function(const std::string &name, const std::vector<Value> &args, std::vector<std::string> &names,
                                 std::vector<LogicalType> &types, std::vector<std::vector<Value>> &rows) {
	std::string n = to_lower(name);
	if (n == "range" || n == "generate_series") {
		int64_t start = 0, stop = 0, step = 1;
		bool inclusive = (n == "generate_series");
		if (args.size() == 1) stop = args[0].as_int();
		else if (args.size() == 2) { start = args[0].as_int(); stop = args[1].as_int(); }
		else if (args.size() == 3) { start = args[0].as_int(); stop = args[1].as_int(); step = args[2].as_int(); }
		else return false;
		names = {"range"};
		types = {LogicalType(TId::BIGINT)};
		if (step == 0) return true;
		if (step > 0) {
			for (int64_t i = start; inclusive ? i <= stop : i < stop; i += step) rows.push_back({Value::intv(i, TId::BIGINT)});
		} else {
			for (int64_t i = start; inclusive ? i >= stop : i > stop; i += step) rows.push_back({Value::intv(i, TId::BIGINT)});
		}
		return true;
	}
	if (n == "read_csv" || n == "read_csv_auto") {
		std::string path = args.empty() ? std::string("") : args[0].to_string();
		if (path.empty()) return false;
		FILE *fp = fopen(path.c_str(), "rb");
		if (!fp) throw DuckDBException(DuckDBException::Type::IO, "No files found that match the pattern \"" + path + "\"");
		std::string content;
		char buf[4096];
		size_t r;
		while ((r = fread(buf, 1, sizeof(buf), fp)) > 0) content.append(buf, r);
		fclose(fp);
		std::vector<std::vector<std::string>> records;
		std::vector<std::string> cur;
		std::string field;
		bool in_q = false;
		for (size_t i = 0; i < content.size(); i++) {
			char c = content[i];
			if (in_q) {
				if (c == '"') {
					if (i + 1 < content.size() && content[i + 1] == '"') { field += '"'; i++; continue; }
					in_q = false;
					continue;
				}
				field += c;
				continue;
			}
			if (c == '"') { in_q = true; continue; }
			if (c == ',') { cur.push_back(field); field.clear(); continue; }
			if (c == '\r') continue;
			if (c == '\n') { cur.push_back(field); field.clear(); records.push_back(cur); cur.clear(); continue; }
			field += c;
		}
		if (!field.empty() || !cur.empty()) { cur.push_back(field); records.push_back(cur); }
		if (records.empty()) return true;
		size_t ncols = 0;
		for (auto &rec : records) ncols = std::max(ncols, rec.size());
		bool has_header = true;
		for (size_t i = 0; i < records[0].size(); i++) {
			std::string h = records[0][i];
			bool numeric = !h.empty();
			for (char c : h) if (!isdigit((unsigned char)c) && c != '-' && c != '.' && c != '+') numeric = false;
			if (numeric || h.empty()) has_header = false;
		}
		size_t start = has_header ? 1 : 0;
		for (size_t i = 0; i < ncols; i++) {
			std::string cn = has_header && i < records[0].size() ? records[0][i] : ("column" + std::to_string(i));
			names.push_back(cn);
		}
		std::vector<LogicalType> coltypes(ncols);
		for (size_t c = 0; c < ncols; c++) {
			bool allint = true, allnum = true;
			for (size_t r2 = start; r2 < records.size(); r2++) {
				std::string v = c < records[r2].size() ? records[r2][c] : "";
				if (v.empty()) continue;
				bool isint = true, isnum = true;
				for (size_t k = 0; k < v.size(); k++) {
					char ch = v[k];
					if (ch == '-' && k == 0) continue;
					if (ch == '.') isint = false;
					if (!isdigit((unsigned char)ch) && ch != '.' && ch != '-' && ch != '+' && ch != 'e' && ch != 'E') isnum = false;
				}
				if (!isint) allint = false;
				if (!isnum) allnum = false;
			}
			if (allint) coltypes[c] = LogicalType(TId::BIGINT);
			else if (allnum) coltypes[c] = LogicalType(TId::DOUBLE);
			else coltypes[c] = LogicalType(TId::VARCHAR);
		}
		types = coltypes;
		for (size_t r2 = start; r2 < records.size(); r2++) {
			std::vector<Value> row;
			for (size_t c = 0; c < ncols; c++) {
				std::string v = c < records[r2].size() ? records[r2][c] : "";
				if (v.empty() && !types[c].is_string()) row.push_back(Value::nullval(types[c]));
				else if (types[c].is_string()) row.push_back(Value::str(v));
				else row.push_back(do_cast(Value::str(v), types[c]));
			}
			rows.push_back(row);
		}
		return true;
	}
	return false;
}

// ----------------------------------------------------------------- binding
struct TempTable {
	std::string name;
	std::shared_ptr<Table> table;
};

static std::vector<TempTable> g_temp_tables;

std::shared_ptr<Table> Engine::resolve_table(const std::vector<std::string> &parts, std::string *schema_out) {
	std::string catalog, schema, name;
	if (parts.size() >= 3) { catalog = parts[parts.size() - 3]; schema = parts[parts.size() - 2]; name = parts[parts.size() - 1]; }
	else if (parts.size() == 2) { schema = parts[0]; name = parts[1]; }
	else if (parts.size() == 1) { name = parts[0]; }
	for (auto &t : g_temp_tables) if (iequals(t.name, name)) { if (schema_out) *schema_out = ""; return t.table; }
	if (iequals(schema, "pg_catalog") || iequals(schema, "information_schema")) {
		auto t = std::make_shared<Table>();
		t->name = name;
		t->schema = to_lower(schema);
		t->columns.push_back({"name", LogicalType(TId::VARCHAR), Value(), false, false, false, false, ""});
		if (schema_out) *schema_out = t->schema;
		return t;
	}
	Schema *s = schema.empty() ? db.main_schema() : db.find_schema(schema);
	if (!s && !schema.empty()) {
		throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name " + schema + " does not exist!");
	}
	if (!s) return nullptr;
	auto t = s->find(name);
	if (t && schema_out) *schema_out = s->name;
	return t;
}

void Engine::add_table(std::shared_ptr<Table> t) {
	Schema *s = db.find_schema(t->schema.empty() ? "main" : t->schema);
	if (!s) {
		db.schemas.push_back({t->schema.empty() ? "main" : t->schema, {}});
		s = &db.schemas.back();
	}
	for (auto &x : s->tables) if (iequals(x->name, t->name)) { x = t; return; }
	s->tables.push_back(t);
}

void Engine::drop_table(const std::string &schema, const std::string &name) {
	for (auto &s : db.schemas) {
		if (!schema.empty() && !iequals(s.name, schema)) continue;
		for (size_t i = 0; i < s.tables.size(); i++) {
			if (iequals(s.tables[i]->name, name)) { s.tables.erase(s.tables.begin() + i); return; }
		}
	}
}

std::vector<std::string> Engine::table_names(const std::string &pattern) {
	std::vector<std::string> out;
	for (auto &t : all_tables()) {
		if (t->is_view) continue;
		if (pattern.empty() || to_lower(t->name).find(to_lower(pattern)) != std::string::npos) out.push_back(t->name);
	}
	return out;
}

std::vector<std::shared_ptr<Table>> Engine::all_tables() {
	std::vector<std::shared_ptr<Table>> out;
	Schema *main = db.main_schema();
	if (main) for (auto &t : main->tables) out.push_back(t);
	Schema *temp = db.find_schema("temp");
	if (temp) for (auto &t : temp->tables) out.push_back(t);
	for (auto &t : g_temp_tables) out.push_back(t.table);
	return out;
}

Engine::Engine() {
	db.schemas.push_back({"main", {}});
	db.schemas.push_back({"temp", {}});
