// ------------------------------------------------------------- FROM binding
struct SourceData {
	std::vector<BoundCol> cols;
	std::vector<std::vector<Value>> rows;
	std::vector<std::string> table_names;
};

static void materialize_query(Engine *eng, const Query *q, Scope *outer, std::vector<std::string> &names,
                              std::vector<LogicalType> &types, std::vector<std::vector<Value>> &rows);

static void bind_table_ref(Engine *eng, TableRef *tr, SourceData &src, Scope *outer) {
	if (!tr) return;
	switch (tr->kind) {
	case TRK::Base: {
		std::string schema;
		std::vector<std::string> parts;
		if (!tr->name_parts[1].empty()) parts = {tr->name_parts[1], tr->name_parts[0], tr->name};
		else if (!tr->name_parts[0].empty()) parts = {tr->name_parts[0], tr->name};
		else parts = {tr->name};
		auto t = eng->resolve_table(parts, &schema);
		if (!t) {
			std::vector<std::string> names;
			std::vector<LogicalType> types;
			std::vector<std::vector<Value>> rows;
			if (eng->eval_table_function(tr->name, {}, names, types, rows)) {
				for (size_t i = 0; i < names.size(); i++) {
					BoundCol bc;
					bc.table_name = tr->alias.empty() ? tr->name : tr->alias;
					bc.column_name = names[i];
					bc.type = types[i];
					bc.table_index = i;
					bc.col_index = (int)i;
					src.cols.push_back(bc);
				}
				src.rows = rows;
				return;
			}
			std::string nm = tr->name;
			std::string sug = suggestion_for(nm, kTableNames);
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name " + nm + " does not exist!" + (sug.empty() ? "" : "\n" + sug)).with_location(tr->pos, tr->pos);
		}
		std::string tname = tr->alias.empty() ? t->name : tr->alias;
		for (size_t i = 0; i < t->columns.size(); i++) {
			BoundCol bc;
			bc.table_name = tname;
			bc.schema_name = schema;
			bc.column_name = t->columns[i].name;
			bc.type = t->columns[i].type;
			bc.table_index = (int)i;
			bc.col_index = (int)i;
			src.cols.push_back(bc);
		}
		src.rows = t->rows;
		src.table_names.push_back(tname);
		return;
	}
	case TRK::Subquery: {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		std::vector<std::vector<Value>> rows;
		materialize_query(eng, tr->query->query, outer, names, types, rows);
		std::string tname = tr->alias.empty() ? "unnamed_subquery" : tr->alias;
		if (!tr->column_aliases.empty()) {
			for (size_t i = 0; i < names.size(); i++) if (i < tr->column_aliases.size()) names[i] = tr->column_aliases[i];
		}
		for (size_t i = 0; i < names.size(); i++) {
			BoundCol bc;
			bc.table_name = tname;
			bc.column_name = names[i];
			bc.type = i < types.size() ? types[i] : LogicalType(TId::UNKNOWN);
			bc.table_index = (int)i;
			bc.col_index = (int)i;
			src.cols.push_back(bc);
		}
		src.rows = rows;
		src.table_names.push_back(tname);
		return;
	}
	case TRK::TableFunc: {
		std::vector<Value> args;
		for (auto &a : tr->using_columns) {
			Scope empty;
			args.push_back(eval_expr(a.get(), empty, eng));
		}
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		std::vector<std::vector<Value>> rows;
		const FuncDef *def = find_function(tr->name);
		if (def && def->kind == FuncKind::Table && def->table_eval) {
			std::string err;
			if (!def->table_eval(args, names, types, rows, err)) {
				if (!err.empty()) throw DuckDBException(DuckDBException::Type::IO, err);
				throw DuckDBException(DuckDBException::Type::CATALOG, "Table Function with name " + tr->name + " does not exist!").with_location(tr->pos, tr->pos);
			}
		} else if (!eng->eval_table_function(tr->name, args, names, types, rows)) {
			std::string sug = suggestion_for(tr->name, kFunctionNames);
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table Function with name " + tr->name + " does not exist!" + (sug.empty() ? "" : "\n" + sug)).with_location(tr->pos, tr->pos);
		}
		std::string tname = tr->alias.empty() ? tr->name : tr->alias;
		if (!tr->column_aliases.empty()) {
			for (size_t i = 0; i < names.size(); i++) if (i < tr->column_aliases.size()) names[i] = tr->column_aliases[i];
		}
		for (size_t i = 0; i < names.size(); i++) {
			BoundCol bc;
			bc.table_name = tname;
			bc.column_name = names[i];
			bc.type = i < types.size() ? types[i] : LogicalType(TId::UNKNOWN);
			bc.table_index = (int)i;
			bc.col_index = (int)i;
			src.cols.push_back(bc);
		}
		src.rows = rows;
		src.table_names.push_back(tname);
		return;
	}
	case TRK::Values: {
		std::string tname = tr->alias.empty() ? "valueslist" : tr->alias;
		size_t ncols = 0;
		for (auto &r : tr->values_rows) ncols = std::max(ncols, r.size());
		for (size_t i = 0; i < ncols; i++) {
			BoundCol bc;
