		std::vector<bool> right_matched(right.rows.size(), false);
		for (auto &l : left.rows) {
			bool matched = false;
			for (size_t j = 0; j < right.rows.size(); j++) {
				std::vector<Value> row = l;
				for (auto &v : right.rows[j]) row.push_back(v);
				bool ok = true;
				if (tr->condition) {
					jscope.row = &row;
					Value c = eval_expr(tr->condition.get(), jscope, eng);
					ok = !c.null && c.as_bool();
				} else if (!tr->using_columns.empty()) {
					jscope.row = &row;
					ok = true;
					for (auto &u : tr->using_columns) {
						int t1 = -1, t2 = -1;
						int i1 = jscope.resolve("", u->column, t1);
						std::vector<int> all = jscope.resolve_all(u->column);
						if (all.size() >= 2) {
							ok = ok && row[all[0]].equals(row[all[1]]);
						}
					}
				}
				if (ok) {
					matched = true;
					right_matched[j] = true;
					out.rows.push_back(row);
				}
			}
			if (!matched && (jt == 1 || jt == 3)) {
				std::vector<Value> row = l;
				for (size_t k = 0; k < right.cols.size(); k++) row.push_back(Value::nullval(right.cols[k].type));
				out.rows.push_back(row);
			}
		}
		if (jt == 2 || jt == 3) {
			for (size_t j = 0; j < right.rows.size(); j++) {
				if (right_matched[j]) continue;
				std::vector<Value> row;
				for (size_t k = 0; k < left.cols.size(); k++) row.push_back(Value::nullval(left.cols[k].type));
				for (auto &v : right.rows[j]) row.push_back(v);
				out.rows.push_back(row);
			}
		}
		src = out;
		return;
	}
	case TRK::CTE: {
		for (auto &t : g_temp_tables) {
			if (iequals(t.name, tr->name)) {
				std::string tname = tr->alias.empty() ? t.name : tr->alias;
				for (size_t i = 0; i < t.table->columns.size(); i++) {
					BoundCol bc;
					bc.table_name = tname;
					bc.column_name = t.table->columns[i].name;
					bc.type = t.table->columns[i].type;
					bc.table_index = (int)i;
					bc.col_index = (int)i;
					src.cols.push_back(bc);
				}
				src.rows = t.table->rows;
				return;
			}
		}
		throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name " + tr->name + " does not exist!").with_location(tr->pos, tr->pos);
	}
	}
}
