static bool type_infer_expr(const Expr *e, const SourceData &src, std::vector<Expr *> &agg_exprs, LogicalType &out) {
	if (!e) return false;
	switch (e->kind) {
	case EK::ColumnRef: {
		if (e->bound_index >= 0 && (size_t)e->bound_index < src.cols.size()) { out = src.cols[e->bound_index].type; return true; }
		for (size_t i = 0; i < src.cols.size(); i++) {
			if (!iequals(src.cols[i].column_name, e->column)) continue;
			if (!e->table.empty() && !iequals(src.cols[i].table_name, e->table)) continue;
			out = src.cols[i].type;
			return true;
		}
		return false;
	}
	case EK::Constant: out = e->value.type; return true;
	case EK::Cast: out = e->type; return true;
	case EK::TableStar: out = LogicalType(TId::UNKNOWN); return false;
	case EK::Star: out = LogicalType(TId::BIGINT); return true;
	case EK::Binary: {
		if (e->args.size() != 2) return false;
		if (e->flags.size() > 0 && e->flags[0]) { out = LogicalType(TId::BOOLEAN); return true; }
		if (e->op == 100 || e->op == 101) { out = LogicalType(TId::BOOLEAN); return true; }
		LogicalType a(TId::UNKNOWN), b(TId::UNKNOWN);
		bool oa = type_infer_expr(e->args[0].get(), src, agg_exprs, a);
		bool ob = type_infer_expr(e->args[1].get(), src, agg_exprs, b);
		if (!oa || !ob) return false;
		out = numeric_op_result(e->op, a, b);
		return out.id != TId::UNKNOWN;
	}
	case EK::Unary: {
		if (e->args.size() != 1) return false;
		if (e->op == 2) { out = LogicalType(TId::BOOLEAN); return true; }
		LogicalType a(TId::UNKNOWN);
		if (!type_infer_expr(e->args[0].get(), src, agg_exprs, a)) return false;
		out = a;
		return true;
	}
	case EK::Func: {
		const FuncDef *def = find_function(e->text);
		if (!def) return false;
		std::vector<LogicalType> ats;
		if (e->is_aggregate) {
			Expr *ae = (e->agg_id >= 0 && e->agg_id < (int)agg_exprs.size()) ? agg_exprs[e->agg_id] : nullptr;
			if (!ae) return false;
			for (auto &a : ae->args) {
				LogicalType at(TId::UNKNOWN);
				type_infer_expr(a.get(), src, agg_exprs, at);
				ats.push_back(at);
			}
			out = def->ret(ats);
			return out.id != TId::UNKNOWN;
		}
		for (auto &a : e->args) {
			LogicalType at(TId::UNKNOWN);
			type_infer_expr(a.get(), src, agg_exprs, at);
			ats.push_back(at);
		}
		out = def->ret(ats);
		return out.id != TId::UNKNOWN;
	}
	case EK::Case: {
		LogicalType t(TId::UNKNOWN);
		for (size_t i = 1; i < e->args.size(); i += 2) {
			LogicalType a(TId::UNKNOWN);
			if (type_infer_expr(e->args[i].get(), src, agg_exprs, a)) {
				if (t.id == TId::UNKNOWN) t = a;
				else if (!(t == a)) t = numeric_op_result(OP_ADD, t, a);
			}
		}
		if (e->args.size() % 2 == 1) {
			LogicalType a(TId::UNKNOWN);
			if (type_infer_expr(e->args.back().get(), src, agg_exprs, a)) {
				if (t.id == TId::UNKNOWN) t = a;
				else if (!(t == a)) t = numeric_op_result(OP_ADD, t, a);
			}
		}
		if (t.id == TId::UNKNOWN) return false;
		out = t;
		return true;
	}
	case EK::In: case EK::Between: case EK::Like: case EK::IsNull: out = LogicalType(TId::BOOLEAN); return true;
	case EK::ListCtor: {
		if (e->op == 10) { out = LogicalType(TId::STRUCT); return true; }
		LogicalType inner(TId::UNKNOWN);
		std::vector<LogicalType> ats;
		for (auto &a : e->args) {
			LogicalType at(TId::UNKNOWN);
			if (type_infer_expr(a.get(), src, agg_exprs, at)) {
				ats.push_back(at);
				if (inner.id == TId::UNKNOWN) inner = at;
				else inner = numeric_op_result(OP_ADD, inner, at);
			} else ats.push_back(LogicalType(TId::UNKNOWN));
		}
		const FuncDef *def = find_function("list_value");
		if (def) out = def->ret(ats);
		else out = LogicalType::list_type(inner);
		return out.id != TId::UNKNOWN;
	}
	case EK::StructCtor: {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		for (auto &a : e->args) {
			LogicalType at(TId::UNKNOWN);
			type_infer_expr(a.get(), src, agg_exprs, at);
			names.push_back(a->text.empty() ? "v" + std::to_string(names.size() + 1) : a->text);
			types.push_back(at);
		}
		out = LogicalType::struct_type(names, types);
		return true;
	}
	case EK::MapCtor: {
		LogicalType k(TId::UNKNOWN), v(TId::UNKNOWN);
		for (size_t i = 0; i < e->args.size(); i++) {
			LogicalType at(TId::UNKNOWN);
			if (type_infer_expr(e->args[i].get(), src, agg_exprs, at) && k.id == TId::UNKNOWN) k = at;
			LogicalType bt(TId::UNKNOWN);
			if (i < e->extra.size() && type_infer_expr(e->extra[i].get(), src, agg_exprs, bt) && v.id == TId::UNKNOWN) v = bt;
		}
		out = LogicalType::map_type(k.id == TId::UNKNOWN ? LogicalType(TId::VARCHAR) : k, v.id == TId::UNKNOWN ? LogicalType(TId::VARCHAR) : v);
		return true;
	}
	case EK::Exists: out = LogicalType(TId::BOOLEAN); return true;
	case EK::Collate: return type_infer_expr(e->args.empty() ? nullptr : e->args[0].get(), src, agg_exprs, out);
	case EK::Window: return type_infer_expr(e->args.empty() ? nullptr : e->args[0].get(), src, agg_exprs, out);
	default: return false;
	}
}

Result Engine::execute(const Statement &st, bool *changed) {
	Result res;
	if (changed) *changed = 0;
	switch (st.kind) {
	case SK::Select: {
		if (!st.query) return res;
		return execute_query(*st.query, nullptr);
	}
	case SK::Insert: {
		auto t = resolve_table(st.name_parts);
		if (!t) {
			std::string nm = st.name_parts.empty() ? "" : st.name_parts.back();
			std::string sug = suggestion_for(nm, kTableNames);
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name " + nm + " does not exist!" + (sug.empty() ? "" : "\n" + sug));
		}
		std::vector<int> colidx;
		if (st.columns.empty()) {
			for (size_t i = 0; i < t->columns.size(); i++) colidx.push_back((int)i);
		} else {
			for (auto &c : st.columns) {
				int idx = t->column_index(c);
				if (idx < 0) throw DuckDBException(DuckDBException::Type::BINDER, "Values were not provided for the following columns: " + c);
				colidx.push_back(idx);
			}
		}
		std::vector<std::vector<Value>> rows;
		if (!st.values_rows.empty()) {
			Scope empty;
			for (auto &vr : st.values_rows) {
				std::vector<Value> row(t->columns.size());
				for (size_t i = 0; i < t->columns.size(); i++) {
					row[i] = t->columns[i].default_value.null ? Value::nullval(t->columns[i].type) : t->columns[i].default_value;
					row[i].type = t->columns[i].type;
				}
				for (size_t i = 0; i < vr.size(); i++) {
					Value v = eval_expr(vr[i].get(), empty, this);
					if (i < colidx.size()) {
						int ci = colidx[i];
						v = do_cast(v, t->columns[ci].type);
						row[ci] = v;
					}
				}
				rows.push_back(row);
			}
		} else if (st.source) {
			Result r = execute_query(*st.source, nullptr);
			for (auto &rrow : r.rows) {
				std::vector<Value> row(t->columns.size());
				for (size_t i = 0; i < t->columns.size(); i++) row[i] = Value::nullval(t->columns[i].type);
				for (size_t i = 0; i < colidx.size() && i < rrow.size(); i++) {
					row[colidx[i]] = do_cast(rrow[i], t->columns[colidx[i]].type);
				}
				rows.push_back(row);
			}
		}
		for (auto &row : rows) {
			for (size_t i = 0; i < row.size(); i++) {
				if (row[i].null && t->columns[i].not_null) {
					throw DuckDBException(DuckDBException::Type::CONSTRAINT, "NOT NULL constraint failed: " + t->name + "." + t->columns[i].name);
				}
			}
		}
		for (auto &row : rows) t->rows.push_back(row);
		if (changed) *changed = (int64_t)rows.size();
		res.is_statement = true;
		res.changed_rows = (int64_t)rows.size();
		return res;
	}
	case SK::Update: {
		auto t = resolve_table(st.name_parts);
		if (!t) {
			std::string nm = st.name_parts.empty() ? "" : st.name_parts.back();
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name " + nm + " does not exist!");
		}
		Scope sc;
		std::vector<BoundCol> cols;
		for (size_t i = 0; i < t->columns.size(); i++) {
			BoundCol bc;
			bc.table_name = t->name;
			bc.column_name = t->columns[i].name;
			bc.type = t->columns[i].type;
			bc.table_index = (int)i;
			bc.col_index = (int)i;
			cols.push_back(bc);
		}
		sc.cols = cols;
		int64_t n = 0;
		for (auto &row : t->rows) {
			sc.row = &row;
			if (st.where) {
				Value c = eval_expr(st.where.get(), sc, this);
				if (c.null || !c.as_bool()) continue;
			}
			std::vector<Value> newrow = row;
			for (auto &a : st.set_assignments) {
				int idx = t->column_index(a.first);
				if (idx < 0) throw DuckDBException(DuckDBException::Type::BINDER, "Referenced column \"" + a.first + "\" not found in FROM clause!");
				Value v = eval_expr(a.second.get(), sc, this);
				newrow[idx] = do_cast(v, t->columns[idx].type);
			}
			row = newrow;
			n++;
		}
		if (changed) *changed = n;
		res.is_statement = true;
		res.changed_rows = n;
		return res;
	}
	case SK::Delete: {
		auto t = resolve_table(st.name_parts);
		if (!t) {
			std::string nm = st.name_parts.empty() ? "" : st.name_parts.back();
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name " + nm + " does not exist!");
		}
		Scope sc;
		std::vector<BoundCol> cols;
		for (size_t i = 0; i < t->columns.size(); i++) {
			BoundCol bc;
			bc.table_name = t->name;
			bc.column_name = t->columns[i].name;
			bc.type = t->columns[i].type;
			bc.table_index = (int)i;
			bc.col_index = (int)i;
			cols.push_back(bc);
		}
		sc.cols = cols;
		std::vector<std::vector<Value>> keep;
		int64_t n = 0;
		for (auto &row : t->rows) {
			sc.row = &row;
			if (st.where) {
				Value c = eval_expr(st.where.get(), sc, this);
				if (c.null || !c.as_bool()) { keep.push_back(row); continue; }
			}
			n++;
		}
		t->rows = keep;
		if (changed) *changed = n;
		res.is_statement = true;
		res.changed_rows = n;
		return res;
	}
	case SK::CreateTable: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		if (db.find_schema(schema) == nullptr) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name " + schema + " does not exist!");
		}
		auto existing = db.find_table(schema, name);
		if (existing) {
			if (st.if_not_exists) return res;
			if (!st.or_replace) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" already exists!");
		}
		auto t = std::make_shared<Table>();
		t->name = name;
		t->schema = schema;
		t->temporary = st.temporary;
		if (st.as_select && st.create_query) {
			Result r = execute_query(*st.create_query, nullptr);
			for (size_t i = 0; i < r.names.size(); i++) {
				Column col;
				col.name = r.names[i];
				col.type = r.types[i];
				t->columns.push_back(col);
			}
			t->rows = r.rows;
		} else {
			for (auto &cd : st.create_columns) {
				Column col;
				col.name = cd.name;
				col.type = cd.type;
				col.not_null = cd.not_null;
				col.primary_key = cd.primary_key;
				col.unique = cd.unique;
				if (cd.default_value) {
					Scope empty;
					col.default_value = eval_expr(cd.default_value.get(), empty, this);
					col.default_value = do_cast(col.default_value, cd.type);
				}
				t->columns.push_back(col);
			}
		}
		add_table(t);
		res.is_statement = true;
		return res;
	}
	case SK::CreateView: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		auto t = std::make_shared<Table>();
		t->name = name;
		t->schema = schema;
		t->is_view = true;
		t->temporary = st.temporary;
		t->view_sql = st.create_sql.empty() ? ("CREATE VIEW " + name + " AS SELECT") : st.create_sql;
		if (st.create_query) {
			Result r = execute_query(*st.create_query, nullptr);
			for (size_t i = 0; i < r.names.size(); i++) {
				Column col;
				col.name = r.names[i];
				col.type = r.types[i];
				t->columns.push_back(col);
			}
		}
		if (db.find_table(schema, name) && !st.or_replace && !st.if_not_exists) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "View with name \"" + name + "\" already exists!");
		}
		add_table(t);
		res.is_statement = true;
		return res;
	}
	case SK::CreateSchema: {
		std::string name = st.table;
		if (db.find_schema(name)) {
			if (!st.if_not_exists) throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name \"" + name + "\" already exists!");
		} else {
			db.schemas.push_back({name, {}});
		}
		res.is_statement = true;
		return res;
	}
	case SK::Drop: {
		if (st.table == "TABLE" || st.table == "VIEW") {
			std::string schema = "main", name;
			if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
			else name = st.name_parts.empty() ? "" : st.name_parts[0];
			auto t = db.find_table(schema, name);
			if (!t) {
				if (!st.if_exists) {
					std::string kind = st.table == "VIEW" ? "View" : "Table";
					throw DuckDBException(DuckDBException::Type::CATALOG, kind + " with name \"" + name + "\" does not exist!");
				}
			} else drop_table(schema, name);
		} else if (st.table == "SCHEMA") {
			std::string name = st.name_parts.empty() ? "" : st.name_parts[0];
			for (size_t i = 0; i < db.schemas.size(); i++) {
				if (iequals(db.schemas[i].name, name)) {
					if (db.schemas[i].name == "main") throw DuckDBException(DuckDBException::Type::CATALOG, "Cannot drop schema \"main\"");
					db.schemas.erase(db.schemas.begin() + i);
					return res;
				}
			}
			if (!st.if_exists) throw DuckDBException(DuckDBException::Type::CATALOG, "Schema with name \"" + name + "\" does not exist!");
		}
		res.is_statement = true;
		return res;
	}
	case SK::Alter: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		auto t = db.find_table(schema, name);
		if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" does not exist!");
		if (st.action == 0) t->name = st.new_name;
		else if (st.action == 1) {
			int idx = t->column_index(st.target_column);
			if (idx < 0) throw DuckDBException(DuckDBException::Type::CATALOG, "Column with name \"" + st.target_column + "\" does not exist!");
			t->columns[idx].name = st.new_name;
		} else if (st.action == 2) {
			Column col;
			col.name = st.create_columns[0].name;
			col.type = st.create_columns[0].type;
			col.not_null = st.create_columns[0].not_null;
			if (st.create_columns[0].default_value) {
				Scope empty;
				col.default_value = eval_expr(st.create_columns[0].default_value.get(), empty, this);
			} else col.default_value = Value::nullval(col.type);
			t->columns.push_back(col);
			for (auto &row : t->rows) row.push_back(col.default_value.null ? Value::nullval(col.type) : col.default_value);
		} else if (st.action == 3) {
			int idx = t->column_index(st.target_column);
			if (idx < 0) {
				if (!st.if_exists) throw DuckDBException(DuckDBException::Type::CATALOG, "Column with name \"" + st.target_column + "\" does not exist!");
			} else {
				t->columns.erase(t->columns.begin() + idx);
				for (auto &row : t->rows) if (idx < (int)row.size()) row.erase(row.begin() + idx);
			}
		} else if (st.action == 4) {
			int idx = t->column_index(st.target_column);
			if (idx >= 0) {
				t->columns[idx].type = st.create_columns[0].type;
				for (auto &row : t->rows) row[idx] = do_cast(row[idx], st.create_columns[0].type);
			}
		}
		res.is_statement = true;
		return res;
	}
	case SK::Truncate: {
		std::string schema = "main", name;
		if (st.name_parts.size() >= 2) { schema = st.name_parts[st.name_parts.size() - 2]; name = st.name_parts.back(); }
		else name = st.name_parts.empty() ? "" : st.name_parts[0];
		auto t = db.find_table(schema, name);
		if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" does not exist!");
		t->rows.clear();
		res.is_statement = true;
		return res;
	}
	case SK::Transaction: res.is_statement = true; return res;
	case SK::Set: {
		std::string name;
		for (auto &s : st.setting_name) { if (!name.empty()) name += "."; name += to_lower(s); }
		std::string value;
		if (st.setting_value) value = st.setting_value->text;
		if (st.pragma_expr) value = st.pragma_expr->text;
		set_setting_string(name, value);
		res.is_statement = true;
		return res;
	}
	case SK::Pragma: {
		std::string name = to_lower(st.pragma_name);
		if (name == "table_info") {
			std::string tname = st.pragma_args.empty() ? std::string("") : st.pragma_args[0];
			auto t = db.find_table(tname);
			res.names = {"cid", "name", "type", "notnull", "dflt_value", "pk"};
			res.types = {LogicalType(TId::INTEGER), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::BOOLEAN), LogicalType(TId::VARCHAR), LogicalType(TId::BOOLEAN)};
			if (t) {
				for (size_t i = 0; i < t->columns.size(); i++) {
					std::vector<Value> row;
					row.push_back(Value::intv((int64_t)i, TId::INTEGER));
					row.push_back(Value::str(t->columns[i].name));
					row.push_back(Value::str(t->columns[i].type.sql_name()));
					row.push_back(Value::boolean(t->columns[i].not_null));
					row.push_back(t->columns[i].default_value.null ? Value::nullval(LogicalType(TId::VARCHAR)) : Value::str(t->columns[i].default_value.to_string()));
					row.push_back(Value::boolean(t->columns[i].primary_key));
					res.rows.push_back(row);
				}
			}
			return res;
		}
		res.is_statement = true;
		return res;
	}
	case SK::Explain: {
		res.names = {"explain_key", "explain_value"};
		res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
		res.rows.push_back({Value::str("plan"), Value::str("")});
		return res;
	}
	case SK::Show: {
		if (iequals(st.table, "TABLES") || st.table.empty()) {
			res.names = {"schema_name", "table_name"};
			res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
			for (auto &t : all_tables()) {
				if (t->is_view) continue;
				res.rows.push_back({Value::str(t->schema), Value::str(t->name)});
			}
			return res;
		}
		if (!st.name_parts.empty()) {
			auto t = db.find_table(st.name_parts.back());
			if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + st.name_parts.back() + "\" does not exist!");
			res.names = {"column_name", "column_type", "null", "key", "default", "extra"};
			res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
			for (auto &c : t->columns) {
				res.rows.push_back({Value::str(c.name), Value::str(c.type.sql_name()), Value::str(c.not_null ? "NO" : "YES"), Value::str(c.primary_key ? "PRI" : ""), Value::str(""), Value::str("")});
			}
			return res;
		}
		res.is_statement = true;
		return res;
	}
	case SK::Describe: {
		std::string name = st.name_parts.empty() ? std::string("") : st.name_parts.back();
		auto t = db.find_table(name);
		if (!t) throw DuckDBException(DuckDBException::Type::CATALOG, "Table with name \"" + name + "\" does not exist!");
		res.names = {"column_name", "column_type", "null", "key", "default", "extra"};
		res.types = {LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR), LogicalType(TId::VARCHAR)};
		for (auto &c : t->columns) {
			res.rows.push_back({Value::str(c.name), Value::str(c.type.sql_name()), Value::str(c.not_null ? "NO" : "YES"), Value::str(c.primary_key ? "PRI" : ""), Value::str(""), Value::str("")});
		}
		return res;
	}
	case SK::Call: {
		std::vector<std::string> names;
		std::vector<LogicalType> types;
		std::vector<std::vector<Value>> rows;
		std::vector<Value> args;
		Scope empty;
		for (auto &a : st.call_args) args.push_back(eval_expr(a.get(), empty, this));
		if (!eval_table_function(st.call_name, args, names, types, rows)) {
			throw DuckDBException(DuckDBException::Type::CATALOG, "Table Function with name " + st.call_name + " does not exist!");
		}
		res.names = names;
		res.types = types;
		res.rows = rows;
		return res;
	}
	case SK::Copy: case SK::Attach: case SK::Detach: case SK::Vacuum: {
		res.is_statement = true;
		return res;
	}
	default: return res;
	}
}

